insert into public.exercises (slug, name, name_en, category, muscles, secondary_muscles, equipment, level, description, instructions, images, featured) values
('3_4_Sit-Up','3/4 Sit-Up','3/4 Sit-Up','Force','Abdominaux',null,'Poids du corps','Débutant',null,array['Lie down on the floor and secure your feet. Your legs should be bent at the knees.','Place your hands behind or to the side of your head. You will begin with your back on the ground. This will be your starting position.','Flex your hips and spine to raise your torso toward your knees.','At the top of the contraction your torso should be perpendicular to the ground. Reverse the motion, going only ¾ of the way down.','Repeat for the recommended amount of repetitions.']::text[],array['3_4_Sit-Up/0.jpg','3_4_Sit-Up/1.jpg']::text[],false),
('90_90_Hamstring','90/90 Hamstring','90/90 Hamstring','Mobilité','Ischio-jambiers','Mollets','Poids du corps','Débutant',null,array['Lie on your back, with one leg extended straight out.','With the other leg, bend the hip and knee to 90 degrees. You may brace your leg with your hands if necessary. This will be your starting position.','Extend your leg straight into the air, pausing briefly at the top. Return the leg to the starting position.','Repeat for 10-20 repetitions, and then switch to the other leg.']::text[],array['90_90_Hamstring/0.jpg','90_90_Hamstring/1.jpg']::text[],false),
('Ab_Crunch_Machine','Ab Crunch Machine','Ab Crunch Machine','Force','Abdominaux',null,'Machine','Intermédiaire',null,array['Select a light resistance and sit down on the ab machine placing your feet under the pads provided and grabbing the top handles. Your arms should be bent at a 90 degree angle as you rest the triceps on the pads provided. This will be your starting position.','At the same time, begin to lift the legs up as you crunch your upper torso. Breathe out as you perform this movement. Tip: Be sure to use a slow and controlled motion. Concentrate on using your abs to move the weight while relaxing your legs and feet.','After a second pause, slowly return to the starting position as you breathe in.','Repeat the movement for the prescribed amount of repetitions.']::text[],array['Ab_Crunch_Machine/0.jpg','Ab_Crunch_Machine/1.jpg']::text[],false),
('Ab_Roller','Roue abdominale','Ab Roller','Force','Abdominaux','Épaules','Autre','Intermédiaire','À genoux, roule vers l''avant en gardant le dos neutre puis reviens en contractant les abdos.',array['Hold the Ab Roller with both hands and kneel on the floor.','Now place the ab roller on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.','Slowly roll the ab roller straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement.','After a pause at the stretched position, start pulling yourself back to the starting position as you breathe out. Tip: Go slowly and keep your abs tight at all times.']::text[],array['Ab_Roller/0.jpg','Ab_Roller/1.jpg']::text[],true),
('Adductor','Adductor','Adductor','Mobilité','Adducteurs',null,'Rouleau','Intermédiaire',null,array['Lie face down with one leg on a foam roll.','Rotate the leg so that the foam roll contacts against your inner thigh. Shift as much weight onto the foam roll as can be tolerated.','While trying to relax the muscles if the inner thigh, roll over the foam between your hip and knee, holding points of tension for 10-30 seconds. Repeat with the other leg.']::text[],array['Adductor/0.jpg','Adductor/1.jpg']::text[],false),
('Adductor_Groin','Adductor/Groin','Adductor/Groin','Mobilité','Adducteurs',null,null,'Intermédiaire',null,array['Lie on your back with your feet raised towards the ceiling.','Have your partner hold your feet or ankles. Abduct your legs as far as you can. This will be your starting position.','Attempt to squeeze your legs together for 10 or more seconds, while your partner prevents you from doing so.','Now, relax the muscles in your legs as your partner pushes your feet apart, stretching as far as is comfortable for you. Be sure to let your partner know when the stretch is adequate to prevent overstretching or injury.']::text[],array['Adductor_Groin/0.jpg','Adductor_Groin/1.jpg']::text[],false),
('Advanced_Kettlebell_Windmill','Advanced Kettlebell Windmill','Advanced Kettlebell Windmill','Force','Abdominaux','Fessiers, Ischio-jambiers, Épaules','Kettlebell','Intermédiaire',null,array['Clean and press a kettlebell overhead with one arm.','Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Keep the non-working arm behind your back and turn your feet out at a forty-five degree angle from the arm with the kettlebell.','Lower yourself as far as possible.','Pause for a second and reverse the motion back to the starting position.']::text[],array['Advanced_Kettlebell_Windmill/0.jpg','Advanced_Kettlebell_Windmill/1.jpg']::text[],false),
('Air_Bike','Air bike (crunch vélo)','Air Bike','Force','Abdominaux',null,'Poids du corps','Débutant','Allongé, ramène coude vers genou opposé en pédalant dans le vide.',array['Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put your hands beside your head. Be careful however to not strain with the neck as you perform it. Now lift your shoulders into the crunch position.','Bring knees up to where they are perpendicular to the floor, with your lower legs parallel to the floor. This will be your starting position.','Now simultaneously, slowly go through a cycle pedal motion kicking forward with the right leg and bringing in the knee of the left leg. Bring your right elbow close to your left knee by crunching to the side, as you breathe out.','Go back to the initial position as you breathe in.','Crunch to the opposite side as you cycle your legs and bring closer your left elbow to your right knee and exhale.','Continue alternating in this manner until all of the recommended repetitions for each side have been completed.']::text[],array['Air_Bike/0.jpg','Air_Bike/1.jpg']::text[],true),
('All_Fours_Quad_Stretch','All Fours Quad Stretch','All Fours Quad Stretch','Mobilité','Quadriceps','Quadriceps','Poids du corps','Intermédiaire',null,array['Start off on your hands and knees, then lift your leg off the floor and hold the foot with your hand.','Use your hand to hold the foot or ankle, keeping the knee fully flexed, stretching the quadriceps and hip flexors.','Focus on extending your hips, thrusting them towards the floor. Hold for 10-20 seconds and then switch sides.']::text[],array['All_Fours_Quad_Stretch/0.jpg','All_Fours_Quad_Stretch/1.jpg']::text[],false),
('Alternate_Hammer_Curl','Alternate Hammer Curl','Alternate Hammer Curl','Force','Biceps','Avant-bras','Haltères','Débutant',null,array['Stand up with your torso upright and a dumbbell in each hand being held at arms length. The elbows should be close to the torso.','The palms of the hands should be facing your torso. This will be your starting position.','While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.','Slowly begin to bring the dumbbells back to starting position as your breathe in.','Repeat the movement with the left hand. This equals one repetition.','Continue alternating in this manner for the recommended amount of repetitions.']::text[],array['Alternate_Hammer_Curl/0.jpg','Alternate_Hammer_Curl/1.jpg']::text[],false),
('Alternate_Heel_Touchers','Alternate Heel Touchers','Alternate Heel Touchers','Force','Abdominaux',null,'Poids du corps','Débutant',null,array['Lie on the floor with the knees bent and the feet on the floor around 18-24 inches apart. Your arms should be extended by your side. This will be your starting position.','Crunch over your torso forward and up about 3-4 inches to the right side and touch your right heel as you hold the contraction for a second. Exhale while performing this movement.','Now go back slowly to the starting position as you inhale.','Now crunch over your torso forward and up around 3-4 inches to the left side and touch your left heel as you hold the contraction for a second. Exhale while performing this movement and then go back to the starting position as you inhale. Now that both heels have been touched, that is considered 1 repetition.','Continue alternating sides in this manner until all prescribed repetitions are done.']::text[],array['Alternate_Heel_Touchers/0.jpg','Alternate_Heel_Touchers/1.jpg']::text[],false),
('Alternate_Incline_Dumbbell_Curl','Alternate Incline Dumbbell Curl','Alternate Incline Dumbbell Curl','Force','Biceps','Avant-bras','Haltères','Débutant',null,array['Sit down on an incline bench with a dumbbell in each hand being held at arms length. Tip: Keep the elbows close to the torso.This will be your starting position.','While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. As you do so, rotate the hand so that the palm is facing up. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.','Slowly begin to bring the dumbbell back to starting position as your breathe in.','Repeat the movement with the left hand. This equals one repetition.','Continue alternating in this manner for the recommended amount of repetitions.']::text[],array['Alternate_Incline_Dumbbell_Curl/0.jpg','Alternate_Incline_Dumbbell_Curl/1.jpg']::text[],false),
('Alternate_Leg_Diagonal_Bound','Alternate Leg Diagonal Bound','Alternate Leg Diagonal Bound','Explosivité','Quadriceps','Abducteurs, Adducteurs, Mollets, Fessiers, Ischio-jambiers',null,'Débutant',null,array['Assume a comfortable stance with one foot slightly in front of the other.','Begin by pushing off with the front leg, driving the opposite knee forward and as high as possible before landing. Attempt to cover as much distance to each side with each bound.','It may help to use a line on the ground to guage distance from side to side.','Repeat the sequence with the other leg.']::text[],array['Alternate_Leg_Diagonal_Bound/0.jpg','Alternate_Leg_Diagonal_Bound/1.jpg']::text[],false),
('Alternating_Cable_Shoulder_Press','Alternating Cable Shoulder Press','Alternating Cable Shoulder Press','Force','Épaules','Triceps','Poulie','Débutant',null,array['Move the cables to the bottom of the tower and select an appropriate weight.','Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position.','Keeping your head and chest up, extend through the elbow to press one side directly over head.','After pausing at the top, return to the starting position and repeat on the opposite side.']::text[],array['Alternating_Cable_Shoulder_Press/0.jpg','Alternating_Cable_Shoulder_Press/1.jpg']::text[],false),
('Alternating_Deltoid_Raise','Alternating Deltoid Raise','Alternating Deltoid Raise','Force','Épaules',null,'Haltères','Débutant',null,array['In a standing position, hold a pair of dumbbells at your side.','Keeping your elbows slightly bent, raise the weights directly in front of you to shoulder height, avoiding any swinging or cheating.','Return the weights to your side.','On the next repetition, raise the weights laterally, raising them out to your side to about shoulder height.','Return the weights to the starting position and continue alternating to the front and side.']::text[],array['Alternating_Deltoid_Raise/0.jpg','Alternating_Deltoid_Raise/1.jpg']::text[],false),
('Alternating_Floor_Press','Alternating Floor Press','Alternating Floor Press','Force','Pectoraux','Abdominaux, Épaules, Triceps','Kettlebell','Débutant',null,array['Lie on the floor with two kettlebells next to your shoulders.','Position one in place on your chest and then the other, gripping the kettlebells on the handle with the palms facing forward.','Extend both arms, so that the kettlebells are being held above your chest. Lower one kettlebell, bringing it to your chest and turn the wrist in the direction of the locked out kettlebell.','Raise the kettlebell and repeat on the opposite side.']::text[],array['Alternating_Floor_Press/0.jpg','Alternating_Floor_Press/1.jpg']::text[],false),
('Alternating_Hang_Clean','Alternating Hang Clean','Alternating Hang Clean','Force','Ischio-jambiers','Biceps, Mollets, Avant-bras, Fessiers, Lombaires, Trapèzes','Kettlebell','Intermédiaire',null,array['Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead.','Clean one kettlebell to your shoulder and hold on to the other kettlebell in a hanging position. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so.','Lower the cleaned kettlebell to a hanging position and clean the alternate kettlebell. Repeat.']::text[],array['Alternating_Hang_Clean/0.jpg','Alternating_Hang_Clean/1.jpg']::text[],false),
('Alternating_Kettlebell_Press','Alternating Kettlebell Press','Alternating Kettlebell Press','Force','Épaules','Triceps','Kettlebell','Intermédiaire',null,array['Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so.','Press one directly overhead by extending through the elbow, turning it so the palm faces forward while holding the other kettlebell stationary .','Lower the pressed kettlebell to the starting position and immediately press with your other arm.']::text[],array['Alternating_Kettlebell_Press/0.jpg','Alternating_Kettlebell_Press/1.jpg']::text[],false),
('Alternating_Kettlebell_Row','Alternating Kettlebell Row','Alternating Kettlebell Row','Force','Haut du dos','Biceps, Dorsaux','Kettlebell','Intermédiaire',null,array['Place two kettlebells in front of your feet. Bend your knees slightly and push your butt out as much as possible. As you bend over to get into the starting position grab both kettlebells by the handles.','Pull one kettlebell off of the floor while holding on to the other kettlebell. Retract the shoulder blade of the working side, as you flex the elbow, drawing the kettlebell towards your stomach or rib cage.','Lower the kettlebell in the working arm and repeat with your other arm.']::text[],array['Alternating_Kettlebell_Row/0.jpg','Alternating_Kettlebell_Row/1.jpg']::text[],false),
('Alternating_Renegade_Row','Alternating Renegade Row','Alternating Renegade Row','Force','Haut du dos','Abdominaux, Biceps, Pectoraux, Dorsaux, Triceps','Kettlebell','Avancé',null,array['Place two kettlebells on the floor about shoulder width apart. Position yourself on your toes and your hands as though you were doing a pushup, with the body straight and extended. Use the handles of the kettlebells to support your upper body. You may need to position your feet wide for support.','Push one kettlebell into the floor and row the other kettlebell, retracting the shoulder blade of the working side as you flex the elbow, pulling it to your side.','Then lower the kettlebell to the floor and begin the kettlebell in the opposite hand. Repeat for several reps.']::text[],array['Alternating_Renegade_Row/0.jpg','Alternating_Renegade_Row/1.jpg']::text[],false),
('Ankle_Circles','Ankle Circles','Ankle Circles','Mobilité','Mollets',null,null,'Débutant',null,array['Use a sturdy object like a squat rack to hold yourself.','Lift the right leg in the air (just around 2 inches from the floor) and perform a circular motion with the big toe. Pretend that you are drawing a big circle with it. Tip: One circle equals 1 repetition. Breathe normally as you perform the movement.','When you are done with the right foot, then repeat with the left leg.']::text[],array['Ankle_Circles/0.jpg','Ankle_Circles/1.jpg']::text[],false),
('Ankle_On_The_Knee','Ankle On The Knee','Ankle On The Knee','Mobilité','Fessiers',null,null,'Débutant',null,array['From a lying position, bend your knees and keep your feet on the floor.','Place your ankle of one foot on your opposite knee.','Grasp the thigh or knee of the bottom leg and pull both of your legs into the chest. Relax your neck and shoulders. Hold for 10-20 seconds and then switch sides.']::text[],array['Ankle_On_The_Knee/0.jpg','Ankle_On_The_Knee/1.jpg']::text[],false),
('Anterior_Tibialis-SMR','Anterior Tibialis-SMR','Anterior Tibialis-SMR','Mobilité','Mollets',null,'Autre','Intermédiaire',null,array['Begin seated on the ground with your legs bent and your feet on the floor.','Using a Muscle Roller or a rolling pin, apply pressure to the muscles on the outside of your shins. Work from just below the knee to above the ankle, pausing at points of tension for 10-30 seconds. Repeat on the other leg.']::text[],array['Anterior_Tibialis-SMR/0.jpg','Anterior_Tibialis-SMR/1.jpg']::text[],false),
('Anti-Gravity_Press','Anti-Gravity Press','Anti-Gravity Press','Force','Épaules','Haut du dos, Trapèzes, Triceps','Barre','Débutant',null,array['Place a bar on the ground behind the head of an incline bench.','Lay on the bench face down. With a pronated grip, pick the barbell up from the floor. Flex the elbows, performing a reverse curl to bring the bar near your chest. This will be your starting position.','To begin, press the barbell out in front of your head by extending your elbows. Keep your arms parallel to the ground throughout the movement.','Return to the starting position and repeat to complete the set.']::text[],array['Anti-Gravity_Press/0.jpg','Anti-Gravity_Press/1.jpg']::text[],false),
('Arm_Circles','Cercles de bras','Arm Circles','Mobilité','Épaules','Trapèzes',null,'Débutant','Bras tendus sur les côtés, fais des cercles de plus en plus grands.',array['Stand up and extend your arms straight out by the sides. The arms should be parallel to the floor and perpendicular (90-degree angle) to your torso. This will be your starting position.','Slowly start to make circles of about 1 foot in diameter with each outstretched arm. Breathe normally as you perform the movement.','Continue the circular motion of the outstretched arms for about ten seconds. Then reverse the movement, going the opposite direction.']::text[],array['Arm_Circles/0.jpg','Arm_Circles/1.jpg']::text[],true),
('Arnold_Dumbbell_Press','Développé Arnold','Arnold Dumbbell Press','Force','Épaules','Triceps','Haltères','Intermédiaire','Haltères devant le visage paumes vers toi, pousse en tournant les poignets vers l''avant.',array['Sit on an exercise bench with back support and hold two dumbbells in front of you at about upper chest level with your palms facing your body and your elbows bent. Tip: Your arms should be next to your torso. The starting position should look like the contracted portion of a dumbbell curl.','Now to perform the movement, raise the dumbbells as you rotate the palms of your hands until they are facing forward.','Continue lifting the dumbbells until your arms are extended above you in straight arm position. Breathe out as you perform this portion of the movement.','After a second pause at the top, begin to lower the dumbbells to the original position by rotating the palms of your hands towards you. Tip: The left arm will be rotated in a counter clockwise manner while the right one will be rotated clockwise. Breathe in as you perform this portion of the movement.','Repeat for the recommended amount of repetitions.']::text[],array['Arnold_Dumbbell_Press/0.jpg','Arnold_Dumbbell_Press/1.jpg']::text[],true),
('Around_The_Worlds','Around The Worlds','Around The Worlds','Force','Pectoraux','Épaules','Haltères','Intermédiaire',null,array['Lay down on a flat bench holding a dumbbell in each hand with the palms of the hands facing towards the ceiling. Tip: Your arms should be parallel to the floor and next to your thighs. To avoid injury, make sure that you keep your elbows slightly bent. This will be your starting position.','Now move the dumbbells by creating a semi-circle as you displace them from the initial position to over the head. All of the movement should happen with the arms parallel to the floor at all times. Breathe in as you perform this portion of the movement.','Reverse the movement to return the weight to the starting position as you exhale.']::text[],array['Around_The_Worlds/0.jpg','Around_The_Worlds/1.jpg']::text[],false),
('Atlas_Stone_Trainer','Atlas Stone Trainer','Atlas Stone Trainer','Strongman','Lombaires','Biceps, Avant-bras, Fessiers, Ischio-jambiers, Quadriceps','Autre','Intermédiaire',null,array['This trainer is effective for developing Atlas Stone strength for those who don''t have access to stones, and are typically made from bar ends or heavy pipe.','Begin by loading the desired weight onto the bar. Straddle the weight, wrapping your arms around the implement, bending at the hips.','Begin by pulling the weight up past the knees, extending through the hips. As the weight clears the knees, it can be lapped by resting it on your thighs and sitting back, hugging it tightly to your chest.','Finish the movement by extending through your hips and knees to raise the weight as high as possible. The weight can be returned to the lap or to the ground for successive repetitions.']::text[],array['Atlas_Stone_Trainer/0.jpg','Atlas_Stone_Trainer/1.jpg']::text[],false),
('Atlas_Stones','Atlas Stones','Atlas Stones','Strongman','Lombaires','Abdominaux, Adducteurs, Biceps, Mollets, Avant-bras, Fessiers, Ischio-jambiers, Haut du dos, Quadriceps, Trapèzes','Autre','Avancé',null,array['Begin with the atlas stone between your feet. Bend at the hips to wrap your arms vertically around the Atlas Stone, attempting to get your fingers underneath the stone. Many stones will have a small flat portion on the bottom, which will make the stone easier to hold.','Pulling the stone into your torso, drive through the back half of your feet to pull the stone from the ground.','As the stone passes the knees, lap it by sitting backward, pulling the stone on top of your thighs.','Sit low, getting the stone high onto your chest as you change your grip to reach over the stone. Stand, driving through with your hips. Close distance to the loading platform, and lean back, extending the hips to get the stone as high as possible.']::text[],array['Atlas_Stones/0.jpg','Atlas_Stones/1.jpg']::text[],false),
('Axle_Deadlift','Axle Deadlift','Axle Deadlift','Strongman','Lombaires','Avant-bras, Fessiers, Ischio-jambiers, Haut du dos, Quadriceps, Trapèzes','Autre','Intermédiaire',null,array['Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an over/under grip.','With your feet and your grip set, take a big breath and then lower your hips and flex the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward.','After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.','Lower the bar by bending at the hips and guiding it to the floor.']::text[],array['Axle_Deadlift/0.jpg','Axle_Deadlift/1.jpg']::text[],false),
('Back_Flyes_-_With_Bands','Back Flyes - With Bands','Back Flyes - With Bands','Force','Épaules','Haut du dos, Triceps','Élastiques','Débutant',null,array['Run a band around a stationary post like that of a squat rack.','Grab the band by the handles and stand back so that the tension in the band rises.','Extend and lift the arms straight in front of you. Tip: Your arms should be straight and parallel to the floor while perpendicular to your torso. Your feet should be firmly planted on the floor spread at shoulder width. This will be your starting position.','As you exhale, move your arms to the sides and back. Keep your arms extended and parallel to the floor. Continue the movement until the arms are extended to your sides.','After a pause, go back to the original position as you inhale.','Repeat for the recommended amount of repetitions.']::text[],array['Back_Flyes_-_With_Bands/0.jpg','Back_Flyes_-_With_Bands/1.jpg']::text[],false),
('Backward_Drag','Backward Drag','Backward Drag','Strongman','Quadriceps','Mollets, Avant-bras, Fessiers, Ischio-jambiers, Lombaires','Autre','Débutant',null,array['Load a sled with the desired weight, attaching a rope or straps to the sled that you can hold onto.','Begin the exercise by moving backwards for a given distance. Leaning back, extend through the legs for short steps to move as quickly as possible.']::text[],array['Backward_Drag/0.jpg','Backward_Drag/1.jpg']::text[],false),
('Backward_Medicine_Ball_Throw','Backward Medicine Ball Throw','Backward Medicine Ball Throw','Explosivité','Épaules',null,'Médecine-ball','Débutant',null,array['This exercise is best done with a partner. If you lack a partner, the ball can be thrown and retrieved or thrown against a wall.','Begin standing a few meters in front of your partner, both facing the same direction. Begin holding the ball between your legs.','Squat down and then forcefully reverse direction, coming to full extension and you toss the ball over your head to your partner.','Your partner can then roll the ball back to you. Repeat for the desired number of repetitions.']::text[],array['Backward_Medicine_Ball_Throw/0.jpg','Backward_Medicine_Ball_Throw/1.jpg']::text[],false),
('Balance_Board','Balance Board','Balance Board','Force','Mollets','Ischio-jambiers, Quadriceps','Autre','Débutant',null,array['Place a balance board in front of you.','Stand up on it and try to balance yourself.','Hold the balance for as long as desired.']::text[],array['Balance_Board/0.jpg','Balance_Board/1.jpg']::text[],false),
('Ball_Leg_Curl','Ball Leg Curl','Ball Leg Curl','Force','Ischio-jambiers','Mollets, Fessiers','Swiss ball','Débutant',null,array['Begin on the floor laying on your back with your feet on top of the ball.','Position the ball so that when your legs are extended your ankles are on top of the ball. This will be your starting position.','Raise your hips off of the ground, keeping your weight on the shoulder blades and your feet.','Flex the knees, pulling the ball as close to you as you can, contracting the hamstrings.','After a brief pause, return to the starting position.']::text[],array['Ball_Leg_Curl/0.jpg','Ball_Leg_Curl/1.jpg']::text[],false),
('Band_Assisted_Pull-Up','Tractions assistées élastique','Band Assisted Pull-Up','Force','Dorsaux','Abdominaux, Avant-bras, Haut du dos','Autre','Débutant','Genou ou pied dans un élastique accroché à la barre. Monte le menton au-dessus de la barre.',array['Choke the band around the center of the pullup bar. You can use different bands to provide varying levels of assistance.','Pull the end of the band down, and place one bent knee into the loop, ensuring it won''t slip out. Take a medium to wide grip on the bar. This will be your starting position.','Pull yourself upward by contracting the lats as you flex the elbow. The elbow should be driven to your side. Pull to the front, attempting to get your chin over the bar. Avoid swinging or jerking movements.','After a brief pause, return to the starting position.']::text[],array['Band_Assisted_Pull-Up/0.jpg','Band_Assisted_Pull-Up/1.jpg']::text[],true),
('Band_Good_Morning','Band Good Morning','Band Good Morning','Force','Ischio-jambiers','Fessiers, Lombaires','Élastiques','Débutant',null,array['Using a 41 inch band, stand on one end, spreading your feet a small amount. Bend at the hips to loop the end of the band behind your neck. This will be your starting position.','Keeping your legs straight, extend through the hips to come to a near vertical position.','Ensure that you do not round your back as you go down back to the starting position.']::text[],array['Band_Good_Morning/0.jpg','Band_Good_Morning/1.jpg']::text[],false),
('Band_Good_Morning_Pull_Through','Band Good Morning (Pull Through)','Band Good Morning (Pull Through)','Force','Ischio-jambiers','Fessiers, Lombaires','Élastiques','Débutant',null,array['Loop the band around a post. Standing a little ways away, loop the opposite end around the neck. Your hands can help hold the band in position.','Begin by bending at the hips, getting your butt back as far as possible. Keep your back flat and bend forward to about 90 degrees. Your knees should be only slightly bent.','Return to the starting position be driving through with the hips to come back to a standing position.']::text[],array['Band_Good_Morning_Pull_Through/0.jpg','Band_Good_Morning_Pull_Through/1.jpg']::text[],false),
('Band_Hip_Adductions','Band Hip Adductions','Band Hip Adductions','Force','Adducteurs',null,'Élastiques','Débutant',null,array['Anchor a band around a solid post or other object.','Stand with your left side to the post, and put your right foot through the band, getting it around the ankle.','Stand up straight and hold onto the post if needed. This will be your starting position.','Keeping the knee straight, raise your right legs out to the side as far as you can.','Return to the starting position and repeat for the desired rep count.','Switch sides.']::text[],array['Band_Hip_Adductions/0.jpg','Band_Hip_Adductions/1.jpg']::text[],false),
('Band_Pull_Apart','Band pull apart','Band Pull Apart','Force','Épaules','Haut du dos, Trapèzes','Élastiques','Débutant','Élastique tendu devant toi, écarte les bras jusqu''à la poitrine en serrant les omoplates.',array['Begin with your arms extended straight out in front of you, holding the band with both hands.','Initiate the movement by performing a reverse fly motion, moving your hands out laterally to your sides.','Keep your elbows extended as you perform the movement, bringing the band to your chest. Ensure that you keep your shoulders back during the exercise.','Pause as you complete the movement, returning to the starting position under control.']::text[],array['Band_Pull_Apart/0.jpg','Band_Pull_Apart/1.jpg']::text[],true),
('Band_Skull_Crusher','Band Skull Crusher','Band Skull Crusher','Force','Triceps',null,'Élastiques','Débutant',null,array['Secure a band to the base of a rack or the bench. Lay on the bench so that the band is lined up with your head.','Take hold of the band, raising your elbows so that the upper arm is perpendicular to the floor. With the elbow flexed, the band should be above your head. This will be your starting position.','Extend through the elbow to straighten your arm, keeping your upper arm in place. Pause at the top of the motion, and return to the starting position.']::text[],array['Band_Skull_Crusher/0.jpg','Band_Skull_Crusher/1.jpg']::text[],false),
('Barbell_Ab_Rollout','Barbell Ab Rollout','Barbell Ab Rollout','Force','Abdominaux','Lombaires, Épaules','Barre','Intermédiaire',null,array['For this exercise you will need to get into a pushup position, but instead of having your hands of the floor, you will be grabbing on to an Olympic barbell (loaded with 5-10 lbs on each side) instead. This will be your starting position.','While keeping a slight arch on your back, lift your hips and roll the barbell towards your feet as you exhale. Tip: As you perform the movement, your glutes should be coming up, you should be keeping the abs tight and should maintain your back posture at all times. Also your arms should be staying perpendicular to the floor throughout the movement. If you don''t, you will work out your shoulders and back more than the abs.','After a second contraction at the top, start to roll the barbell back forward to the starting position slowly as you inhale.','Repeat for the recommended amount of repetitions.']::text[],array['Barbell_Ab_Rollout/0.jpg','Barbell_Ab_Rollout/1.jpg']::text[],false),
('Barbell_Ab_Rollout_-_On_Knees','Barbell Ab Rollout - On Knees','Barbell Ab Rollout - On Knees','Force','Abdominaux','Lombaires, Épaules','Barre','Avancé',null,array['Hold an Olympic barbell loaded with 5-10lbs on each side and kneel on the floor.','Now place the barbell on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.','Slowly roll the barbell straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement.','After a second pause at the stretched position, start pulling yourself back to the starting position as you breathe out. Tip: Go slowly and keep your abs tight at all times.']::text[],array['Barbell_Ab_Rollout_-_On_Knees/0.jpg','Barbell_Ab_Rollout_-_On_Knees/1.jpg']::text[],false),
('Barbell_Bench_Press_-_Medium_Grip','Développé couché barre','Barbell Bench Press - Medium Grip','Force','Pectoraux','Épaules, Triceps','Barre','Débutant','Omoplates serrées, pieds au sol. Descends la barre au milieu des pectoraux puis pousse jusqu''à bras tendus.',array['Lie back on a flat bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.','From the starting position, breathe in and begin coming down slowly until the bar touches your middle chest.','After a brief pause, push the bar back to the starting position as you breathe out. Focus on pushing the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position at the top of the motion, hold for a second and then start coming down slowly again. Tip: Ideally, lowering the weight should take about twice as long as raising it.','Repeat the movement for the prescribed amount of repetitions.','When you are done, place the bar back in the rack.']::text[],array['Barbell_Bench_Press_-_Medium_Grip/0.jpg','Barbell_Bench_Press_-_Medium_Grip/1.jpg']::text[],true),
('Barbell_Curl','Curl barre','Barbell Curl','Force','Biceps','Avant-bras','Barre','Débutant','Coudes collés au corps, monte la barre vers les épaules puis redescends lentement.',array['Stand up with your torso upright while holding a barbell at a shoulder-width grip. The palm of your hands should be facing forward and the elbows should be close to the torso. This will be your starting position.','While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.','Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.','Slowly begin to bring the bar back to starting position as your breathe in.','Repeat for the recommended amount of repetitions.']::text[],array['Barbell_Curl/0.jpg','Barbell_Curl/1.jpg']::text[],true),
('Barbell_Curls_Lying_Against_An_Incline','Barbell Curls Lying Against An Incline','Barbell Curls Lying Against An Incline','Force','Biceps',null,'Barre','Débutant',null,array['Lie against an incline bench, with your arms holding a barbell and hanging down in a horizontal line. This will be your starting position.','While keeping the upper arms stationary, curl the weight up as high as you can while squeezing the biceps. Breathe out as you perform this portion of the movement. Tip: Only the forearms should move. Do not swing the arms.','After a second contraction, slowly go back to the starting position as you inhale. Tip: Make sure that you go all of the way down.','Repeat for the recommended amount of repetitions.']::text[],array['Barbell_Curls_Lying_Against_An_Incline/0.jpg','Barbell_Curls_Lying_Against_An_Incline/1.jpg']::text[],false),
('Barbell_Deadlift','Soulevé de terre','Barbell Deadlift','Force','Lombaires','Mollets, Avant-bras, Fessiers, Ischio-jambiers, Dorsaux, Haut du dos, Quadriceps, Trapèzes','Barre','Intermédiaire','Barre au-dessus du milieu des pieds. Dos neutre, pousse le sol avec les jambes et verrouille les hanches en haut.',array['Stand in front of a loaded barbell.','While keeping the back as straight as possible, bend your knees, bend forward and grasp the bar using a medium (shoulder width) overhand grip. This will be the starting position of the exercise. Tip: If it is difficult to hold on to the bar with this grip, alternate your grip or use wrist straps.','While holding the bar, start the lift by pushing with your legs while simultaneously getting your torso to the upright position as you breathe out. In the upright position, stick your chest out and contract the back by bringing the shoulder blades back. Think of how the soldiers in the military look when they are in standing in attention.','Go back to the starting position by bending at the knees while simultaneously leaning the torso forward at the waist while keeping the back straight. When the weights on the bar touch the floor you are back at the starting position and ready to perform another repetition.','Perform the amount of repetitions prescribed in the program.']::text[],array['Barbell_Deadlift/0.jpg','Barbell_Deadlift/1.jpg']::text[],true),
('Barbell_Full_Squat','Squat barre complet','Barbell Full Squat','Force','Quadriceps','Mollets, Fessiers, Ischio-jambiers, Lombaires','Barre','Intermédiaire','Barre sur les trapèzes, pieds largeur d''épaules. Descends hanches sous les genoux en gardant le dos neutre, remonte en poussant dans le sol.',array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just above shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.','Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.','Step away from the rack and position your legs using a shoulder-width medium stance with the toes slightly pointed out. Keep your head up at all times and maintain a straight back. This will be your starting position.','Begin to slowly lower the bar by bending the knees and sitting back with your hips as you maintain a straight posture with the head up. Continue down until your hamstrings are on your calves. Inhale as you perform this portion of the movement.','Begin to raise the bar as you exhale by pushing the floor with the heel or middle of your foot as you straighten the legs and extend the hips to go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],array['Barbell_Full_Squat/0.jpg','Barbell_Full_Squat/1.jpg']::text[],true),
('Barbell_Glute_Bridge','Pont fessier barre','Barbell Glute Bridge','Force','Fessiers','Mollets, Ischio-jambiers','Barre','Intermédiaire','Allongé au sol, barre sur les hanches. Monte le bassin en poussant dans les talons, contracte en haut.',array['Begin seated on the ground with a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise. Roll the bar so that it is directly above your hips, and lay down flat on the floor.','Begin the movement by driving through with your heels, extending your hips vertically through the bar. Your weight should be supported by your upper back and the heels of your feet.','Extend as far as possible, then reverse the motion to return to the starting position.']::text[],array['Barbell_Glute_Bridge/0.jpg','Barbell_Glute_Bridge/1.jpg']::text[],true),
('Barbell_Guillotine_Bench_Press','Barbell Guillotine Bench Press','Barbell Guillotine Bench Press','Force','Pectoraux','Épaules, Triceps','Barre','Intermédiaire',null,array['Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over your neck with your arms locked. This will be your starting position.','As you breathe in, bring the bar down slowly until it is about 1 inch from your neck.','After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. It should take at least twice as long to go down than to come up.','Repeat the movement for the prescribed amount of repetitions.','When you are done, place the bar back in the rack.']::text[],array['Barbell_Guillotine_Bench_Press/0.jpg','Barbell_Guillotine_Bench_Press/1.jpg']::text[],false),
('Barbell_Hack_Squat','Barbell Hack Squat','Barbell Hack Squat','Force','Quadriceps','Mollets, Avant-bras, Ischio-jambiers','Barre','Intermédiaire',null,array['Stand up straight while holding a barbell behind you at arms length and your feet at shoulder width. Tip: A shoulder width grip is best with the palms of your hands facing back. You can use wrist wraps for this exercise for a better grip. This will be your starting position.','While keeping your head and eyes up and back straight, squat until your upper thighs are parallel to the floor. Breathe in as you slowly go down.','Pressing mainly with the heel of the foot and squeezing the thighs, go back up as you breathe out.','Repeat for the recommended amount of repetitions.']::text[],array['Barbell_Hack_Squat/0.jpg','Barbell_Hack_Squat/1.jpg']::text[],false),
('Barbell_Hip_Thrust','Hip thrust barre','Barbell Hip Thrust','Force','Fessiers','Mollets, Ischio-jambiers','Barre','Intermédiaire','Haut du dos sur un banc, barre sur les hanches. Monte le bassin jusqu''à l''alignement épaules-genoux, serre les fessiers.',array['Begin seated on the ground with a bench directly behind you. Have a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise.','Roll the bar so that it is directly above your hips, and lean back against the bench so that your shoulder blades are near the top of it.','Begin the movement by driving through your feet, extending your hips vertically through the bar. Your weight should be supported by your shoulder blades and your feet. Extend as far as possible, then reverse the motion to return to the starting position.']::text[],array['Barbell_Hip_Thrust/0.jpg','Barbell_Hip_Thrust/1.jpg']::text[],true),
('Barbell_Incline_Bench_Press_-_Medium_Grip','Développé incliné barre','Barbell Incline Bench Press - Medium Grip','Force','Pectoraux','Épaules, Triceps','Barre','Débutant','Banc incliné à 30-45°. Descends la barre vers le haut des pectoraux puis pousse.',array['Lie back on an incline bench. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.','As you breathe in, come down slowly until you feel the bar on you upper chest.','After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly again. Tip: it should take at least twice as long to go down than to come up.','Repeat the movement for the prescribed amount of repetitions.','When you are done, place the bar back in the rack.']::text[],array['Barbell_Incline_Bench_Press_-_Medium_Grip/0.jpg','Barbell_Incline_Bench_Press_-_Medium_Grip/1.jpg']::text[],true),
('Barbell_Incline_Shoulder_Raise','Barbell Incline Shoulder Raise','Barbell Incline Shoulder Raise','Force','Épaules','Pectoraux','Barre','Débutant',null,array['Lie back on an Incline Bench. Using a medium width grip (a grip that is slightly wider than shoulder width), lift the bar from the rack and hold it straight over you with your arms straight. This will be your starting position.','While keeping the arms straight, lift the bar by protracting your shoulder blades, raising the shoulders from the bench as you breathe out.','Bring back the bar to the starting position as you breathe in.','Repeat for the recommended amount of repetitions.']::text[],array['Barbell_Incline_Shoulder_Raise/0.jpg','Barbell_Incline_Shoulder_Raise/1.jpg']::text[],false),
('Barbell_Lunge','Fente barre','Barbell Lunge','Force','Quadriceps','Mollets, Fessiers, Ischio-jambiers','Barre','Intermédiaire','Barre sur les trapèzes, grand pas en avant. Descends genou arrière vers le sol puis reviens.',array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.','Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.','Step away from the rack and step forward with your right leg and squat down through your hips, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: Do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. li>','Using mainly the heel of your foot, push up and go back to the starting position as you exhale.','Repeat the movement for the recommended amount of repetitions and then perform with the left leg.']::text[],array['Barbell_Lunge/0.jpg','Barbell_Lunge/1.jpg']::text[],true),
('Barbell_Rear_Delt_Row','Barbell Rear Delt Row','Barbell Rear Delt Row','Force','Épaules','Biceps, Dorsaux, Haut du dos','Barre','Débutant',null,array['Stand up straight while holding a barbell using a wide (higher than shoulder width) and overhand (palms facing your body) grip.','Bend knees slightly and bend over as you keep the natural arch of your back. Let the arms hang in front of you as they hold the bar. Once your torso is parallel to the floor, flare the elbows out and away from your body. Tip: Your torso and your arms should resemble the letter "T". Now you are ready to begin the exercise.','While keeping the upper arms perpendicular to the torso, pull the barbell up towards your upper chest as you squeeze the rear delts and you breathe out. Tip: When performed correctly, this exercise should resemble a bench press in reverse. Also, refrain from using your biceps to do the work. Focus on targeting the rear delts; the arms should only act as hooks.','Slowly go back to the initial position as you breathe in.','Repeat for the recommended amount of repetitions.']::text[],array['Barbell_Rear_Delt_Row/0.jpg','Barbell_Rear_Delt_Row/1.jpg']::text[],false),
('Barbell_Rollout_from_Bench','Barbell Rollout from Bench','Barbell Rollout from Bench','Force','Abdominaux','Fessiers, Ischio-jambiers, Dorsaux, Épaules','Barre','Intermédiaire',null,array['Place a loaded barbell on the ground, near the end of a bench. Kneel with both legs on the bench, and take a medium to narrow grip on the barbell. This will be your starting position.','To begin, extend through the hips to slowly roll the bar forward. As you roll out, flex the shoulder to roll the bar above your head. Ensure that your arms remain extended throughout the movement.','When the bar has been moved as far forward as possible, return to the starting position.']::text[],array['Barbell_Rollout_from_Bench/0.jpg','Barbell_Rollout_from_Bench/1.jpg']::text[],false),
('Barbell_Seated_Calf_Raise','Barbell Seated Calf Raise','Barbell Seated Calf Raise','Force','Mollets',null,'Barre','Débutant',null,array['Place a block about 12 inches in front of a flat bench.','Sit on the bench and place the ball of your feet on the block.','Have someone place a barbell over your upper thighs about 3 inches above your knees and hold it there. This will be your starting position.','Raise up on your toes as high as possible as you squeeze the calves and as you breathe out.','After a second contraction, slowly go back to the starting position. Tip: To get maximum benefit stretch your calves as far as you can.','Repeat for the recommended amount of repetitions.']::text[],array['Barbell_Seated_Calf_Raise/0.jpg','Barbell_Seated_Calf_Raise/1.jpg']::text[],false),
('Barbell_Shoulder_Press','Développé militaire barre','Barbell Shoulder Press','Force','Épaules','Pectoraux, Triceps','Barre','Intermédiaire','Barre devant les épaules, gainage serré. Pousse au-dessus de la tête jusqu''à bras tendus.',array['Sit on a bench with back support in a squat rack. Position a barbell at a height that is just above your head. Grab the barbell with a pronated grip (palms facing forward).','Once you pick up the barbell with the correct grip width, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.','Lower the bar down to the shoulders slowly as you inhale.','Lift the bar back up to the starting position as you exhale.','Repeat for the recommended amount of repetitions.']::text[],array['Barbell_Shoulder_Press/0.jpg','Barbell_Shoulder_Press/1.jpg']::text[],true),
('Barbell_Shrug','Shrug barre','Barbell Shrug','Force','Trapèzes',null,'Barre','Débutant','Barre en mains bras tendus, monte les épaules vers les oreilles puis redescends lentement.',array['Stand up straight with your feet at shoulder width as you hold a barbell with both hands in front of you using a pronated grip (palms facing the thighs). Tip: Your hands should be a little wider than shoulder width apart. You can use wrist wraps for this exercise for a better grip. This will be your starting position.','Raise your shoulders up as far as you can go as you breathe out and hold the contraction for a second. Tip: Refrain from trying to lift the barbell by using your biceps.','Slowly return to the starting position as you breathe in.','Repeat for the recommended amount of repetitions.']::text[],array['Barbell_Shrug/0.jpg','Barbell_Shrug/1.jpg']::text[],true),
('Barbell_Shrug_Behind_The_Back','Barbell Shrug Behind The Back','Barbell Shrug Behind The Back','Force','Trapèzes','Avant-bras, Haut du dos','Barre','Débutant',null,array['Stand up straight with your feet at shoulder width as you hold a barbell with both hands behind your back using a pronated grip (palms facing back). Tip: Your hands should be a little wider than shoulder width apart. You can use wrist wraps for this exercise for better grip. This will be your starting position.','Raise your shoulders up as far as you can go as you breathe out and hold the contraction for a second. Tip: Refrain from trying to lift the barbell by using your biceps. The arms should remain stretched out at all times.','Slowly return to the starting position as you breathe in.','Repeat for the recommended amount of repetitions.']::text[],array['Barbell_Shrug_Behind_The_Back/0.jpg','Barbell_Shrug_Behind_The_Back/1.jpg']::text[],false),
('Barbell_Side_Bend','Barbell Side Bend','Barbell Side Bend','Force','Abdominaux','Lombaires','Barre','Débutant',null,array['Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck). Your feet should be shoulder width apart. This will be your starting position.','While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting position as you exhale. Tip: Keep the rest of the body stationary.','Now repeat the movement but bending to the left instead. Hold for a second and come back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],array['Barbell_Side_Bend/0.jpg','Barbell_Side_Bend/1.jpg']::text[],false),
('Barbell_Side_Split_Squat','Barbell Side Split Squat','Barbell Side Split Squat','Force','Quadriceps','Mollets, Ischio-jambiers, Lombaires','Barre','Débutant',null,array['Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck). Your feet should be placed wide apart with the foot of the lead leg angled out to the side. This will be your starting position.','Lower your body towards the side of your angled foot by bending the knee and hip of your lead leg and while keeping the opposite leg only slightly bent. Breathe in as you lower your body.','Return to the starting position by extending the hip and knee of the lead leg. Breathe out as you perform this movement.','After performing the recommended amount of reps, repeat the movement with the opposite leg.']::text[],array['Barbell_Side_Split_Squat/0.jpg','Barbell_Side_Split_Squat/1.jpg']::text[],false),
('Barbell_Squat','Squat barre (Back Squat)','Barbell Squat','Force','Quadriceps','Mollets, Fessiers, Ischio-jambiers, Lombaires','Barre','Débutant','Barre haute sur les trapèzes, gainage serré. Descends en contrôlant jusqu''à la parallèle, genoux dans l''axe des pieds, remonte en expirant.',array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack to just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.','Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.','Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).','Begin to slowly lower the bar by bending the knees and hips as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.','Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],array['Barbell_Squat/0.jpg','Barbell_Squat/1.jpg']::text[],true),
('Barbell_Squat_To_A_Bench','Barbell Squat To A Bench','Barbell Squat To A Bench','Force','Quadriceps','Mollets, Fessiers, Ischio-jambiers, Lombaires','Barre','Avancé',null,array['This exercise is best performed inside a squat rack for safety purposes. To begin, first place a flat bench or a box behind you. The flat bench is used to teach you to set your hips back and to hit depth.','','Then, set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.','Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.','Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).','Begin to slowly lower the bar by bending the knees and sitting your hips back as you maintain a straight posture with the head up. Continue down until you slightly touch the bench behind you. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.','Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs and extend the hips to go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],array['Barbell_Squat_To_A_Bench/0.jpg','Barbell_Squat_To_A_Bench/1.jpg']::text[],false),
('Barbell_Step_Ups','Step-up barre','Barbell Step Ups','Force','Quadriceps','Mollets, Fessiers, Ischio-jambiers, Quadriceps','Barre','Intermédiaire','Monte sur une box avec une jambe en poussant dans le talon, redescends en contrôle. Alterne.',array['Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck) and stand upright behind an elevated platform (such as the one used for spotting behind a flat bench). This is your starting position.','Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute the force required to come up.','Step down with the left leg by flexing the hip and knee of the right leg as you inhale. Return to the original standing position by placing the right foot of to next to the left foot on the initial position.','Repeat with the right leg for the recommended amount of repetitions and then perform with the left leg.']::text[],array['Barbell_Step_Ups/0.jpg','Barbell_Step_Ups/1.jpg']::text[],true),
('Barbell_Walking_Lunge','Fentes marchées barre','Barbell Walking Lunge','Force','Quadriceps','Mollets, Fessiers, Ischio-jambiers','Barre','Débutant','Enchaîne les fentes vers l''avant en marchant, buste droit, barre sur le dos.',array['Begin standing with your feet shoulder width apart and a barbell across your upper back.','Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.','Drive through the heel of your lead foot and extend both knees to raise yourself back up.','Step forward with your rear foot, repeating the lunge on the opposite leg.']::text[],array['Barbell_Walking_Lunge/0.jpg','Barbell_Walking_Lunge/1.jpg']::text[],true),
('Battling_Ropes','Battle ropes','Battling Ropes','Force','Épaules','Pectoraux, Avant-bras','Autre','Débutant','Genoux fléchis, fais onduler les cordes en alternant les bras rapidement.',array['For this exercise you will need a heavy rope anchored at its center 15-20 feet away. Standing in front of the rope, take an end in each hand with your arms extended at your side. This will be your starting position.','Initiate the movement by rapidly raising one arm to shoulder level as quickly as you can.','As you let that arm drop to the starting position, raise the opposite side.','Continue alternating your left and right arms, whipping the ropes up and down as fast as you can.']::text[],array['Battling_Ropes/0.jpg','Battling_Ropes/1.jpg']::text[],true),
('Bear_Crawl_Sled_Drags','Bear Crawl Sled Drags','Bear Crawl Sled Drags','Strongman','Quadriceps','Mollets, Fessiers, Ischio-jambiers','Autre','Débutant',null,array['Wearing either a harness or a loose weight belt, attach the chain to the back so that you will be facing away from the sled. Bend down so that your hands are on the ground. Your back should be flat and knees bent. This is your starting position.','Begin by driving with legs, alternating left and right. Use your hands to maintain balance and to help pull. Try to keep your back flat as you move over a given distance.']::text[],array['Bear_Crawl_Sled_Drags/0.jpg','Bear_Crawl_Sled_Drags/1.jpg']::text[],false),
('Behind_Head_Chest_Stretch','Behind Head Chest Stretch','Behind Head Chest Stretch','Mobilité','Pectoraux','Épaules','Autre','Avancé',null,array['Sit upright on the floor with your partner behind you.','Place your hands behind your hand, and push your elbows back as far as you can. Your partner should hold your elbows. This will be your starting position.','Gently attempt to pull your elbows forward with your hands still behind your head for 10 or more seconds. Your partner should prevent your elbows from moving.','Now, relax your muscles and have your partner gently pull the elbows back as far as it comfortable for you. Be sure to let your partner know when the stretch is adequate to prevent overstretching or injury.']::text[],array['Behind_Head_Chest_Stretch/0.jpg','Behind_Head_Chest_Stretch/1.jpg']::text[],false),
('Bench_Dips','Dips sur banc','Bench Dips','Force','Triceps','Pectoraux, Épaules','Poids du corps','Débutant','Mains sur un banc derrière toi, descends en fléchissant les coudes à 90° puis remonte.',array['For this exercise you will need to place a bench behind your back. With the bench perpendicular to your body, and while looking away from it, hold on to the bench on its edge with the hands fully extended, separated at shoulder width. The legs will be extended forward, bent at the waist and perpendicular to your torso. This will be your starting position.','Slowly lower your body as you inhale by bending at the elbows until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm. Tip: Keep the elbows as close as possible throughout the movement. Forearms should always be pointing down.','Using your triceps to bring your torso up again, lift yourself back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],array['Bench_Dips/0.jpg','Bench_Dips/1.jpg']::text[],true),
('Bench_Jump','Bench Jump','Bench Jump','Explosivité','Quadriceps','Mollets, Fessiers, Ischio-jambiers','Poids du corps','Intermédiaire',null,array['Begin with a box or bench 1-2 feet in front of you. Stand with your feet shoulder width apart. This will be your starting position.','Perform a short squat in preparation for the jump; swing your arms behind you.','Rebound out of this position, extending through the hips, knees, and ankles to jump as high as possible. Swing your arms forward and up.','Jump over the bench, landing with the knees bent, absorbing the impact through the legs.','Turn around and face the opposite direction, then jump back over the bench.']::text[],array['Bench_Jump/0.jpg','Bench_Jump/1.jpg']::text[],false),
('Bench_Press_-_Powerlifting','Bench Press - Powerlifting','Bench Press - Powerlifting','Force','Triceps','Pectoraux, Avant-bras, Dorsaux, Épaules','Barre','Intermédiaire',null,array['Begin by lying on the bench, getting your head beyond the bar if possible. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.','However wide your grip, it should cover the ring on the bar. Pull the bar out of the rack without protracting your shoulders. Focus on squeezing the bar and trying to pull it apart.','Lower the bar to your lower chest or upper stomach. The bar, wrist, and elbow should stay in line at all times.','Pause when the barbell touches your torso, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout.']::text[],array['Bench_Press_-_Powerlifting/0.jpg','Bench_Press_-_Powerlifting/1.jpg']::text[],false),
('Bench_Press_-_With_Bands','Bench Press - With Bands','Bench Press - With Bands','Force','Pectoraux','Épaules, Triceps','Élastiques','Débutant',null,array['Using a flat bench secure a band under the leg of the bench that is nearest to your head.','Once the band is secure, grab it by both handles and lie down on the bench.','Extend your arms so that you are holding the band handles in front of you at shoulder width.','Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.','Bring down the handles slowly until your elbow forms a 90 degree angle. Keep full control at all times.','As you breathe out, bring the handles up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.','Repeat the movement for the prescribed amount of repetitions of your training program.']::text[],array['Bench_Press_-_With_Bands/0.jpg','Bench_Press_-_With_Bands/1.jpg']::text[],false),
('Bench_Press_with_Chains','Bench Press with Chains','Bench Press with Chains','Force','Triceps','Pectoraux, Dorsaux, Épaules','Barre','Avancé',null,array['Adjust the leader chain, shortening it to the desired length.Place the chains on the sleeves of the bar.','Lying on the bench, get your head beyond the bar if possible. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement. However wide your grip, it should cover the ring on the bar.','Pull the bar out of the rack without protracting your shoulders. Focus on squeezing the bar and trying to pull it apart. Lower the bar to your lower chest or upper stomach. The bar, wrist, and elbow should stay in line at all times.','Pause when the barbell touches your torso, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout.']::text[],array['Bench_Press_with_Chains/0.jpg','Bench_Press_with_Chains/1.jpg']::text[],false),
('Bench_Sprint','Bench Sprint','Bench Sprint','Explosivité','Quadriceps','Mollets, Fessiers, Ischio-jambiers','Autre','Débutant',null,array['Stand on the ground with one foot resting on a bench or box with your heel close to the edge.','Push off with your foot on top of the bench, extending through the hip and knee.','Land with the opposite foot on top of the box, returning your other foot back to the start position.','Continue alternating from one foot to another to complete the set.']::text[],array['Bench_Sprint/0.jpg','Bench_Sprint/1.jpg']::text[],false),
('Bent-Arm_Barbell_Pullover','Bent-Arm Barbell Pullover','Bent-Arm Barbell Pullover','Force','Dorsaux','Pectoraux, Dorsaux, Épaules, Triceps','Barre','Intermédiaire',null,array['Lie on a flat bench with a barbell using a shoulder grip width.','Hold the bar straight over your chest with a bend in your arms. This will be your starting position.','While keeping your arms in the bent arm position, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest.','At that point, bring the barbell back to the starting position using the arc through which the weight was lowered and exhale as you perform this movement.','Hold the weight on the initial position for a second and repeat the motion for the prescribed number of repetitions.']::text[],array['Bent-Arm_Barbell_Pullover/0.jpg','Bent-Arm_Barbell_Pullover/1.jpg']::text[],false),
('Bent-Arm_Dumbbell_Pullover','Bent-Arm Dumbbell Pullover','Bent-Arm Dumbbell Pullover','Force','Pectoraux','Dorsaux, Épaules, Triceps','Haltères','Intermédiaire',null,array['Place a dumbbell standing up on a flat bench.','Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench (torso across it as in forming a cross) with only your shoulders lying on the surface. Hips should be below the bench and legs bent with feet firmly on the floor. The head will be off the bench as well.','Grasp the dumbbell with both hands and hold it straight over your chest with a bend in your arms. Both palms should be pressing against the underside one of the sides of the dumbbell. This will be your starting position. Caution: Always ensure that the dumbbell used for this exercise is secure. Using a dumbbell with loose plates can result in the dumbbell falling apart and falling on your face.','While keeping your arms locked in the bent arm position, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest.','At that point, bring the dumbbell back to the starting position using the arc through which the weight was lowered and exhale as you perform this movement.','Hold the weight on the initial position for a second and repeat the motion for the prescribed number of repetitions.']::text[],array['Bent-Arm_Dumbbell_Pullover/0.jpg','Bent-Arm_Dumbbell_Pullover/1.jpg']::text[],false),
('Bent-Knee_Hip_Raise','Bent-Knee Hip Raise','Bent-Knee Hip Raise','Force','Abdominaux',null,'Poids du corps','Débutant',null,array['Lay flat on the floor with your arms next to your sides.','Now bend your knees at around a 75 degree angle and lift your feet off the floor by around 2 inches.','Using your lower abs, bring your knees in towards you as you maintain the 75 degree angle bend in your legs. Continue this movement until you raise your hips off of the floor by rolling your pelvis backward. Breathe out as you perform this portion of the movement. Tip: At the end of the movement your knees will be over your chest.','Squeeze your abs at the top of the movement for a second and then return to the starting position slowly as you breathe in. Tip: Maintain a controlled motion at all times.','Repeat for the recommended amount of repetitions.']::text[],array['Bent-Knee_Hip_Raise/0.jpg','Bent-Knee_Hip_Raise/1.jpg']::text[],false),
('Bent_Over_Barbell_Row','Rowing barre buste penché','Bent Over Barbell Row','Force','Haut du dos','Biceps, Dorsaux, Épaules','Barre','Débutant','Buste penché à 45°, dos plat. Tire la barre vers le nombril en serrant les omoplates.',array['Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.','Now, while keeping the torso stationary, breathe out and lift the barbell to you. Keep the elbows close to the body and only use the forearms to hold the weight. At the top contracted position, squeeze the back muscles and hold for a brief pause.','Then inhale and slowly lower the barbell back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],array['Bent_Over_Barbell_Row/0.jpg','Bent_Over_Barbell_Row/1.jpg']::text[],true),
('Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench','Oiseau haltères','Bent Over Dumbbell Rear Delt Raise With Head On Bench','Force','Épaules',null,'Haltères','Débutant','Buste penché, ouvre les bras sur les côtés en serrant l''arrière des épaules.',array['Stand up straight while holding a dumbbell in each hand and with an incline bench in front of you.','While keeping your back straight and maintaining the natural arch of your back, lean forward until your forehead touches the bench in front of you. Let the arms hang in front of you perpendicular to the ground. The palms of your hands should be facing each other and your torso should be parallel to the floor. This will be your starting position.','Keeping your torso forward and stationary, and the arms straight with a slight bend at the elbows, lift the dumbbells straight to the side until both arms are parallel to the floor. Exhale as you lift the weights. Caution: avoid swinging the torso or bringing the arms back as opposed to the side.','After a one second contraction at the top, slowly lower the dumbbells back to the starting position.','Repeat the recommended amount of repetitions.']::text[],array['Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench/0.jpg','Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench/1.jpg']::text[],true),
('Bent_Over_Low-Pulley_Side_Lateral','Bent Over Low-Pulley Side Lateral','Bent Over Low-Pulley Side Lateral','Force','Épaules','Lombaires, Haut du dos, Trapèzes','Poulie','Débutant',null,array['Select a weight and hold the handle of the low pulley with your right hand.','Bend at the waist until your torso is nearly parallel to the floor. Your legs should be slightly bent with your left hand placed on your lower left thigh. Your right arm should be hanging from your shoulder in front of you and with a slight bend at the elbow. This will be your starting position.','Raise your right arm, elbow slightly bent, to the side until the arm is parallel to the floor and in line with your right ear. Breathe out as you perform this step.','Slowly lower the weight back to the starting position as you breathe in.','Repeat for the recommended amount of repetitions and repeat the movement with the other arm.']::text[],array['Bent_Over_Low-Pulley_Side_Lateral/0.jpg','Bent_Over_Low-Pulley_Side_Lateral/1.jpg']::text[],false),
('Bent_Over_One-Arm_Long_Bar_Row','Bent Over One-Arm Long Bar Row','Bent Over One-Arm Long Bar Row','Force','Haut du dos','Biceps, Dorsaux, Lombaires, Trapèzes','Barre','Débutant',null,array['Put weight on one of the ends of an Olympic barbell. Make sure that you either place the other end of the barbell in the corner of two walls; or put a heavy object on the ground so the barbell cannot slide backward.','Bend forward until your torso is as close to parallel with the floor as you can and keep your knees slightly bent.','Now grab the bar with one arm just behind the plates on the side where the weight was placed and put your other hand on your knee. This will be your starting position.','Pull the bar straight up with your elbow in (to maximize back stimulation) until the plates touch your lower chest. Squeeze the back muscles as you lift the weight up and hold for a second at the top of the movement. Breathe out as you lift the weight. Tip: Do not allow for any swinging of the torso. Only the arm should move.','Slowly lower the bar to the starting position getting a nice stretch on the lats. Tip: Do not let the plates touch the floor. To ensure the best range of motion, I recommend using small plates (25-lb ones) as opposed to larger plates (like 35-45lb ones).','Repeat for the recommended amount of repetitions and switch arms.']::text[],array['Bent_Over_One-Arm_Long_Bar_Row/0.jpg','Bent_Over_One-Arm_Long_Bar_Row/1.jpg']::text[],false),
('Bent_Over_Two-Arm_Long_Bar_Row','Bent Over Two-Arm Long Bar Row','Bent Over Two-Arm Long Bar Row','Force','Haut du dos','Biceps, Dorsaux','Barre','Intermédiaire',null,array['Put weight on one of the ends of an Olympic barbell. Make sure that you either place the other end of the barbell in the corner of two walls; or put a heavy object on the ground so the barbell cannot slide backward.','Bend forward until your torso is as close to parallel with the floor as you can and keep your knees slightly bent.','Now grab the bar with both arms just behind the plates on the side where the weight was placed and put your other hand on your knee. This will be your starting position.','Pull the bar straight up with your elbows in (to maximize back stimulation) until the plates touch your lower chest. Squeeze the back muscles as you lift the weight up and hold for a second at the top of the movement. Breathe out as you lift the weight. Tip: Use a stirrup or double handle cable attachment by hooking it under the end of the bar.','Slowly lower the bar to the starting position getting a nice stretch on the lats. Tip: Do not let the plates touch the floor. To ensure the best range of motion, I recommend using small plates (25-lb ones) as opposed to larger plates (like 35-45lb ones).','Repeat for the recommended amount of repetitions.']::text[],array['Bent_Over_Two-Arm_Long_Bar_Row/0.jpg','Bent_Over_Two-Arm_Long_Bar_Row/1.jpg']::text[],false),
('Bent_Over_Two-Dumbbell_Row','Rowing haltères buste penché','Bent Over Two-Dumbbell Row','Force','Haut du dos','Biceps, Dorsaux, Épaules','Haltères','Débutant','Buste penché, dos plat, tire les deux haltères vers les hanches puis redescends.',array['With a dumbbell in each hand (palms facing your torso), bend your knees slightly and bring your torso forward by bending at the waist; as you bend make sure to keep your back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The weights should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.','While keeping the torso stationary, lift the dumbbells to your side (as you breathe out), keeping the elbows close to the body (do not exert any force with the forearm other than holding the weights). On the top contracted position, squeeze the back muscles and hold for a second.','Slowly lower the weight again to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[],array['Bent_Over_Two-Dumbbell_Row/0.jpg','Bent_Over_Two-Dumbbell_Row/1.jpg']::text[],true),
('Bent_Over_Two-Dumbbell_Row_With_Palms_In','Bent Over Two-Dumbbell Row With Palms In','Bent Over Two-Dumbbell Row With Palms In','Force','Haut du dos','Biceps, Dorsaux','Haltères','Débutant',null,array['With a dumbbell in each hand (palms facing each other), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The weights should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.','While keeping the torso stationary, lift the dumbbells to your side as you breathe out, squeezing your shoulder blades together. On the top contracted position, squeeze the back muscles and hold for a second.','Slowly lower the weight again to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[],array['Bent_Over_Two-Dumbbell_Row_With_Palms_In/0.jpg','Bent_Over_Two-Dumbbell_Row_With_Palms_In/1.jpg']::text[],false),
('Bent_Press','Bent Press','Bent Press','Force','Abdominaux','Fessiers, Ischio-jambiers, Lombaires, Quadriceps, Épaules, Triceps','Kettlebell','Avancé',null,array['Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so. This will be your starting position.','Begin my leaning to the side opposite the kettlebell, continuing until you are able to touch the ground with your free hand, keeping your eyes on the kettlebell. As you do so, press the weight vertically be extending through the elbow, keeping your arm perpendicular to the ground.','Return to an upright position, with the kettlebell above your head. Return the kettlebell to the shoulder and repeat for the desired number of repetitions.']::text[],array['Bent_Press/0.jpg','Bent_Press/1.jpg']::text[],false),
('Bicycling','Bicycling','Bicycling','Cardio','Quadriceps','Mollets, Fessiers, Ischio-jambiers','Autre','Débutant',null,array['To begin, seat yourself on the bike and adjust the seat to your height.']::text[],array['Bicycling/0.jpg','Bicycling/1.jpg']::text[],false),
('Bicycling_Stationary','Vélo stationnaire','Bicycling, Stationary','Cardio','Quadriceps','Mollets, Fessiers, Ischio-jambiers','Machine','Débutant','Pédale à cadence régulière en gardant le buste stable.',array['To begin, seat yourself on the bike and adjust the seat to your height.','Select the desired option from the menu. You may have to start pedaling to turn it on. You can use the manual setting, or you can select a program to use. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. The level of resistance can be changed throughout the workout. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.']::text[],array['Bicycling_Stationary/0.jpg','Bicycling_Stationary/1.jpg']::text[],true),
('Board_Press','Board Press','Board Press','Force','Triceps','Pectoraux, Avant-bras, Dorsaux, Épaules','Barre','Intermédiaire',null,array['Begin by lying on the bench, getting your head beyond the bar if possible. One to five boards, made out of 2x6''s, can be screwed together and held in place by a training partner, bands, or just tucked under your shirt.','Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.','You can take a standard bench grip, or shoulder width to focus on the triceps. Pull the bar out of the rack without protracting your shoulders. The bar, wrist, and elbow should stay in line at all times. Focus on squeezing the bar and trying to pull it apart.','Lower the bar to the boards, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout.']::text[],array['Board_Press/0.jpg','Board_Press/1.jpg']::text[],false),
('Body-Up','Body-Up','Body-Up','Force','Triceps','Abdominaux, Avant-bras','Poids du corps','Intermédiaire',null,array['Assume a plank position on the ground. You should be supporting your bodyweight on your toes and forearms, keeping your torso straight. Your forearms should be shoulder-width apart. This will be your starting position.','Pressing your palms firmly into the ground, extend through the elbows to raise your body from the ground. Keep your torso rigid as you perform the movement.','Slowly lower your forearms back to the ground by allowing the elbows to flex.','Repeat.']::text[],array['Body-Up/0.jpg','Body-Up/1.jpg']::text[],false),
('Body_Tricep_Press','Body Tricep Press','Body Tricep Press','Force','Triceps',null,'Poids du corps','Débutant',null,array['Position a bar in a rack at chest height.','Standing, take a shoulder width grip on the bar and step a yard or two back, feet together and arms extended so that you are leaning on the bar. This will be your starting position.','Begin by flexing the elbow, lowering yourself towards the bar.','Pause, and then reverse the motion by extending the elbows.','Progress from bodyweight by adding chains over your shoulders.']::text[],array['Body_Tricep_Press/0.jpg','Body_Tricep_Press/1.jpg']::text[],false),
('Bodyweight_Flyes','Bodyweight Flyes','Bodyweight Flyes','Force','Pectoraux','Abdominaux, Épaules, Triceps','Barre EZ','Intermédiaire',null,array['Position two equally loaded EZ bars on the ground next to each other. Ensure they are able to roll.','Assume a push-up position over the bars, supporting your weight on your toes and hands with your arms extended and body straight.','Place your hands on the bars. This will be your starting position.','Using a slow and controlled motion, move your hands away from the midline of your body, rolling the bars apart. Inhale during this portion of the motion.','After moving the bars as far apart as you can, return to the starting position by pulling them back together. Exhale as you perform this movement.']::text[],array['Bodyweight_Flyes/0.jpg','Bodyweight_Flyes/1.jpg']::text[],false),
('Bodyweight_Mid_Row','Bodyweight Mid Row','Bodyweight Mid Row','Force','Haut du dos','Biceps, Dorsaux','Autre','Intermédiaire',null,array['Begin by taking a medium to wide grip on a pull-up apparatus with your palms facing away from you. From a hanging position, tuck your knees to your chest, leaning back and getting your legs over your side of the pull-up apparatus. This will be your starting position.','Beginning with your arms straight, flex the elbows and retract the shoulder blades to raise your body up until your legs contact the pull-up apparatus.','After a brief pause, return to the starting position.']::text[],array['Bodyweight_Mid_Row/0.jpg','Bodyweight_Mid_Row/1.jpg']::text[],false),
('Bodyweight_Squat','Squat au poids du corps','Bodyweight Squat','Force','Quadriceps','Fessiers, Ischio-jambiers','Poids du corps','Débutant','Pieds largeur d''épaules, bras devant. Descends hanches en arrière jusqu''à la parallèle puis remonte.',array['Stand with your feet shoulder width apart. You can place your hands behind your head. This will be your starting position.','Begin the movement by flexing your knees and hips, sitting back with your hips.','Continue down to full depth if you are able,and quickly reverse the motion until you return to the starting position. As you squat, keep your head and chest up and push your knees out.']::text[],array['Bodyweight_Squat/0.jpg','Bodyweight_Squat/1.jpg']::text[],true),
('Bodyweight_Walking_Lunge','Fentes marchées au poids du corps','Bodyweight Walking Lunge','Force','Quadriceps','Mollets, Fessiers, Ischio-jambiers',null,'Débutant','Enchaîne les fentes en avançant, buste droit, genou avant au-dessus de la cheville.',array['Begin standing with your feet shoulder width apart and your hands on your hips.','Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.','Drive through the heel of your lead foot and extend both knees to raise yourself back up.','Step forward with your rear foot, repeating the lunge on the opposite leg.']::text[],array['Bodyweight_Walking_Lunge/0.jpg','Bodyweight_Walking_Lunge/1.jpg']::text[],true),
('Bosu_Ball_Cable_Crunch_With_Side_Bends','Bosu Ball Cable Crunch With Side Bends','Bosu Ball Cable Crunch With Side Bends','Force','Abdominaux',null,'Poulie','Débutant',null,array['Connect a standard handle to each arm of a cable machine, and position them in the most downward position.','Grab a Bosu Ball and position it in front and center of the cable machine.','Lie down on the Bosu Ball with the small of your back arched around the ball. Your rear end should be close to the floor without touching it.','With both hands, reach back and grab the handle of each cable.','With your feet positioned in a wide stance, extend your arms straight out in front of you and in between your knees. Your hands should be at knee level.','Keep your arms straight and in-line with the upward angle of the cable. Elevate your torso in a crunching motion without dropping or bending your arms.','Maintain the rigid position with your arms. Slowly descend back to the starting position with your back arched around the Bosu Ball and your abdominals elongated.','Repeat the same series of movements to failure.','Once you reach failure, keep your abs tight and raise your torso into plank position so your back is elevated off the Bosu Ball.','Lower your arms down to your side; keep them straight. Start doing alternating side bends; reach for your heels! This finishing movement will focus on your obliques.']::text[],array['Bosu_Ball_Cable_Crunch_With_Side_Bends/0.jpg','Bosu_Ball_Cable_Crunch_With_Side_Bends/1.jpg']::text[],false),
('Bottoms-Up_Clean_From_The_Hang_Position','Bottoms-Up Clean From The Hang Position','Bottoms-Up Clean From The Hang Position','Force','Avant-bras','Biceps, Épaules','Kettlebell','Intermédiaire',null,array['Initiate the exercise by standing upright with a kettlebell in one hand.','Swing the kettlebell back forcefully and then reverse the motion forcefully. Crush the kettlebell handle as hard as possible and raise the kettlebell to your shoulder.']::text[],array['Bottoms-Up_Clean_From_The_Hang_Position/0.jpg','Bottoms-Up_Clean_From_The_Hang_Position/1.jpg']::text[],false),
('Bottoms_Up','Bottoms Up','Bottoms Up','Force','Abdominaux',null,'Poids du corps','Débutant',null,array['Begin by lying on your back on the ground. Your legs should be straight and your arms at your side. This will be your starting position.','To perform the movement, tuck the knees toward your chest by flexing the hips and knees. Following this, extend your legs directly above you so that they are perpendicular to the ground. Rotate and elevate your pelvis to raise your glutes from the floor.','After a brief pause, return to the starting position.']::text[],array['Bottoms_Up/0.jpg','Bottoms_Up/1.jpg']::text[],false),
('Box_Jump_Multiple_Response','Box jump','Box Jump (Multiple Response)','Explosivité','Ischio-jambiers','Abducteurs, Adducteurs, Mollets, Fessiers, Quadriceps','Autre','Débutant','Saute à pieds joints sur une box, réception souple, redescends en marchant.',array['Assume a relaxed stance facing the box or platform approximately an arm''s length away. Arms should be down at the sides and legs slightly bent.','Using the arms to aid in the initial burst, jump upward and forward, landing with feet simultaneously on top of the box or platform.','Immediately drop or jump back down to the original starting place; then repeat the sequence.']::text[],array['Box_Jump_Multiple_Response/0.jpg','Box_Jump_Multiple_Response/1.jpg']::text[],true),
('Box_Skip','Box Skip','Box Skip','Explosivité','Ischio-jambiers','Abducteurs, Adducteurs, Mollets, Fessiers, Quadriceps','Autre','Débutant',null,array['You will need several boxes lined up about 8 feet apart.','Begin facing the first box with one leg slightly behind the other.','Drive off the back leg, attempting to gain as much height with the hips as possible.','Immediately upon landing on the box, drive the other leg forward and upward to gain height and distance, leaping from the box. Land between the first two boxes with the same leg that landed on the first box.','Then, step to the next box and repeat.']::text[],array['Box_Skip/0.jpg','Box_Skip/1.jpg']::text[],false),
('Box_Squat','Box squat','Box Squat','Force','Quadriceps','Adducteurs, Mollets, Fessiers, Ischio-jambiers, Lombaires','Barre','Intermédiaire','Assieds-toi en arrière sur une box sans relâcher le gainage, marque un temps puis remonte explosivement.',array['The box squat allows you to squat to desired depth and develop explosive strength in the squat movement. Begin in a power rack with a box at the appropriate height behind you. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired.','Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.','With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.','Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe.']::text[],array['Box_Squat/0.jpg','Box_Squat/1.jpg']::text[],true),
('Box_Squat_with_Bands','Box Squat with Bands','Box Squat with Bands','Force','Quadriceps','Abducteurs, Adducteurs, Mollets, Fessiers, Ischio-jambiers, Lombaires','Barre','Avancé',null,array['Begin in a power rack with a box at the appropriate height behind you. Set up the bands on the sleeves, secured to either band pegs, the rack, or dumbbells so that there is appropriate tension. If dumbbells are used, secure them so that they don''t move. Also, ensure that the dumbbells you are using are heavy enough for the bands that you are using. Additional plates can be used to hold the dumbbells down. If more tension is needed, you can either widen the base on the floor or choke the bands. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired.','Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.','With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.','Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe. Use care to return the barbell to the rack.']::text[],array['Box_Squat_with_Bands/0.jpg','Box_Squat_with_Bands/1.jpg']::text[],false),
('Box_Squat_with_Chains','Box Squat with Chains','Box Squat with Chains','Force','Quadriceps','Abducteurs, Adducteurs, Mollets, Fessiers, Ischio-jambiers, Lombaires','Barre','Avancé',null,array['Begin in a power rack with a box at the appropriate height behind you. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired.','To set up the chains, begin by looping the leader chain over the sleeves of the bar. The heavy chain should be attached using a snap hook. Adjust the length of the lead chain so that a few links are still on the floor at the top of the movement.','Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.','With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.','Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe.']::text[],array['Box_Squat_with_Chains/0.jpg','Box_Squat_with_Chains/1.jpg']::text[],false),
('Brachialis-SMR','Brachialis-SMR','Brachialis-SMR','Mobilité','Biceps',null,'Rouleau','Intermédiaire',null,array['Lie on your side, with your upper arm against the foam roller. The upper arm should be more or less aligned with your body, with the outside of the bicep pressed against the foam roller.','Raise your hips off of the floor, supporting your weight on your arm and on your feet. Hold for 10-30 seconds, and then switch sides.']::text[],array['Brachialis-SMR/0.jpg','Brachialis-SMR/1.jpg']::text[],false),
('Bradford_Rocky_Presses','Bradford/Rocky Presses','Bradford/Rocky Presses','Force','Épaules','Triceps','Barre','Débutant',null,array['Sit on a Military Press Bench with a bar at shoulder level with a pronated grip (palms facing forward). Tip: Your grip should be wider than shoulder width and it should create a 90-degree angle between the forearm and the upper arm as the barbell goes down. This is your starting position.','Once you pick up the barbell with the correct grip, lift the bar up over your head by locking your arms.','Now lower the bar down to the back of the head slowly as you inhale.','Lift the bar back up to the starting position as you exhale.','Lower the bar down to the starting position slowly as you inhale. This is one repetition.','Alternate in this manner until you complete the recommended amount of repetitions.']::text[],array['Bradford_Rocky_Presses/0.jpg','Bradford_Rocky_Presses/1.jpg']::text[],false),
('Butt-Ups','Butt-Ups','Butt-Ups','Force','Abdominaux',null,'Poids du corps','Débutant',null,array['Begin a pushup position but with your elbows on the ground and resting on your forearms. Your arms should be bent at a 90 degree angle.','Arch your back slightly out rather than keeping your back completely straight.','Raise your glutes toward the ceiling, squeezing your abs tightly to close the distance between your ribcage and hips. The end result will be that you''ll end up in a high bridge position. Exhale as you perform this portion of the movement.','Lower back down slowly to your starting position as you breathe in. Tip: Don''t let your back sag downwards.','Repeat for the recommended amount of repetitions.']::text[],array['Butt-Ups/0.jpg','Butt-Ups/1.jpg']::text[],false),
('Butt_Lift_Bridge','Pont fessier','Butt Lift (Bridge)','Force','Fessiers','Ischio-jambiers','Poids du corps','Débutant','Allongé sur le dos, pieds à plat. Monte le bassin en serrant les fessiers, marque un temps puis redescends.',array['Lie flat on the floor on your back with the hands by your side and your knees bent. Your feet should be placed around shoulder width. This will be your starting position.','Pushing mainly with your heels, lift your hips off the floor while keeping your back straight. Breathe out as you perform this part of the motion and hold at the top for a second.','Slowly go back to the starting position as you breathe in.']::text[],array['Butt_Lift_Bridge/0.jpg','Butt_Lift_Bridge/1.jpg']::text[],true),
('Butterfly','Pec deck (butterfly)','Butterfly','Force','Pectoraux',null,'Machine','Débutant','Assis à la machine, ramène les bras devant toi en serrant les pectoraux puis reviens lentement.',array['Sit on the machine with your back flat on the pad.','Take hold of the handles. Tip: Your upper arms should be positioned parallel to the floor; adjust the machine accordingly. This will be your starting position.','Push the handles together slowly as you squeeze your chest in the middle. Breathe out during this part of the motion and hold the contraction for a second.','Return back to the starting position slowly as you inhale until your chest muscles are fully stretched.','Repeat for the recommended amount of repetitions.']::text[],array['Butterfly/0.jpg','Butterfly/1.jpg']::text[],true),
('Cable_Chest_Press','Cable Chest Press','Cable Chest Press','Force','Pectoraux','Épaules, Triceps','Poulie','Débutant',null,array['Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and chest up. The elbows should be bent to about 90 degrees. This will be your starting position.','Begin by extending through the elbow, pressing the handles together straight in front of you. Keep your shoulder blades retracted as you execute the movement.','After pausing at full extension, return to th starting position, keeping tension on the cables.','You can also execute this movement with your back off the pad, at an incline or decline, or alternate hands.']::text[],array['Cable_Chest_Press/0.jpg','Cable_Chest_Press/1.jpg']::text[],false),
('Cable_Crossover','Écarté à la poulie vis-à-vis','Cable Crossover','Force','Pectoraux','Épaules','Poulie','Débutant','Poulies hautes, ramène les mains devant toi en arc de cercle, contracte les pectoraux puis reviens.',array['To get yourself into the starting position, place the pulleys on a high position (above your head), select the resistance to be used and hold the pulleys in each hand.','Step forward in front of an imaginary straight line between both pulleys while pulling your arms together in front of you. Your torso should have a small forward bend from the waist. This will be your starting position.','With a slight bend on your elbows in order to prevent stress at the biceps tendon, extend your arms to the side (straight out at both sides) in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms and torso should remain stationary; the movement should only occur at the shoulder joint.','Return your arms back to the starting position as you breathe out. Make sure to use the same arc of motion used to lower the weights.','Hold for a second at the starting position and repeat the movement for the prescribed amount of repetitions.']::text[],array['Cable_Crossover/0.jpg','Cable_Crossover/1.jpg']::text[],true),
('Cable_Crunch','Crunch à la poulie','Cable Crunch','Force','Abdominaux',null,'Poulie','Débutant','À genoux face à la poulie haute, enroule le buste vers le sol en contractant les abdos.',array['Kneel below a high pulley that contains a rope attachment.','Grasp cable rope attachment and lower the rope until your hands are placed next to your face.','Flex your hips slightly and allow the weight to hyperextend the lower back. This will be your starting position.','With the hips stationary, flex the waist as you contract the abs so that the elbows travel towards the middle of the thighs. Exhale as you perform this portion of the movement and hold the contraction for a second.','Slowly return to the starting position as you inhale. Tip: Make sure that you keep constant tension on the abs throughout the movement. Also, do not choose a weight so heavy that the lower back handles the brunt of the work.','Repeat for the recommended amount of repetitions.']::text[],array['Cable_Crunch/0.jpg','Cable_Crunch/1.jpg']::text[],true),
('Cable_Deadlifts','Cable Deadlifts','Cable Deadlifts','Force','Quadriceps','Avant-bras, Fessiers, Ischio-jambiers, Lombaires','Poulie','Débutant',null,array['Move the cables to the bottom of the towers and select an appropriate weight. Stand directly in between the uprights.','To begin, squat down be flexing your hips and knees until you can reach the handles.','After grasping them, begin your ascent. Driving through your heels extend your hips and knees keeping your hands hanging at your side. Keep your head and chest up throughout the movement.','After reaching a full standing position, Return to the starting position and repeat.']::text[],array['Cable_Deadlifts/0.jpg','Cable_Deadlifts/1.jpg']::text[],false),
('Cable_Hammer_Curls_-_Rope_Attachment','Cable Hammer Curls - Rope Attachment','Cable Hammer Curls - Rope Attachment','Force','Biceps',null,'Poulie','Débutant',null,array['Attach a rope attachment to a low pulley and stand facing the machine about 12 inches away from it.','Grasp the rope with a neutral (palms-in) grip and stand straight up keeping the natural arch of the back and your torso stationary.','Put your elbows in by your side and keep them there stationary during the entire movement. Tip: Only the forearms should move; not your upper arms. This will be your starting position.','Using your biceps, pull your arms up as you exhale until your biceps touch your forearms. Tip: Remember to keep the elbows in and your upper arms stationary.','After a 1 second contraction where you squeeze your biceps, slowly start to bring the weight back to the original position.','Repeat for the recommended amount of repetitions.']::text[],array['Cable_Hammer_Curls_-_Rope_Attachment/0.jpg','Cable_Hammer_Curls_-_Rope_Attachment/1.jpg']::text[],false),
('Cable_Hip_Adduction','Cable Hip Adduction','Cable Hip Adduction','Force','Quadriceps',null,'Poulie','Débutant',null,array['Stand in front of a low pulley facing forward with one leg next to the pulley and the other one away.','Attach the ankle cuff to the cable and also to the ankle of the leg that is next to the pulley.','Now step out and away from the stack with a wide stance and grasp the bar of the pulley system.','Stand on the foot that does not have the ankle cuff (the far foot) and allow the leg with the cuff to be pulled towards the low pulley. This will be your starting position.','Now perform the movement by moving the leg with the ankle cuff in front of the far leg by using the inner thighs to abduct the hip. Breathe out during this portion of the movement.','Slowly return to the starting position as you breathe in.','Repeat for the recommended amount of repetitions and then repeat the same movement with the opposite leg.']::text[],array['Cable_Hip_Adduction/0.jpg','Cable_Hip_Adduction/1.jpg']::text[],false),
('Cable_Incline_Pushdown','Cable Incline Pushdown','Cable Incline Pushdown','Force','Dorsaux',null,'Poulie','Débutant',null,array['Lie on incline an bench facing away from a high pulley machine that has a straight bar attachment on it.','Grasp the straight bar attachment overhead with a pronated (overhand; palms down) shoulder width grip and extend your arms in front of you. The bar should be around 2 inches away from your upper thighs. This will be your starting position.','Keeping the upper arms stationary, lift your arms back in a semi circle until the bar is straight over your head. Breathe in during this portion of the movement.','Slowly go back to the starting position using your lats and hold the contraction once you reach the starting position. Breathe out during the execution of this movement.','Repeat for the recommended amount of repetitions.']::text[],array['Cable_Incline_Pushdown/0.jpg','Cable_Incline_Pushdown/1.jpg']::text[],false),
('Cable_Incline_Triceps_Extension','Cable Incline Triceps Extension','Cable Incline Triceps Extension','Force','Triceps',null,'Poulie','Débutant',null,array['Lie on incline an bench facing away from a high pulley machine that has a straight bar attachment on it.','Grasp the straight bar attachment overhead with a pronated (overhand; palms down) narrow grip (less than shoulder width) and keep your elbows tucked in to your sides. Your upper arms should create around a 25 degree angle when measured from the floor.','Keeping the upper arms stationary, extend the arms as you flex the triceps. Breathe out during this portion of the movement and hold the contraction for a second.','Slowly go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],array['Cable_Incline_Triceps_Extension/0.jpg','Cable_Incline_Triceps_Extension/1.jpg']::text[],false),
('Cable_Internal_Rotation','Cable Internal Rotation','Cable Internal Rotation','Force','Épaules',null,'Poulie','Débutant',null,array['Sit next to a low pulley sideways (with legs stretched in front of you or crossed) and grasp the single hand cable attachment with the arm nearest to the cable. Tip: If you can adjust the pulley''s height, you can use a flat bench to sit on instead.','Position the elbow against your side with the elbow bent at 90° and the arm pointing towards the pulley. This will be your starting position.','Pull the single hand cable attachment toward your body by internally rotating your shoulder until your forearm is across your abs. You will be creating an imaginary semi-circle. Tip: The forearm should be perpendicular to your torso at all times.','Slowly go back to the initial position.','Repeat for the recommended amount of repetitions and then repeat the movement with the next arm.']::text[],array['Cable_Internal_Rotation/0.jpg','Cable_Internal_Rotation/1.jpg']::text[],false),
('Cable_Iron_Cross','Cable Iron Cross','Cable Iron Cross','Force','Pectoraux',null,'Poulie','Débutant',null,array['Begin by moving the pulleys to the high position, select the resistance to be used, and take a handle in each hand.','Stand directly between both pulleys with your arms extended out to your sides. Your head and chest should be up while your arms form a "T". This will be your starting position.','Keeping the elbows extended, pull your arms straight to your sides.','Return your arms back to the starting position after a pause at the peak contraction.','Continue the movement for the prescribed number of repetitions.']::text[],array['Cable_Iron_Cross/0.jpg','Cable_Iron_Cross/1.jpg']::text[],false),
('Cable_Judo_Flip','Cable Judo Flip','Cable Judo Flip','Force','Abdominaux',null,'Poulie','Débutant',null,array['Connect a rope attachment to a tower, and move the cable to the lowest pulley position. Stand with your side to the cable with a wide stance, and grab the rope with both hands.','Twist your body away from the pulley as you bring the rope over your shoulder like you''re performing a judo flip.','Shift your weight between your feet as you twist and crunch forward, pulling the cable downward.','Return to the starting position and repeat until failure.','Then, reposition and repeat the same series of movements on the opposite side.']::text[],array['Cable_Judo_Flip/0.jpg','Cable_Judo_Flip/1.jpg']::text[],false),
('Cable_Lying_Triceps_Extension','Cable Lying Triceps Extension','Cable Lying Triceps Extension','Force','Triceps',null,'Poulie','Débutant',null,array['Lie on a flat bench and grasp the straight bar attachment of a low pulley with a narrow overhand grip. Tip: The easiest way to do this is to have someone hand you the bar as you lay down.','With your arms extended, position the bar over your torso. Your arms and your torso should create a 90-degree angle. This will be your starting position.','Lower the bar by bending at the elbow while keeping the upper arms stationary and elbows in. Go down until the bar lightly touches your forehead. Breathe in as you perform this portion of the movement.','Flex the triceps as you lift the bar back to its starting position. Exhale as you perform this portion of the movement.','Hold for a second at the contracted position and repeat for the recommended amount of repetitions.']::text[],array['Cable_Lying_Triceps_Extension/0.jpg','Cable_Lying_Triceps_Extension/1.jpg']::text[],false),
('Cable_One_Arm_Tricep_Extension','Cable One Arm Tricep Extension','Cable One Arm Tricep Extension','Force','Triceps',null,'Poulie','Débutant',null,array['With your right hand, grasp a single handle attached to the high-cable pulley using a supinated (underhand; palms facing up) grip. You should be standing directly in front of the weight stack.','Now pull the handle down so that your upper arm and elbow are locked in to the side of your body. Your upper arm and forearm should form an acute angle (less than 90-degrees). You can keep the other arm by the waist and you can have one leg in front of you and the other one back for better balance. This will be your starting position.','As you contract the triceps, move the single handle attachment down to your side until your arm is straight. Breathe out as you perform this movement. Tip: Only the forearms should move. Your upper arms should remain stationary at all times.','Squeeze the triceps and hold for a second in this contracted position.','Slowly return the handle to the starting position.','Repeat for the recommended amount of repetitions and then perform the same movement with the other arm.']::text[],array['Cable_One_Arm_Tricep_Extension/0.jpg','Cable_One_Arm_Tricep_Extension/1.jpg']::text[],false),
('Cable_Preacher_Curl','Cable Preacher Curl','Cable Preacher Curl','Force','Biceps','Avant-bras','Poulie','Débutant',null,array['Place a preacher bench about 2 feet in front of a pulley machine.','Attach a straight bar to the low pulley.','Sit at the preacher bench with your elbow and upper arms firmly on top of the bench pad and have someone hand you the bar from the low pulley.','Grab the bar and fully extend your arms on top of the preacher bench pad. This will be your starting position.','Now start pilling the weight up towards your shoulders and squeeze the biceps hard at the top of the movement. Exhale as you perform this motion. Also, hold for a second at the top.','Now slowly lower the weight to the starting position.','Repeat for the recommended amount of repetitions.']::text[],array['Cable_Preacher_Curl/0.jpg','Cable_Preacher_Curl/1.jpg']::text[],false),
('Cable_Rear_Delt_Fly','Oiseau à la poulie','Cable Rear Delt Fly','Force','Épaules',null,'Poulie','Débutant','Poulies croisées à hauteur d''épaules, ouvre les bras vers l''arrière.',array['Adjust the pulleys to the appropriate height and adjust the weight. The pulleys should be above your head.','Grab the left pulley with your right hand and the right pulley with your left hand, crossing them in front of you. This will be your starting position.','Initiate the movement by moving your arms back and outward, keeping your arms straight as you execute the movement.','Pause at the end of the motion before returning the handles to the start position.']::text[],array['Cable_Rear_Delt_Fly/0.jpg','Cable_Rear_Delt_Fly/1.jpg']::text[],true),
('Cable_Reverse_Crunch','Cable Reverse Crunch','Cable Reverse Crunch','Force','Abdominaux',null,'Poulie','Débutant',null,array['Connect an ankle strap attachment to a low pulley cable and position a mat on the floor in front of it.','Sit down with your feet toward the pulley and attach the cable to your ankles.','Lie down, elevate your legs and bend your knees at a 90-degree angle. Your legs and the cable should be aligned. If not, adjust the pulley up or down until they are.','With your hands behind your head, bring your knees inward to your torso and elevate your hips off the floor.','Pause for a moment and in a slow and controlled manner drop your hips and bring your legs back to the starting 90-degree angle. You should still have tension on your abs in the resting position.','Repeat the same movement to failure.']::text[],array['Cable_Reverse_Crunch/0.jpg','Cable_Reverse_Crunch/1.jpg']::text[],false),
('Cable_Rope_Overhead_Triceps_Extension','Cable Rope Overhead Triceps Extension','Cable Rope Overhead Triceps Extension','Force','Triceps',null,'Poulie','Débutant',null,array['Attach a rope to the bottom pulley of the pulley machine.','Grasping the rope with both hands, extend your arms with your hands directly above your head using a neutral grip (palms facing each other). Your elbows should be in close to your head and the arms should be perpendicular to the floor with the knuckles aimed at the ceiling. This will be your starting position.','Slowly lower the rope behind your head as you hold the upper arms stationary. Inhale as you perform this movement and pause when your triceps are fully stretched.','Return to the starting position by flexing your triceps as you breathe out.','Repeat for the recommended amount of repetitions.']::text[],array['Cable_Rope_Overhead_Triceps_Extension/0.jpg','Cable_Rope_Overhead_Triceps_Extension/1.jpg']::text[],false),
('Cable_Rope_Rear-Delt_Rows','Cable Rope Rear-Delt Rows','Cable Rope Rear-Delt Rows','Force','Épaules','Biceps, Haut du dos','Poulie','Débutant',null,array['Sit in the same position on a low pulley row station as you would if you were doing seated cable rows for the back.','Attach a rope to the pulley and grasp it with an overhand grip. Your arms should be extended and parallel to the floor with the elbows flared out.','Keep your lower back upright and slide your hips back so that your knees are slightly bent. This will be your starting position.','Pull the cable attachment towards your upper chest, just below the neck, as you keep your elbows up and out to the sides. Continue this motion as you exhale until the elbows travel slightly behind the back. Tip: Keep your upper arms horizontal, perpendicular to the torso and parallel to the floor throughout the motion.','Go back to the initial position where the arms are extended and the shoulders are stretched forward. Inhale as you perform this portion of the movement.','Repeat for the recommended amount of repetitions.']::text[],array['Cable_Rope_Rear-Delt_Rows/0.jpg','Cable_Rope_Rear-Delt_Rows/1.jpg']::text[],false),
('Cable_Russian_Twists','Cable Russian Twists','Cable Russian Twists','Force','Abdominaux',null,'Poulie','Débutant',null,array['Connect a standard handle attachment, and position the cable to a middle pulley position.','Lie on a stability ball perpendicular to the cable and grab the handle with one hand. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable.','Grab the handle with both hands and fully extend your arms above your chest. You hands should be directly in-line with the pulley. If not, adjust the pulley up or down until they are.','Keep your hips elevated and abs engaged. Rotate your torso away from the pulley for a full-quarter rotation. Your body should be flat from head to knees.','Pause for a moment and in a slow and controlled manner reset to the starting position. You should still have side tension on the cable in the resting position.','Repeat the same movement to failure.','Then, reposition and repeat the same series of movements on the opposite side.']::text[],array['Cable_Russian_Twists/0.jpg','Cable_Russian_Twists/1.jpg']::text[],false),
('Cable_Seated_Crunch','Cable Seated Crunch','Cable Seated Crunch','Force','Abdominaux',null,'Poulie','Débutant',null,array['Seat on a flat bench with your back facing a high pulley.','Grasp the cable rope attachment with both hands (with the palms of the hands facing each other) and place your hands securely over both shoulders. Tip: Allow the weight to hyperextend the lower back slightly. This will be your starting position.','With the hips stationary, flex the waist so the elbows travel toward the hips. Breathe out as you perform this step.','As you inhale, go back to the initial position slowly.','Repeat for the recommended amount of repetitions.']::text[],array['Cable_Seated_Crunch/0.jpg','Cable_Seated_Crunch/1.jpg']::text[],false),
('Cable_Seated_Lateral_Raise','Élévations latérales poulie','Cable Seated Lateral Raise','Force','Épaules','Haut du dos, Trapèzes','Poulie','Débutant','À la poulie basse, monte le bras sur le côté jusqu''à l''horizontale puis redescends.',array['Stand in the middle of two low pulleys that are opposite to each other and place a flat bench right behind you (in perpendicular fashion to you; the narrow edge of the bench should be the one behind you). Select the weight to be used on each pulley.','Now sit at the edge of the flat bench behind you with your feet placed in front of your knees.','Bend forward while keeping your back flat and rest your torso on the thighs.','Have someone give you the single handles attached to the pulleys. Grasp the left pulley with the right hand and the right pulley with the left after you select your weight. The pulleys should run under your knees and your arms will be extended with palms facing each other and a slight bend at the elbows. This will be the starting position.','While keeping the arms stationary, raise the upper arms to the sides until they are parallel to the floor and at shoulder height. Exhale during the execution of this movement and hold the contraction for a second.','Slowly lower your arms to the starting position as you inhale.','Repeat for the recommended amount of repetitions. Tip: Maintain upper arms perpendicular to torso and a fixed elbow position (10 degree to 30 degree angle) throughout exercise.']::text[],array['Cable_Seated_Lateral_Raise/0.jpg','Cable_Seated_Lateral_Raise/1.jpg']::text[],true),
('Cable_Shoulder_Press','Cable Shoulder Press','Cable Shoulder Press','Force','Épaules','Triceps','Poulie','Débutant',null,array['Move the cables to the bottom of the towers and select an appropriate weight.','Stand directly in between the uprights. Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position.','Keeping your head and chest up, extend through the elbow to press the handles directly over head.','After pausing at the top, return to the starting position and repeat.']::text[],array['Cable_Shoulder_Press/0.jpg','Cable_Shoulder_Press/1.jpg']::text[],false),
('Cable_Shrugs','Cable Shrugs','Cable Shrugs','Force','Trapèzes',null,'Poulie','Débutant',null,array['Grasp a cable bar attachment that is attached to a low pulley with a shoulder width or slightly wider overhand (palms facing down) grip.','Stand erect close to the pulley with your arms extended in front of you holding the bar. This will be your starting position.','Lift the bar by elevating the shoulders as high as possible as you exhale. Hold the contraction at the top for a second. Tip: The arms should remain extended at all times. Refrain from using the biceps to help lift the bar. Only the shoulders should be moving up and down.','Lower the bar back to the original position.','Repeat for the recommended amount of repetitions.']::text[],array['Cable_Shrugs/0.jpg','Cable_Shrugs/1.jpg']::text[],false),
('Cable_Wrist_Curl','Cable Wrist Curl','Cable Wrist Curl','Force','Avant-bras',null,'Poulie','Débutant',null,array['Start out by placing a flat bench in front of a low pulley cable that has a straight bar attachment.','Use your arms to grab the cable bar with a narrow to shoulder width supinated grip (palms up) and bring them up so that your forearms are resting against the top of your thighs. Your wrists should be hanging just beyond your knees.','Start out by curling your wrist upwards and exhaling. Keep the contraction for a second.','Slowly lower your wrists back down to the starting position while inhaling.','Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.','Repeat for the recommended amount of repetitions.']::text[],array['Cable_Wrist_Curl/0.jpg','Cable_Wrist_Curl/1.jpg']::text[],false),
('Calf-Machine_Shoulder_Shrug','Calf-Machine Shoulder Shrug','Calf-Machine Shoulder Shrug','Force','Trapèzes',null,'Machine','Débutant',null,array['Position yourself on the calf machine so that the shoulder pads are above your shoulders. Your torso should be straight with the arms extended normally by your side. This will be your starting position.','Raise your shoulders up towards your ears as you exhale and hold the contraction for a full second.','Slowly return to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[],array['Calf-Machine_Shoulder_Shrug/0.jpg','Calf-Machine_Shoulder_Shrug/1.jpg']::text[],false),
('Calf_Press','Calf Press','Calf Press','Force','Mollets',null,'Machine','Débutant',null,array['Adjust the seat so that your legs are only slightly bent in the start position. The balls of your feet should be firmly on the platform.','Select an appropriate weight, and grasp the handles. This will be your starting position.','Straighten the legs by extending the knees, just barely lifting the weight from the stack. Your ankle should be fully flexed, toes pointing up. Execute the movement by pressing downward through the balls of your feet as far as possible.','After a brief pause, reverse the motion and repeat.']::text[],array['Calf_Press/0.jpg','Calf_Press/1.jpg']::text[],false),
('Calf_Press_On_The_Leg_Press_Machine','Mollets à la presse','Calf Press On The Leg Press Machine','Force','Mollets',null,'Machine','Débutant','Pointes de pieds en bas du plateau, pousse avec les chevilles puis laisse revenir en étirement.',array['Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance.','Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you without locking your knees. (Note: In some leg press units you can leave the safety bars on for increased safety. If your leg press unit allows for this, then this is the preferred method of performing the exercise.) Your torso and the legs should make perfect 90-degree angle. Now carefully place your toes and balls of your feet on the lower portion of the platform with the heels extending off. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.','Press on the platform by raising your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.','Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.','Repeat for the recommended amount of repetitions.']::text[],array['Calf_Press_On_The_Leg_Press_Machine/0.jpg','Calf_Press_On_The_Leg_Press_Machine/1.jpg']::text[],true),
('Calf_Raise_On_A_Dumbbell','Calf Raise On A Dumbbell','Calf Raise On A Dumbbell','Force','Mollets',null,'Haltères','Intermédiaire',null,array['Hang on to a sturdy object for balance and stand on a dumbbell handle, preferably one with round plates so that it rolls as in this manner you have to work harder to stabilize yourself; thus increasing the effectiveness of the exercise.','Now roll your foot slightly forward so that you can get a nice stretch of the calf. This will be your starting position.','Lift the calf as you roll your foot over the top of the handle so that you get a full extension. Exhale during the execution of this movement. Contract the calf hard at the top and hold for a second. Tip: As you come up, roll the dumbbell slightly backward.','Now inhale as you roll the dumbbell slightly forward as you come down to get a better stretch.','Repeat for the recommended amount of repetitions.']::text[],array['Calf_Raise_On_A_Dumbbell/0.jpg','Calf_Raise_On_A_Dumbbell/1.jpg']::text[],false),
('Calf_Raises_-_With_Bands','Calf Raises - With Bands','Calf Raises - With Bands','Force','Mollets',null,'Élastiques','Débutant',null,array['Grab an exercise band and stand on it with your toes making sure that the length of the band between the foot and the arms is the same for both sides.','While holding the handles of the band, raise the arms to the side of your head as if you were getting ready to perform a shoulder press. The palms should be facing forward with the elbows bent and to the sides. This movement will create tension on the band. This will be your starting position.','Keeping the hands by your shoulder, stand up on your toes as you exhale and contract the calves hard at the top of the movement.','After a one second contraction, slowly go back down to the starting position.','Repeat for the recommended amount of repetitions.']::text[],array['Calf_Raises_-_With_Bands/0.jpg','Calf_Raises_-_With_Bands/1.jpg']::text[],false),
('Calf_Stretch_Elbows_Against_Wall','Calf Stretch Elbows Against Wall','Calf Stretch Elbows Against Wall','Mobilité','Mollets',null,null,'Débutant',null,array['Stand facing a wall from a couple feet away.','Lean against the wall, placing your weight on your forearms.','Attempt to keep your heels on the ground. Hold for 10-20 seconds. You may move further or closer the wall, making it more or less difficult, respectively.']::text[],array['Calf_Stretch_Elbows_Against_Wall/0.jpg','Calf_Stretch_Elbows_Against_Wall/1.jpg']::text[],false),
('Calf_Stretch_Hands_Against_Wall','Étirement mollets au mur','Calf Stretch Hands Against Wall','Mobilité','Mollets',null,null,'Débutant','Mains au mur, une jambe tendue derrière, talon au sol. Tiens 30 secondes.',array['Stand facing a wall from several feet away. Stagger your stance, placing one foot forward.','Lean forward and rest your hands on the wall, keeping your heel, hip and head in a straight line.','Attempt to keep your heel on the ground. Hold for 10-20 seconds and then switch sides.']::text[],array['Calf_Stretch_Hands_Against_Wall/0.jpg','Calf_Stretch_Hands_Against_Wall/1.jpg']::text[],true),
('Calves-SMR','Auto-massage mollets (rouleau)','Calves-SMR','Mobilité','Mollets',null,'Rouleau','Intermédiaire','Rouleau sous les mollets, roule lentement de la cheville au genou.',array['Begin seated on the floor. Place a foam roller underneath your lower leg. Your other leg can either be crossed over the opposite or be placed on the floor, supporting some of your weight. This will be your starting position.','Place your hands to your side or just behind you, and press down to raise your hips off of the floor, placing much of your weight against your calf muscle. Roll from below the knee to above the ankle, pausing at points of tension for 10-30 seconds. Repeat for the other leg.']::text[],array['Calves-SMR/0.jpg','Calves-SMR/1.jpg']::text[],true),
('Car_Deadlift','Car Deadlift','Car Deadlift','Strongman','Quadriceps','Avant-bras, Fessiers, Ischio-jambiers, Lombaires, Trapèzes','Autre','Intermédiaire',null,array['This event apparatus typically has neutral grip handles, however some have a straight bar that you can approach like a normal deadlift. The apparatus can be loaded with a vehicle or other heavy objects such as tractor tires or kegs.','Center yourself between the handles if you are a strong squatter, or back a couple inches if you are a strong deadlifter. You feet should be about hip width apart. Bend at the hip to grip the handles. With your feet and your grip set, take a big breath and then lower your hips and flex the knees.','Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. As the weight comes up, pull your shoulder blades together as you drive your hips forward.','Lower the weight by bending at the hips and guiding it to the floor.']::text[],array['Car_Deadlift/0.jpg','Car_Deadlift/1.jpg']::text[],false),
('Car_Drivers','Car Drivers','Car Drivers','Force','Épaules','Avant-bras','Barre','Débutant',null,array['While standing upright, hold a barbell plate in both hands at the 3 and 9 o''clock positions. Your palms should be facing each other and your arms should be extended straight out in front of you. This will be your starting position.','Initiate the movement by rotating the plate as far to one side as possible. Use the same type of movement you would use to turn a steering wheel to one side.','Reverse the motion, turning it all the way to the opposite side.','Repeat for the recommended amount of repetitions.']::text[],array['Car_Drivers/0.jpg','Car_Drivers/1.jpg']::text[],false),
('Carioca_Quick_Step','Carioca Quick Step','Carioca Quick Step','Explosivité','Adducteurs','Abdominaux, Abducteurs, Mollets, Fessiers, Ischio-jambiers, Quadriceps',null,'Débutant',null,array['Begin with your feet a few inches apart and your left arm up in a relaxed, athletic position.','With your right foot, quick step behind and pull the knee up.','Fire your arms back up when you pull the right knee, being sure that your knee goes straight up and down. Avoid turning your feet as you move and continue to look forward as you move to the side.']::text[],array['Carioca_Quick_Step/0.jpg','Carioca_Quick_Step/1.jpg']::text[],false),
('Cat_Stretch','Étirement chat-vache','Cat Stretch','Mobilité','Lombaires','Haut du dos, Trapèzes',null,'Débutant','À quatre pattes, alterne dos rond et dos creux lentement.',array['Position yourself on the floor on your hands and knees.','Pull your belly in and round your spine, lower back, shoulders, and neck, letting your head drop.','Hold for 15 seconds.']::text[],array['Cat_Stretch/0.jpg','Cat_Stretch/1.jpg']::text[],true),
('Catch_and_Overhead_Throw','Catch and Overhead Throw','Catch and Overhead Throw','Explosivité','Dorsaux','Abdominaux, Pectoraux, Épaules','Médecine-ball','Débutant',null,array['Begin standing while facing a wall or a partner.','Using both hands, position the ball behind your head, stretching as much as possible, and forcefully throw the ball forward.','Ensure that you follow your throw through, being prepared to receive your rebound from your throw. If you are throwing against the wall, make sure that you stand close enough to the wall to receive the rebound, and aim a little higher than you would with a partner.']::text[],array['Catch_and_Overhead_Throw/0.jpg','Catch_and_Overhead_Throw/1.jpg']::text[],false),
('Chain_Handle_Extension','Chain Handle Extension','Chain Handle Extension','Force','Triceps',null,'Autre','Intermédiaire',null,array['You will need two cable handle attachments and a flat bench, as well as chains, for this exercise. Clip the middle of the chains to the handles, and position yourself on the flat bench. Your elbows should be pointing straight up.','Begin by extending through the elbow, keeping your upper arm still, with your wrists pronated.','Pause at the lockout, and reverse the motion to return to the starting position.']::text[],array['Chain_Handle_Extension/0.jpg','Chain_Handle_Extension/1.jpg']::text[],false),
('Chain_Press','Chain Press','Chain Press','Force','Pectoraux','Épaules, Triceps','Autre','Intermédiaire',null,array['Begin by connecting the chains to the cable handle attachments. Position yourself on the flat bench in the same position as for a dumbbell press. Your wrists should be pronated and arms perpendicular to the floor. This will be your starting position.','Lower the chains by flexing the elbows, unloading some of the chain onto the floor.','Continue until your elbow forms a 90 degree angle, and then reverse the motion by extending through the elbow to lockout.']::text[],array['Chain_Press/0.jpg','Chain_Press/1.jpg']::text[],false),
('Chair_Leg_Extended_Stretch','Chair Leg Extended Stretch','Chair Leg Extended Stretch','Mobilité','Ischio-jambiers','Adducteurs','Autre','Débutant',null,array['Sit upright in a chair and grip the seat on the sides.','Raise one leg, extending the knee, flexing the ankle as you do so.','Slowly move that leg outward as far as you can, and then back to the center and down.','Repeat for your other leg.']::text[],array['Chair_Leg_Extended_Stretch/0.jpg','Chair_Leg_Extended_Stretch/1.jpg']::text[],false),
('Chair_Lower_Back_Stretch','Chair Lower Back Stretch','Chair Lower Back Stretch','Mobilité','Dorsaux','Lombaires',null,'Débutant',null,array['Sit upright on a chair.','Bend to one side with your arm over your head. You can hold onto the chair with your free hand.','Hold for 10 seconds, and repeat for your other side.']::text[],array['Chair_Lower_Back_Stretch/0.jpg','Chair_Lower_Back_Stretch/1.jpg']::text[],false),
('Chair_Squat','Chair Squat','Chair Squat','Force','Quadriceps','Mollets, Fessiers, Ischio-jambiers','Machine','Débutant',null,array['To begin, first set the bar to a position that best matches your height. Once the bar is loaded, step under it and position it across the back of your shoulders.','Take the bar with your hands facing forward, unlock it and lift it off the rack by extending your legs.','Move your feet forward about 18 inches in front of the bar. Position your legs using a shoulder width stance with the toes slightly pointed out. Look forward at all times and maintain a neutral or slightly arched spine. This will be your starting position.','Slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper and lower leg breaks 90 degrees.','Begin to raise the bar as you exhale by pushing the floor with the heels of your feet, extending the knees and returning to the starting position.','Repeat for the recommended amount of repetitions.']::text[],array['Chair_Squat/0.jpg','Chair_Squat/1.jpg']::text[],false),
('Chair_Upper_Body_Stretch','Chair Upper Body Stretch','Chair Upper Body Stretch','Mobilité','Épaules','Biceps, Pectoraux','Autre','Débutant',null,array['Sit on the edge of a chair, gripping the back of it.','Straighten your arms, keeping your back straight, and pull your upper body forward so you feel a stretch. Hold for 20-30 seconds.']::text[],array['Chair_Upper_Body_Stretch/0.jpg','Chair_Upper_Body_Stretch/1.jpg']::text[],false),
('Chest_And_Front_Of_Shoulder_Stretch','Chest And Front Of Shoulder Stretch','Chest And Front Of Shoulder Stretch','Mobilité','Pectoraux','Épaules','Autre','Débutant',null,array['Start off by standing with your legs together, holding a bodybar or a broomstick.','Take a slightly wider than shoulder width grip on the pole and hold it in front of you with your palms facing down.','Carefully lift the pole up and behind your head.']::text[],array['Chest_And_Front_Of_Shoulder_Stretch/0.jpg','Chest_And_Front_Of_Shoulder_Stretch/1.jpg']::text[],false),
('Chest_Push_from_3_point_stance','Chest Push from 3 point stance','Chest Push from 3 point stance','Explosivité','Pectoraux','Abdominaux, Épaules, Triceps','Médecine-ball','Débutant',null,array['Begin in a three point stance, squatted down with your back flat and one hand on the ground. Place the medicine ball directly in front of you.','To begin, take your first step as you pull the ball to your chest, positioning both hands to prepare for the throw.','As you execute the second step, explosively release the ball forward as hard as possible.']::text[],array['Chest_Push_from_3_point_stance/0.jpg','Chest_Push_from_3_point_stance/1.jpg']::text[],false),
('Chest_Push_multiple_response','Chest Push (multiple response)','Chest Push (multiple response)','Explosivité','Pectoraux','Abdominaux, Épaules, Triceps','Médecine-ball','Débutant',null,array['Begin in a kneeling position facing a wall or utilize a partner. Hold the ball with both hands tight into the chest.','Execute the pass by exploding forward and outward with the hips while pushing the ball as hard as possible.','Follow through by falling forward, catching yourself with your hands.','Immediately return to an upright position. Repeat for the desired number of repetitions.']::text[],array['Chest_Push_multiple_response/0.jpg','Chest_Push_multiple_response/1.jpg']::text[],false),
('Chest_Push_single_response','Chest Push (single response)','Chest Push (single response)','Explosivité','Pectoraux','Abdominaux, Épaules, Triceps','Médecine-ball','Débutant',null,array['Begin in a kneeling position holding the medicine ball with both hands tightly into the chest.','Execute the pass by exploding forward and outward with the hips while pushing the ball as far as possible.','Follow through by falling forward, catching yourself with your hands.']::text[],array['Chest_Push_single_response/0.jpg','Chest_Push_single_response/1.jpg']::text[],false),
('Chest_Push_with_Run_Release','Chest Push with Run Release','Chest Push with Run Release','Explosivité','Pectoraux','Abdominaux, Épaules, Triceps','Médecine-ball','Débutant',null,array['Begin in an athletic stance with the knees bent, hips back, and back flat. Hold the medicine ball near your legs. This will be your starting position.','While taking your first step draw the medicine ball into your chest.','As you take the second step, explosively push the ball forward, immediately sprinting for 10 yards after the release. If you are really fast, you can catch your own pass!']::text[],array['Chest_Push_with_Run_Release/0.jpg','Chest_Push_with_Run_Release/1.jpg']::text[],false),
('Chest_Stretch_on_Stability_Ball','Chest Stretch on Stability Ball','Chest Stretch on Stability Ball','Mobilité','Pectoraux',null,'Swiss ball','Débutant',null,array['Get on your hands and knees next to an exercise ball.','Place your elbows on top of the ball, keeping your arm out to your side. This will be your starting position.','Lower your torso towards the floor, keeping your elbow on top of the ball. Hold the stretch for 20-30 seconds, and repeat with the other arm.']::text[],array['Chest_Stretch_on_Stability_Ball/0.jpg','Chest_Stretch_on_Stability_Ball/1.jpg']::text[],false),
('Childs_Pose','Posture de l''enfant','Child''s Pose','Mobilité','Lombaires','Fessiers, Haut du dos',null,'Débutant','À genoux, assis sur les talons, allonge les bras devant toi et relâche le dos.',array['Get on your hands and knees, walk your hands in front of you.','Lower your buttocks down to sit on your heels. Let your arms drag along the floor as you sit back to stretch your entire spine.','Once you settle onto your heels, bring your hands next to your feet and relax. "breathe" into your back. Rest your forehead on the floor. Avoid this position if you have knee problems.']::text[],array['Childs_Pose/0.jpg','Childs_Pose/1.jpg']::text[],true),
('Chin-Up','Tractions supination (chin-up)','Chin-Up','Force','Dorsaux','Biceps, Avant-bras, Haut du dos','Poids du corps','Débutant','Paumes vers toi, mains largeur d''épaules. Monte le menton au-dessus de la barre puis redescends lentement.',array['Grab the pull-up bar with the palms facing your torso and a grip closer than the shoulder width.','As you have both arms extended in front of you holding the bar at the chosen grip width, keep your torso as straight as possible while creating a curvature on your lower back and sticking your chest out. This is your starting position. Tip: Keeping the torso as straight as possible maximizes biceps stimulation while minimizing back involvement.','As you breathe out, pull your torso up until your head is around the level of the pull-up bar. Concentrate on using the biceps muscles in order to perform the movement. Keep the elbows close to your body. Tip: The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.','After a second of squeezing the biceps in the contracted position, slowly lower your torso back to the starting position; when your arms are fully extended. Breathe in as you perform this portion of the movement.','Repeat this motion for the prescribed amount of repetitions.']::text[],array['Chin-Up/0.jpg','Chin-Up/1.jpg']::text[],true),
('Chin_To_Chest_Stretch','Chin To Chest Stretch','Chin To Chest Stretch','Mobilité','Cou','Trapèzes',null,'Débutant',null,array['Get into a seated position on the floor.','Place both hands at the rear of your head, fingers interlocked, thumbs pointing down and elbows pointing straight ahead. Slowly pull your head down to your chest. Hold for 20-30 seconds.']::text[],array['Chin_To_Chest_Stretch/0.jpg','Chin_To_Chest_Stretch/1.jpg']::text[],false),
('Circus_Bell','Circus Bell','Circus Bell','Strongman','Épaules','Avant-bras, Fessiers, Ischio-jambiers, Lombaires, Trapèzes, Triceps','Autre','Avancé',null,array['The circus bell is an oversized dumbbell with a thick handle. Begin with the dumbbell between your feet, and grip the handle with both hands.','Clean the dumbbell by extending through your hips and knees to deliver the implement to the desired shoulder, letting go with the extra hand.','Ensure that you get one of the dumbbell heads behind the shoulder to keep from being thrown off balance. To raise it overhead, dip by flexing the knees, and the drive upwards as you extend the dumbbell overhead, leaning slightly away from it as you do so.','Carefully guide the bell back to the floor, keeping it under control as much as possible. It is best to perform this event on a thick rubber mat to prevent damage to the floor.']::text[],array['Circus_Bell/0.jpg','Circus_Bell/1.jpg']::text[],false),
('Clean','Clean','Clean','Haltérophilie','Ischio-jambiers','Mollets, Avant-bras, Fessiers, Lombaires, Quadriceps, Épaules, Trapèzes','Barre','Intermédiaire',null,array['With a barbell on the floor close to the shins, take an overhand (or hook) grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.','','Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.','Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.','As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.','Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.']::text[],array['Clean/0.jpg','Clean/1.jpg']::text[],false),
('Clean_Deadlift','Clean Deadlift','Clean Deadlift','Haltérophilie','Ischio-jambiers','Avant-bras, Fessiers, Lombaires, Haut du dos, Quadriceps, Trapèzes','Barre','Débutant',null,array['Begin standing with a barbell close to your shins. Your feet should be directly under your hips with your feet turned out slightly. Grip the bar with a double overhand grip or hook grip, about shoulder width apart. Squat down to the bar. Your spine should be in full extension, with a back angle that places your shoulders in front of the bar and your back as vertical as possible.','Begin by driving through the floor through the front of your heels. As the bar travels upward, maintain a constant back angle. Flare your knees out to the side to help keep them out of the bar''s path.','After the bar crosses the knees, complete the lift by driving the hips into the bar until your hips and knees are extended.']::text[],array['Clean_Deadlift/0.jpg','Clean_Deadlift/1.jpg']::text[],false),
('Clean_Pull','Clean Pull','Clean Pull','Haltérophilie','Quadriceps','Avant-bras, Fessiers, Ischio-jambiers, Lombaires, Trapèzes','Barre','Intermédiaire',null,array['With a barbell on the floor close to the shins, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.','Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight and elbows out. Move the weight with control as you continue to above the knees.','Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended. Full extension should be violent and abrupt, and ensure that you do not prolong the extension for longer than necessary.']::text[],array['Clean_Pull/0.jpg','Clean_Pull/1.jpg']::text[],false),
('Clean_Shrug','Clean Shrug','Clean Shrug','Haltérophilie','Trapèzes','Avant-bras, Épaules','Barre','Débutant',null,array['Begin with a shoulder width, double overhand or hook grip, with the bar hanging at the mid thigh position. Your back should be straight and inclined slightly forward.','Shrug your shoulders towards your ears. While this exercise can usually by loaded with heavier weight than a clean, avoid overloading to the point that the execution slows down.']::text[],array['Clean_Shrug/0.jpg','Clean_Shrug/1.jpg']::text[],false),
('Clean_and_Jerk','Épaulé-jeté','Clean and Jerk','Haltérophilie','Épaules','Abdominaux, Fessiers, Ischio-jambiers, Lombaires, Quadriceps, Trapèzes, Triceps','Barre','Avancé','Épaule la barre puis jette-la au-dessus de la tête en fente.',array['With a barbell on the floor close to the shins, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.','Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.','Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.','As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.','Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.','The second phase is the jerk, which raises the weight overhead. Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible.','Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders.','At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible. In the brief moment the feet are not actively driving against the platform, the athletes effort to push the bar up will drive them down. The feet should be split, with one foot forward, and one foot back. Receive the bar with the arms locked out overhead. Return to a standing position.']::text[],array['Clean_and_Jerk/0.jpg','Clean_and_Jerk/1.jpg']::text[],true),
('Clean_and_Press','Clean and Press','Clean and Press','Force','Épaules','Abdominaux, Mollets, Fessiers, Ischio-jambiers, Lombaires, Haut du dos, Quadriceps, Épaules, Trapèzes, Triceps','Barre','Intermédiaire',null,array['Assume a shoulder-width stance, with knees inside the arms. Now while keeping the back flat, bend at the knees and hips so that you can grab the bar with the arms fully extended and a pronated grip that is slightly wider than shoulder width. Point the elbows out to sides. The bar should be close to the shins. Position the shoulders over or slightly ahead of the bar. Establish a flat back posture. This will be your starting position.','Begin to pull the bar by extending the knees. Move your hips forward and raise the shoulders at the same rate while keeping the angle of the back constant; continue to lift the bar straight up while keeping it close to your body.','As the bar passes the knee, extend at the ankles, knees, and hips forcefully, similar to a jumping motion. As you do so, continue to guide the bar with your hands, shrugging your shoulders and using the momentum from your movement to pull the bar as high as possible. The bar should travel close to your body, and you should keep your elbows out.','At maximum elevation, your feet should clear the floor and you should start to pull yourself under the bar. The mechanics of this could change slightly, depending on the weight used. You should descend into a squatting position as you pull yourself under the bar.','As the bar hits terminal height, rotate your elbows around and under the bar. Rack the bar across the front of the shoulders while keeping the torso erect and flexing the hips and knees to absorb the weight of the bar.','Stand to full height, holding the bar in the clean position.','Without moving your feet, press the bar overhead as you exhale. Lower the bar under control .']::text[],array['Clean_and_Press/0.jpg','Clean_and_Press/1.jpg']::text[],false),
('Clean_from_Blocks','Clean from Blocks','Clean from Blocks','Haltérophilie','Quadriceps','Mollets, Fessiers, Ischio-jambiers, Épaules, Trapèzes','Barre','Intermédiaire',null,array['With a barbell on boxes or stands of the desired height, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.','Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight with the elbows pointed out.','As full extension is achieved, transition into the receiving position by aggressively shrugging and flexing the arms with the elbows up and out. Aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.','Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position. Return the weight to the boxes for the next rep.']::text[],array['Clean_from_Blocks/0.jpg','Clean_from_Blocks/1.jpg']::text[],false),
('Clock_Push-Up','Clock Push-Up','Clock Push-Up','Force','Pectoraux','Épaules, Triceps','Poids du corps','Intermédiaire',null,array['Move into a prone position on the floor, supporting your weight on your hands and toes.','Your arms should be fully extended with the hands around shoulder width. Keep your body straight throughout the movement. This will be your starting position.','Descend by flexing at the elbow, lowering your chest toward the ground.','At the bottom, reverse the motion by pushing yourself up through elbow extension as quickly as possible until you are air borne. Aim to "jump" 12-18 inches to one side.','As you accelerate up, move your outside foot away from your direction of travel. Leaving the ground, shift your body about 30 degrees for the next repetition.','Return to the starting position and repeat the exercise, working all the way around until you are back where you started.']::text[],array['Clock_Push-Up/0.jpg','Clock_Push-Up/1.jpg']::text[],false),
('Close-Grip_Barbell_Bench_Press','Développé couché prise serrée','Close-Grip Barbell Bench Press','Force','Triceps','Pectoraux, Épaules','Barre','Débutant','Mains largeur d''épaules, coudes près du corps. Descends vers le bas des pectoraux puis pousse.',array['Lie back on a flat bench. Using a close grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.','As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that - as opposed to a regular bench press - you keep the elbows close to the torso at all times in order to maximize triceps involvement.','After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.','Repeat the movement for the prescribed amount of repetitions.','When you are done, place the bar back in the rack.']::text[],array['Close-Grip_Barbell_Bench_Press/0.jpg','Close-Grip_Barbell_Bench_Press/1.jpg']::text[],true),
('Close-Grip_Dumbbell_Press','Close-Grip Dumbbell Press','Close-Grip Dumbbell Press','Force','Triceps','Pectoraux, Épaules','Haltères','Débutant',null,array['Place a dumbbell standing up on a flat bench.','Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench with only your shoulders lying on the surface. Hips should be below the bench and your legs bent with your feet firmly on the floor.','Grasp the dumbbell with both hands and hold it straight over your chest at arm''s length. Both palms should be pressing against the underside of the sides of the dumbbell. This will be your starting position.','Initiate the movement by lowering the dumbbell to your chest.','Return to the starting position by extending the elbows.']::text[],array['Close-Grip_Dumbbell_Press/0.jpg','Close-Grip_Dumbbell_Press/1.jpg']::text[],false),
('Close-Grip_EZ-Bar_Curl_with_Band','Close-Grip EZ-Bar Curl with Band','Close-Grip EZ-Bar Curl with Band','Force','Biceps','Avant-bras','Barre EZ','Débutant',null,array['Attach a band to each end of the bar. Take the bar, placing a foot on the middle of the band. Stand upright with a narrow, supinated grip on the EZ bar. The elbows should be close to the torso. This will be your starting position.','While keeping the upper arms in place, flex the elbows to execute the curl. Exhale as the weight is lifted.','Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.','Slowly begin to bring the bar back to starting position as your breathe in.','Repeat for the recommended amount of repetitions.']::text[],array['Close-Grip_EZ-Bar_Curl_with_Band/0.jpg','Close-Grip_EZ-Bar_Curl_with_Band/1.jpg']::text[],false),
('Close-Grip_EZ-Bar_Press','Close-Grip EZ-Bar Press','Close-Grip EZ-Bar Press','Force','Triceps','Pectoraux, Épaules','Barre EZ','Débutant',null,array['Lie on a flat bench with an EZ bar loaded to an appropriate weight.','Using a narrow grip lift the bar and hold it straight over your torso with your elbows in. The arms should be perpendicular to the floor. This will be your starting position.','Now lower the bar down to your lower chest as you breathe in. Keep the elbows in as you perform this movement.','Using the triceps to push the bar back up, press it back to the starting position by extending the elbows as you exhale.','Repeat.']::text[],array['Close-Grip_EZ-Bar_Press/0.jpg','Close-Grip_EZ-Bar_Press/1.jpg']::text[],false),
('Close-Grip_EZ_Bar_Curl','Close-Grip EZ Bar Curl','Close-Grip EZ Bar Curl','Force','Biceps','Avant-bras','Barre','Débutant',null,array['Stand up with your torso upright while holding an E-Z Curl Bar at the closer inner handle. The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar. The elbows should be close to the torso. This will be your starting position.','While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.','Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.','Slowly begin to bring the bar back to starting position as your breathe in.','Repeat for the recommended amount of repetitions.']::text[],array['Close-Grip_EZ_Bar_Curl/0.jpg','Close-Grip_EZ_Bar_Curl/1.jpg']::text[],false),
('Close-Grip_Front_Lat_Pulldown','Tirage vertical prise serrée','Close-Grip Front Lat Pulldown','Force','Dorsaux','Biceps, Haut du dos, Épaules','Poulie','Débutant','Prise serrée, tire vers le haut de la poitrine en gardant le buste légèrement incliné.',array['Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.','Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.','As you have both arms extended in front of you - while holding the bar at the chosen grip width - bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.','As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary (only the arms should move). The forearms should do no other work except for holding the bar; therefore do not try to pull the bar down using the forearms.','After a second in the contracted position, while squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.','6. Repeat this motion for the prescribed amount of repetitions.']::text[],array['Close-Grip_Front_Lat_Pulldown/0.jpg','Close-Grip_Front_Lat_Pulldown/1.jpg']::text[],true),
('Close-Grip_Push-Up_off_of_a_Dumbbell','Close-Grip Push-Up off of a Dumbbell','Close-Grip Push-Up off of a Dumbbell','Force','Triceps','Abdominaux, Pectoraux, Épaules','Poids du corps','Intermédiaire',null,array['Lie on the floor and place your hands on an upright dumbbell. Supporting your weight on your toes and hands, keep your torso rigid and your elbows in with your arms straight. This will be your starting position.','Lower your body, allowing the elbows to flex while you inhale. Keep your body straight, not allowing your hips to rise or sag.','Press yourself back up to the starting position by extending the elbows. Breathe out as you perform this step.','After a pause at the contracted position, repeat the movement for the prescribed amount of repetitions.']::text[],array['Close-Grip_Push-Up_off_of_a_Dumbbell/0.jpg','Close-Grip_Push-Up_off_of_a_Dumbbell/1.jpg']::text[],false),
('Close-Grip_Standing_Barbell_Curl','Close-Grip Standing Barbell Curl','Close-Grip Standing Barbell Curl','Force','Biceps','Avant-bras','Barre','Débutant',null,array['Hold a barbell with both hands, palms up and a few inches apart.','Stand with your torso straight and your head up. Your feet should be about shoulder width and your elbows close to your torso. This will be your starting position. Tip: You will keep your upper arms and elbows stationary throughout the movement.','Curl the bar up in a semicircular motion until the forearms touch your biceps. Exhale as you perform this portion of the movement and contract your biceps hard for a second at the top. Tip: Avoid bending the back or using swinging motions as you lift the weight. Only the forearms should move.','Slowly go back down to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[],array['Close-Grip_Standing_Barbell_Curl/0.jpg','Close-Grip_Standing_Barbell_Curl/1.jpg']::text[],false),
('Cocoons','Cocoons','Cocoons','Force','Abdominaux',null,'Poids du corps','Débutant',null,array['Begin by lying on your back on the ground. Your legs should be straight and your arms extended behind your head. This will be your starting position.','To perform the movement, tuck the knees toward your chest, rotating your pelvis to lift your glutes from the floor. As you do so, flex the spine, bringing your arms back over your head to perform a simultaneous crunch motion.','After a brief pause, return to the starting position.']::text[],array['Cocoons/0.jpg','Cocoons/1.jpg']::text[],false),
('Conans_Wheel','Conan''s Wheel','Conan''s Wheel','Strongman','Quadriceps','Abdominaux, Biceps, Mollets, Avant-bras, Lombaires, Épaules, Trapèzes','Autre','Intermédiaire',null,array['With the weight loaded, take a zurcher hold on the end of the implement. Place the bar in the crook of the elbow and hold onto your wrist. Try to keep the weight off of the forearms.','Begin by lifting the weight from the ground. Keep a tight, upright posture as you being to walk, taking short, fast steps. Look up and away as you turn in a circle. Do not hold your breath during the event. Continue walking until you complete one or more complete turns.']::text[],array['Conans_Wheel/0.jpg','Conans_Wheel/1.jpg']::text[],false),
('Concentration_Curls','Curl concentré','Concentration Curls','Force','Biceps','Avant-bras','Haltères','Débutant','Assis, coude calé contre l''intérieur de la cuisse, monte l''haltère vers l''épaule.',array['Sit down on a flat bench with one dumbbell in front of you between your legs. Your legs should be spread with your knees bent and feet on the floor.','Use your right arm to pick the dumbbell up. Place the back of your right upper arm on the top of your inner right thigh. Rotate the palm of your hand until it is facing forward away from your thigh. Tip: Your arm should be extended and the dumbbell should be above the floor. This will be your starting position.','While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Tip: At the top of the movement make sure that the little finger of your arm is higher than your thumb. This guarantees a good contraction. Hold the contracted position for a second as you squeeze the biceps.','Slowly begin to bring the dumbbells back to starting position as your breathe in. Caution: Avoid swinging motions at any time.','Repeat for the recommended amount of repetitions. Then repeat the movement with the left arm.']::text[],array['Concentration_Curls/0.jpg','Concentration_Curls/1.jpg']::text[],true),
('Cross-Body_Crunch','Cross-Body Crunch','Cross-Body Crunch','Force','Abdominaux',null,'Poids du corps','Débutant',null,array['Lie flat on your back and bend your knees about 60 degrees.','Keep your feet flat on the floor and place your hands loosely behind your head. This will be your starting position.','Now curl up and bring your right elbow and shoulder across your body while bring your left knee in toward your left shoulder at the same time. Reach with your elbow and try to touch your knee. Exhale as you perform this movement. Tip: Try to bring your shoulder up towards your knee rather than just your elbow and remember that the key is to contract the abs as you perform the movement; not just to move the elbow.','Now go back down to the starting position as you inhale and repeat with the left elbow and the right knee.','Continue alternating in this manner until all prescribed repetitions are done.']::text[],array['Cross-Body_Crunch/0.jpg','Cross-Body_Crunch/1.jpg']::text[],false),
('Cross_Body_Hammer_Curl','Cross Body Hammer Curl','Cross Body Hammer Curl','Force','Biceps','Avant-bras','Haltères','Débutant',null,array['Stand up straight with a dumbbell in each hand. Your hands should be down at your side with your palms facing in.','While keeping your palms facing in and without twisting your arm, curl the dumbbell of the right arm up towards your left shoulder as you exhale. Touch the top of the dumbbell to your shoulder and hold the contraction for a second.','Slowly lower the dumbbell along the same path as you inhale and then repeat the same movement for the left arm.','Continue alternating in this fashion until the recommended amount of repetitions is performed for each arm.']::text[],array['Cross_Body_Hammer_Curl/0.jpg','Cross_Body_Hammer_Curl/1.jpg']::text[],false),
('Cross_Over_-_With_Bands','Cross Over - With Bands','Cross Over - With Bands','Force','Pectoraux','Biceps, Épaules','Élastiques','Débutant',null,array['Secure an exercise band around a stationary post.','While facing away from the post, grab the handles on both ends of the band and step forward enough to create tension on the band.','Raise your arms to the sides, parallel to the floor, perpendicular to your torso (your torso and the arms should resemble the letter "T") and with the palms facing forward. Have them extended with a slight bend at the elbows. This will be your starting position.','While keeping your arms straight, bring them across your chest in a semicircular motion to the front as you exhale and flex your pecs. Hold the contraction for a second.','Slowly return to the starting position as you inhale.','Perform for the recommended amount of repetitions.']::text[],array['Cross_Over_-_With_Bands/0.jpg','Cross_Over_-_With_Bands/1.jpg']::text[],false),
('Crossover_Reverse_Lunge','Crossover Reverse Lunge','Crossover Reverse Lunge','Mobilité','Lombaires','Abdominaux, Abducteurs, Fessiers, Ischio-jambiers, Quadriceps',null,'Intermédiaire',null,array['Stand with your feet shoulder width apart. This will be your starting position.','Perform a rear lunge by stepping back with one foot and flexing the hips and front knee. As you do so, rotate your torso across the front leg.','After a brief pause, return to the starting position and repeat on the other side, continuing in an alternating fashion.']::text[],array['Crossover_Reverse_Lunge/0.jpg','Crossover_Reverse_Lunge/1.jpg']::text[],false),
('Crucifix','Crucifix','Crucifix','Strongman','Épaules','Avant-bras','Autre','Débutant',null,array['In the crucifix, you statically hold weights out to the side for time. While the event can be practiced using dumbbells, it is best to practice with one of the various implements used, such as axes and hammers, as it feels different.','Begin standing, and raise your arms out to the side holding the implements. Your arms should be parallel to the ground. In competition, judges or sensors are used to let you know when you break parallel. Hold for as long as you can. Typically, the weights should be heavy enough that you fail in 30-60 seconds.']::text[],array['Crucifix/0.jpg','Crucifix/1.jpg']::text[],false),
('Crunch_-_Hands_Overhead','Crunch - Hands Overhead','Crunch - Hands Overhead','Force','Abdominaux',null,'Poids du corps','Débutant',null,array['Lie on the floor with your back flat and knees bent with around a 60-degree angle between the hamstrings and the calves.','Keep your feet flat on the floor and stretch your arms overhead with your palms crossed. This will be your starting position.','Curl your upper body forward and bring your shoulder blades just off the floor. At all times, keep your arms aligned with your head, neck and shoulder. Don''t move them forward from that position. Exhale as you perform this portion of the movement and hold the contraction for a second.','Slowly lower down to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[],array['Crunch_-_Hands_Overhead/0.jpg','Crunch_-_Hands_Overhead/1.jpg']::text[],false),
('Crunch_-_Legs_On_Exercise_Ball','Crunch - Legs On Exercise Ball','Crunch - Legs On Exercise Ball','Force','Abdominaux',null,'Poids du corps','Débutant',null,array['Lie flat on your back with your feet resting on an exercise ball and your knees bent at a 90 degree angle.','Place your feet three to four inches apart and point your toes inward so they touch.','Place your hands lightly on either side of your head keeping your elbows in. Tip: Don''t lock your fingers behind your head.','Push the small of your back down in the floor in order to better isolate your abdominal muscles. This will be your starting position.','Begin to roll your shoulders off the floor and continue to push down as hard as you can with your lower back. Your shoulders should come up off the floor only about four inches, and your lower back should remain on the floor. Breathe out as you execute this portion of the movement. Squeeze your abdominals hard at the top of the contraction and hold for a second. Tip: Focus on a slow, controlled movement. Refrain from using momentum at any time.','Slowly go back down to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[],array['Crunch_-_Legs_On_Exercise_Ball/0.jpg','Crunch_-_Legs_On_Exercise_Ball/1.jpg']::text[],false),
('Crunches','Crunch','Crunches','Force','Abdominaux',null,'Poids du corps','Débutant','Allongé, genoux fléchis, enroule le haut du dos vers les genoux en expirant puis redescends.',array['Lie flat on your back with your feet flat on the ground, or resting on a bench with your knees bent at a 90 degree angle. If you are resting your feet on a bench, place them three to four inches apart and point your toes inward so they touch.','Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don''t lock your fingers behind your head.','While pushing the small of your back down in the floor to better isolate your abdominal muscles, begin to roll your shoulders off the floor.','Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the floor only about four inches, and your lower back should remain on the floor. At the top of the movement, contract your abdominals hard and keep the contraction for a second. Tip: Focus on slow, controlled movement - don''t cheat yourself by using momentum.','After the one second contraction, begin to come down slowly again to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[],array['Crunches/0.jpg','Crunches/1.jpg']::text[],true),
('Cuban_Press','Cuban Press','Cuban Press','Force','Épaules','Trapèzes','Haltères','Intermédiaire',null,array['Take a dumbbell in each hand with a pronated grip in a standing position. Raise your upper arms so that they are parallel to the floor, allowing your lower arms to hang in the "scarecrow" position. This will be your starting position.','To initiate the movement, externally rotate the shoulders to move the upper arm 180 degrees. Keep the upper arms in place, rotating the upper arms until the wrists are directly above the elbows, the forearms perpendicular to the floor.','Now press the dumbbells by extending at the elbows, straightening your arms overhead.','Return to the starting position as you breathe in by reversing the steps.','Repeat for the recommended amount of repetitions.']::text[],array['Cuban_Press/0.jpg','Cuban_Press/1.jpg']::text[],false),
('Dancers_Stretch','Dancer''s Stretch','Dancer''s Stretch','Mobilité','Lombaires','Abducteurs, Fessiers',null,'Débutant',null,array['Sit up on the floor.','Cross your right leg over your left, keeping the knee bent. Your left leg is straight and down on the floor.','Place your left arm on your right leg and your right hand on the floor.','Rotate your upper body to the right, and hold for 10-20 seconds. Switch sides.']::text[],array['Dancers_Stretch/0.jpg','Dancers_Stretch/1.jpg']::text[],false),
('Dead_Bug','Dead bug','Dead Bug','Force','Abdominaux',null,'Poids du corps','Débutant','Sur le dos, bras et jambes en l''air. Descends bras et jambe opposés en gardant le bas du dos au sol.',array['Begin lying on your back with your hands extended above you toward the ceiling.','Bring your feet, knees, and hips up to 90 degrees.','Exhale hard to bring your ribcage down and flatten your back onto the floor, rotating your pelvis up and squeezing your glutes. Hold this position throughout the movement. This will be your starting position.','Initiate the exercise by extending one leg, straightening the knee and hip to bring the leg just above the ground.','Maintain the position of your lumbar and pelvis as you perform the movement, as your back is going to want to arch.','Stay tight and return the working leg to the starting position.','Repeat on the opposite side, alternating until the set is complete.']::text[],array['Dead_Bug/0.jpg','Dead_Bug/1.jpg']::text[],true),
('Deadlift_with_Bands','Deadlift with Bands','Deadlift with Bands','Force','Lombaires','Avant-bras, Fessiers, Ischio-jambiers, Haut du dos, Quadriceps, Trapèzes','Barre','Avancé',null,array['To deadlift with short bands, simply loop them over the bar before you start, and step into them to set up. For long bands, they will need to be anchored to a secure base, such as heavy dumbbells or a rack.','With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.','Lower the bar by bending at the hips and guiding it to the floor.']::text[],array['Deadlift_with_Bands/0.jpg','Deadlift_with_Bands/1.jpg']::text[],false),
('Deadlift_with_Chains','Deadlift with Chains','Deadlift with Chains','Force','Lombaires','Avant-bras, Fessiers, Ischio-jambiers, Haut du dos, Quadriceps, Trapèzes','Barre','Avancé',null,array['You can attach the chains to the sleeves of the bar, or just drape the middle over the bar so there is a greater weight increase as you lift.','Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets. With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar.','Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.','Lower the bar by bending at the hips and guiding it to the floor.']::text[],array['Deadlift_with_Chains/0.jpg','Deadlift_with_Chains/1.jpg']::text[],false),
('Decline_Barbell_Bench_Press','Développé décliné barre','Decline Barbell Bench Press','Force','Pectoraux','Épaules, Triceps','Barre','Débutant','Banc décliné, descends la barre vers le bas des pectoraux puis pousse.',array['Secure your legs at the end of the decline bench and slowly lay down on the bench.','Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.','As you breathe in, come down slowly until you feel the bar on your lower chest.','After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up).','Repeat the movement for the prescribed amount of repetitions.','When you are done, place the bar back in the rack.']::text[],array['Decline_Barbell_Bench_Press/0.jpg','Decline_Barbell_Bench_Press/1.jpg']::text[],true),
('Decline_Close-Grip_Bench_To_Skull_Crusher','Decline Close-Grip Bench To Skull Crusher','Decline Close-Grip Bench To Skull Crusher','Force','Triceps','Pectoraux, Épaules','Barre','Intermédiaire',null,array['Secure your legs at the end of the decline bench and slowly lay down on the bench.','Using a close grip (a grip that is slightly less than shoulder width), lift the bar from the rack and hold it straight over you with your arms locked and elbows in. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.','Now lower the bar down to your lower chest as you breathe in. Keep the elbows in as you perform this movement.','Using the triceps to push the bar back up, press it back to the starting position as you exhale.','As you breathe in and you keep the upper arms stationary, bring the bar down slowly by moving your forearms in a semicircular motion towards you until you feel the bar slightly touch your forehead. Breathe in as you perform this portion of the movement.','Lift the bar back to the starting position by contracting the triceps and exhaling.','Repeat steps 3-6 until the recommended amount of repetitions is performed.']::text[],array['Decline_Close-Grip_Bench_To_Skull_Crusher/0.jpg','Decline_Close-Grip_Bench_To_Skull_Crusher/1.jpg']::text[],false),
('Decline_Crunch','Decline Crunch','Decline Crunch','Force','Abdominaux',null,'Poids du corps','Intermédiaire',null,array['Secure your legs at the end of the decline bench and lie down.','Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don''t lock your fingers behind your head.','While pushing the small of your back down in the bench to better isolate your abdominal muscles, begin to roll your shoulders off it.','Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the bench only about four inches, and your lower back should remain on the bench. At the top of the movement, contract your abdominals hard and keep the contraction for a second. Tip: Focus on slow, controlled movement - don''t cheat yourself by using momentum.','After the one second contraction, begin to come down slowly again to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[],array['Decline_Crunch/0.jpg','Decline_Crunch/1.jpg']::text[],false),
('Decline_Dumbbell_Bench_Press','Développé décliné haltères','Decline Dumbbell Bench Press','Force','Pectoraux','Épaules, Triceps','Haltères','Débutant','Banc décliné, descends les haltères vers le bas des pectoraux puis pousse.',array['Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.','Once you are laying down, move the dumbbells in front of you at shoulder width.','Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.','Bring down the weights slowly to your side as you breathe out. Keep full control of the dumbbells at all times. Tip: Throughout the motion, the forearms should always be perpendicular to the floor.','As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up..','Repeat the movement for the prescribed amount of repetitions of your training program.']::text[],array['Decline_Dumbbell_Bench_Press/0.jpg','Decline_Dumbbell_Bench_Press/1.jpg']::text[],true),
('Decline_Dumbbell_Flyes','Decline Dumbbell Flyes','Decline Dumbbell Flyes','Force','Pectoraux',null,'Haltères','Débutant',null,array['Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.','Once you are laying down, move the dumbbells in front of you at shoulder width. The palms of the hands should be facing each other and the arms should be perpendicular to the floor and fully extended. This will be your starting position.','With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary; the movement should only occur at the shoulder joint.','Return your arms back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.','Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions.']::text[],array['Decline_Dumbbell_Flyes/0.jpg','Decline_Dumbbell_Flyes/1.jpg']::text[],false),
('Decline_Dumbbell_Triceps_Extension','Decline Dumbbell Triceps Extension','Decline Dumbbell Triceps Extension','Force','Triceps',null,'Haltères','Débutant',null,array['Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.','Once you are laying down, move the dumbbells in front of you at shoulder width. The palms of the hands should be facing each other and the arms should be perpendicular to the floor and fully extended. This will be your starting position.','As you breathe in and you keep the upper arms stationary (and elbows in), bring the dumbbells down slowly by moving your forearms in a semicircular motion towards you until your thumbs are next to your ears. Breathe in as you perform this portion of the movement.','Lift the dumbbells back to the starting position by contracting the triceps and exhaling.','Repeat for the recommended amount of repetitions.']::text[],array['Decline_Dumbbell_Triceps_Extension/0.jpg','Decline_Dumbbell_Triceps_Extension/1.jpg']::text[],false),
('Decline_EZ_Bar_Triceps_Extension','Decline EZ Bar Triceps Extension','Decline EZ Bar Triceps Extension','Force','Triceps',null,'Barre','Débutant',null,array['Secure your legs at the end of the decline bench and slowly lay down on the bench.','Using a close grip (a grip that is slightly less than shoulder width), lift the EZ bar from the rack and hold it straight over you with your arms locked and elbows in. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.','As you breathe in and you keep the upper arms stationary, bring the bar down slowly by moving your forearms in a semicircular motion towards you until you feel the bar slightly touch your forehead. Breathe in as you perform this portion of the movement.','Lift the bar back to the starting position by contracting the triceps and exhaling.','Repeat until the recommended amount of repetitions is performed.']::text[],array['Decline_EZ_Bar_Triceps_Extension/0.jpg','Decline_EZ_Bar_Triceps_Extension/1.jpg']::text[],false),
('Decline_Oblique_Crunch','Decline Oblique Crunch','Decline Oblique Crunch','Force','Abdominaux',null,'Poids du corps','Débutant',null,array['Secure your legs at the end of the decline bench and slowly lay down on the bench.','Raise your upper body off the bench until your torso is about 35-45 degrees if measured from the floor.','Put one hand beside your head and the other on your thigh. This will be your starting position.','Raise your upper body slowly from the starting position while turning your torso to the left. Continue crunching up as you exhale until your right elbow touches your left knee. Hold this contracted position for a second. Tip: Focus on keeping your abs tight and keeping the movement slow and controlled.','Lower your body back down slowly to the starting position as you inhale.','After completing one set on the right for the recommended amount of repetitions, switch to your left side. Tip: Focus on really twisting your torso and feeling the contraction when you are in the up position.']::text[],array['Decline_Oblique_Crunch/0.jpg','Decline_Oblique_Crunch/1.jpg']::text[],false),
('Decline_Push-Up','Decline Push-Up','Decline Push-Up','Force','Pectoraux','Épaules, Triceps',null,'Débutant',null,array['Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length. Move your feet up to a box or bench. This will be your starting position.','Next, lower yourself downward until your chest almost touches the floor as you inhale.','Now breathe out and press your upper body back up to the starting position while squeezing your chest.','After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed.']::text[],array['Decline_Push-Up/0.jpg','Decline_Push-Up/1.jpg']::text[],false),
('Decline_Reverse_Crunch','Decline Reverse Crunch','Decline Reverse Crunch','Force','Abdominaux',null,'Poids du corps','Débutant',null,array['Lie on your back on a decline bench and hold on to the top of the bench with both hands. Don''t let your body slip down from this position.','Hold your legs parallel to the floor using your abs to hold them there while keeping your knees and feet together. Tip: Your legs should be fully extended with a slight bend on the knee. This will be your starting position.','While exhaling, move your legs towards the torso as you roll your pelvis backwards and you raise your hips off the bench. At the end of this movement your knees will be touching your chest.','Hold the contraction for a second and move your legs back to the starting position while inhaling.','Repeat for the recommended amount of repetitions.']::text[],array['Decline_Reverse_Crunch/0.jpg','Decline_Reverse_Crunch/1.jpg']::text[],false),
('Decline_Smith_Press','Decline Smith Press','Decline Smith Press','Force','Pectoraux','Épaules, Triceps','Machine','Débutant',null,array['Place a decline bench underneath the Smith machine. Now place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Using a pronated grip that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms extended. This will be your starting position.','As you inhale, lower the bar under control by allowing the elbows to flex, lightly contacting the torso.','After a brief pause, bring the bar back to the starting position by extending the elbows, exhaling as you do so.','Repeat the movement for the prescribed amount of repetitions.','When the set is complete, lock the bar back in the rack.']::text[],array['Decline_Smith_Press/0.jpg','Decline_Smith_Press/1.jpg']::text[],false),
('Deficit_Deadlift','Soulevé de terre en déficit','Deficit Deadlift','Force','Lombaires','Avant-bras, Fessiers, Ischio-jambiers, Haut du dos, Quadriceps, Trapèzes','Barre','Intermédiaire','Debout sur une cale de 3-5 cm, même technique que le soulevé classique avec plus d''amplitude.',array['Begin by having a platform or weight plates that you can stand on, usually 1-3 inches in height. Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets.','With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.','Lower the bar by bending at the hips and guiding it to the floor.']::text[],array['Deficit_Deadlift/0.jpg','Deficit_Deadlift/1.jpg']::text[],true),
('Depth_Jump_Leap','Depth jump','Depth Jump Leap','Explosivité','Quadriceps','Abducteurs, Adducteurs, Mollets, Fessiers, Ischio-jambiers','Autre','Débutant','Laisse-toi tomber d''une box et rebondis immédiatement le plus haut possible.',array['For this drill you will need two boxes or benches, one 12 to 16 inches high and the other 22 to 26 inches high.','Stand on one of the two boxes with arms at the sides; feet should be together and slightly off the edge as in the depth jump. Place the other box approximately two or three feet in front of and facing the performer.','Begin by dropping off the initial box, landing and simultaneously taking off with both feet.','Rebound by driving upward and outward as intensely as possible, using the arms and full extension of the body to jump onto the higher box. Again, allow the legs to absorb the impact.']::text[],array['Depth_Jump_Leap/0.jpg','Depth_Jump_Leap/1.jpg']::text[],true),
('Dip_Machine','Dip Machine','Dip Machine','Force','Triceps','Pectoraux, Épaules','Machine','Débutant',null,array['Sit securely in a dip machine, select the weight and firmly grasp the handles.','Now keep your elbows in at your sides in order to place emphasis on the triceps. The elbows should be bent at a 90 degree angle.','As you contract the triceps, extend your arms downwards as you exhale. Tip: At the bottom of the movement, focus on keeping a little bend in your arms to keep tension on the triceps muscle.','Now slowly let your arms come back up to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[],array['Dip_Machine/0.jpg','Dip_Machine/1.jpg']::text[],false),
('Dips_-_Chest_Version','Dips (pectoraux)','Dips - Chest Version','Force','Pectoraux','Épaules, Triceps','Autre','Intermédiaire','Buste penché en avant, descends jusqu''à l''étirement des pectoraux puis remonte.',array['For this exercise you will need access to parallel bars. To get yourself into the starting position, hold your body at arms length (arms locked) above the bars.','While breathing in, lower yourself slowly with your torso leaning forward around 30 degrees or so and your elbows flared out slightly until you feel a slight stretch in the chest.','Once you feel the stretch, use your chest to bring your body back to the starting position as you breathe out. Tip: Remember to squeeze the chest at the top of the movement for a second.','Repeat the movement for the prescribed amount of repetitions.']::text[],array['Dips_-_Chest_Version/0.jpg','Dips_-_Chest_Version/1.jpg']::text[],true),
('Dips_-_Triceps_Version','Dips (triceps)','Dips - Triceps Version','Force','Triceps','Pectoraux, Épaules','Poids du corps','Débutant','Buste droit, coudes près du corps. Descends à 90° puis pousse jusqu''à bras tendus.',array['To get into the starting position, hold your body at arm''s length with your arms nearly locked above the bars.','Now, inhale and slowly lower yourself downward. Your torso should remain upright and your elbows should stay close to your body. This helps to better focus on tricep involvement. Lower yourself until there is a 90 degree angle formed between the upper arm and forearm.','Then, exhale and push your torso back up using your triceps to bring your body back to the starting position.','Repeat the movement for the prescribed amount of repetitions.']::text[],array['Dips_-_Triceps_Version/0.jpg','Dips_-_Triceps_Version/1.jpg']::text[],true),
('Donkey_Calf_Raises','Donkey Calf Raises','Donkey Calf Raises','Force','Mollets',null,'Autre','Intermédiaire',null,array['For this exercise you will need access to a donkey calf raise machine. Start by positioning your lower back and hips under the padded lever provided. The tailbone area should be the one making contact with the pad.','Place both of your arms on the side handles and place the balls of your feet on the calf block with the heels extending off. Align the toes forward, inward or outward, depending on the area you wish to target, and straighten the knees without locking them. This will be your starting position.','Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.','Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.','Repeat for the recommended amount of repetitions.']::text[],array['Donkey_Calf_Raises/0.jpg','Donkey_Calf_Raises/1.jpg']::text[],false),
('Double_Kettlebell_Alternating_Hang_Clean','Double Kettlebell Alternating Hang Clean','Double Kettlebell Alternating Hang Clean','Force','Ischio-jambiers','Biceps, Mollets, Avant-bras, Fessiers, Lombaires, Quadriceps, Trapèzes','Kettlebell','Intermédiaire',null,array['Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead.','Clean one kettlebell to your shoulder and hold on to the other kettlebell.','With a fluid motion, lower the top kettlebell while driving the bottom kettlebell up.']::text[],array['Double_Kettlebell_Alternating_Hang_Clean/0.jpg','Double_Kettlebell_Alternating_Hang_Clean/1.jpg']::text[],false),
('Double_Kettlebell_Jerk','Double Kettlebell Jerk','Double Kettlebell Jerk','Force','Épaules','Mollets, Quadriceps, Triceps','Kettlebell','Intermédiaire',null,array['Hold a kettlebell by the handle in each hand.','Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward. This will be your starting position.','Dip your body by bending the knees, keeping your torso upright.','Immediately reverse direction, driving through the heels, in essence jumping to create momentum.','As you do so, press the kettlebells overhead to lockout by extending the arms, using your body''s momentum to move the weights.','Return your feet to the ground in a split fashion, with one foot forward and one foot back.','Keeping the weights overhead, return to a standing position, bringing your feet together. Lower the weights to perform the next repetition.']::text[],array['Double_Kettlebell_Jerk/0.jpg','Double_Kettlebell_Jerk/1.jpg']::text[],false),
('Double_Kettlebell_Push_Press','Double Kettlebell Push Press','Double Kettlebell Push Press','Force','Épaules','Mollets, Quadriceps, Triceps','Kettlebell','Intermédiaire',null,array['Clean two kettlebells to your shoulders.','Squat down a few inches and reverse the motion rapidly. Use the momentum from the legs to drive the kettlebells overhead.','Once the kettlebells are locked out, lower the kettlebells to your shoulders and repeat.']::text[],array['Double_Kettlebell_Push_Press/0.jpg','Double_Kettlebell_Push_Press/1.jpg']::text[],false),
('Double_Kettlebell_Snatch','Double Kettlebell Snatch','Double Kettlebell Snatch','Force','Épaules','Fessiers, Ischio-jambiers, Quadriceps','Kettlebell','Avancé',null,array['Place two kettlebells behind your feet. Bend your knees and sit back to pick up the kettlebells.','Swing the kettlebells between your legs forcefully and reverse the direction.','Drive through with your hips and lock the ketttlebells overhead in one uninterrupted motion.']::text[],array['Double_Kettlebell_Snatch/0.jpg','Double_Kettlebell_Snatch/1.jpg']::text[],false),
('Double_Kettlebell_Windmill','Double Kettlebell Windmill','Double Kettlebell Windmill','Force','Abdominaux','Fessiers, Ischio-jambiers, Épaules, Triceps','Kettlebell','Intermédiaire',null,array['Place a kettlebell in front of your front foot and clean and press a kettlebell overhead with your opposite arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so, so that the palm faces forward.','Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Turn your feet out at a forty-five degree angle from the arm with the locked out kettlebell.','Bending at the hip to one side, sticking your butt out, slowly lean until you can retrieve the kettlebell from the floor. Keep your eyes on the kettlebell that you hold over your head at all times.','Pause for a second after retrieving the kettlebell from the ground and reverse the motion back to the starting position.']::text[],array['Double_Kettlebell_Windmill/0.jpg','Double_Kettlebell_Windmill/1.jpg']::text[],false),
('Double_Leg_Butt_Kick','Double Leg Butt Kick','Double Leg Butt Kick','Explosivité','Quadriceps','Abducteurs, Adducteurs, Mollets, Fessiers, Ischio-jambiers','Poids du corps','Débutant',null,array['Begin standing with your knees slightly bent.','Quickly squat a short distance, flexing the hips and knees, and immediately extend to jump for maximum vertical height.','As you go up, tuck your heels by flexing the knees, attempting to touch the buttocks.','Finish the motion by landing with the knees only partially bent, using your legs to absorb the impact.']::text[],array['Double_Leg_Butt_Kick/0.jpg','Double_Leg_Butt_Kick/1.jpg']::text[],false),
('Downward_Facing_Balance','Downward Facing Balance','Downward Facing Balance','Force','Fessiers','Abdominaux, Ischio-jambiers','Swiss ball','Intermédiaire',null,array['Lie facedown on top of an exercise ball.','While resting on your stomach on the ball, walk your hands forward along the floor and lift your legs, extending your elbows and knees.']::text[],array['Downward_Facing_Balance/0.jpg','Downward_Facing_Balance/1.jpg']::text[],false),
('Drag_Curl','Drag Curl','Drag Curl','Force','Biceps','Avant-bras','Barre','Intermédiaire',null,array['Grab a barbell with a supinated grip (palms facing forward) and get your elbows close to your torso and back. This will be your starting position.','As you exhale, curl the bar up while keeping the elbows to the back as you "Drag" the bar up by keeping it in contact with your torso. Tip: As you can see, you will not be keeping the elbows pinned to your sides, but instead you will be bringing them back. Also, do not lift your shoulders.','Slowly go back to the starting position as you keep the bar in contact with the torso at all times.','Repeat for the recommended amount of repetitions.']::text[],array['Drag_Curl/0.jpg','Drag_Curl/1.jpg']::text[],false),
('Drop_Push','Drop Push','Drop Push','Explosivité','Pectoraux','Épaules, Triceps','Autre','Intermédiaire',null,array['Position low boxes or other platforms 2-3 feet apart.','Move to a pushup position between them, supporting yourself by placing your hands on the boxes.','With good posture, drop from the platforms by pressing up and moving your hands to shoulder width, cushioning your landing by absorbing the impact through the arm.']::text[],array['Drop_Push/0.jpg','Drop_Push/1.jpg']::text[],false),
('Dumbbell_Alternate_Bicep_Curl','Curl haltères alterné','Dumbbell Alternate Bicep Curl','Force','Biceps','Avant-bras','Haltères','Débutant','Monte un haltère après l''autre en tournant le poignet vers le haut.',array['Stand (torso upright) with a dumbbell in each hand held at arms length. The elbows should be close to the torso and the palms of your hand should be facing your thighs.','While holding the upper arm stationary, curl the right weight as you rotate the palm of the hands until they are facing forward. At this point continue contracting the biceps as you breathe out until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.','Slowly begin to bring the dumbbell back to the starting position as your breathe in. Tip: Remember to twist the palms back to the starting position (facing your thighs) as you come down.','Repeat the movement with the left hand. This equals one repetition.','Continue alternating in this manner for the recommended amount of repetitions.']::text[],array['Dumbbell_Alternate_Bicep_Curl/0.jpg','Dumbbell_Alternate_Bicep_Curl/1.jpg']::text[],true),
('Dumbbell_Bench_Press','Développé couché haltères','Dumbbell Bench Press','Force','Pectoraux','Épaules, Triceps','Haltères','Débutant','Haltères au-dessus de la poitrine, descends en ouvrant les coudes à 45° puis pousse en rapprochant les haltères.',array['Lie down on a flat bench with a dumbbell in each hand resting on top of your thighs. The palms of your hands will be facing each other.','Then, using your thighs to help raise the dumbbells up, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.','Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. The dumbbells should be just to the sides of your chest, with your upper arm and forearm creating a 90 degree angle. Be sure to maintain full control of the dumbbells at all times. This will be your starting position.','Then, as you breathe out, use your chest to push the dumbbells up. Lock your arms at the top of the lift and squeeze your chest, hold for a second and then begin coming down slowly. Tip: Ideally, lowering the weight should take about twice as long as raising it.','Repeat the movement for the prescribed amount of repetitions of your training program.']::text[],array['Dumbbell_Bench_Press/0.jpg','Dumbbell_Bench_Press/1.jpg']::text[],true),
('Dumbbell_Bench_Press_with_Neutral_Grip','Dumbbell Bench Press with Neutral Grip','Dumbbell Bench Press with Neutral Grip','Force','Pectoraux','Épaules, Triceps','Haltères','Débutant',null,array['Take a dumbbell in each hand and lay back onto a flat bench. Your feet should be flat on the floor and your shoulder blades retracted.','Maintaining a neutral grip, palms facing each other, begin with your arms extended directly above you, perpendicular to the floor. This will be your starting position.','Begin the movement by flexing the elbow, lowering the upper arms to the side. Descend until the dumbbells are to your torso.','Pause, then extend the elbow and return to the starting position.']::text[],array['Dumbbell_Bench_Press_with_Neutral_Grip/0.jpg','Dumbbell_Bench_Press_with_Neutral_Grip/1.jpg']::text[],false),
('Dumbbell_Bicep_Curl','Curl haltères','Dumbbell Bicep Curl','Force','Biceps','Avant-bras','Haltères','Débutant','Haltères le long du corps paumes vers l''avant, monte vers les épaules puis redescends.',array['Stand up straight with a dumbbell in each hand at arm''s length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.','Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps.','Then, inhale and slowly begin to lower the dumbbells back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],array['Dumbbell_Bicep_Curl/0.jpg','Dumbbell_Bicep_Curl/1.jpg']::text[],true),
('Dumbbell_Clean','Dumbbell Clean','Dumbbell Clean','Force','Ischio-jambiers','Mollets, Avant-bras, Fessiers, Lombaires, Quadriceps, Épaules, Trapèzes','Haltères','Intermédiaire',null,array['Begin standing with a dumbbell in each hand with your feet shoulder width apart.','Lower the weights to the floor by flexing at the hips and knees, pushing your hips back until the dumbbells reach the floor. This will be your starting position.','To initiate the movement, violently jump upward by extending the hips, knees, and ankles to acclerate the weights upward. Maintaining a neutral grip on the dumbbells, keep the arms straight until full extension is reached.','After full extension, rebend the hips and knees to receive the weight in a squat position. Allow the arms to bend, guiding the dumbbells to your shoulders.','Upon receiving the weight in the squat position, extend the hips and knees to finish in a standing position with the weights on your shoulders.']::text[],array['Dumbbell_Clean/0.jpg','Dumbbell_Clean/1.jpg']::text[],false),
('Dumbbell_Floor_Press','Dumbbell Floor Press','Dumbbell Floor Press','Force','Triceps','Pectoraux, Épaules','Haltères','Intermédiaire',null,array['Lay on the floor holding dumbbells in your hands. Your knees can be bent. Begin with the weights fully extended above you.','Lower the weights until your upper arm comes in contact with the floor. You can tuck your elbows to emphasize triceps size and strength, or to focus on your chest angle your arms to the side.','Pause at the bottom, and then bring the weight together at the top by extending through the elbows.']::text[],array['Dumbbell_Floor_Press/0.jpg','Dumbbell_Floor_Press/1.jpg']::text[],false),
('Dumbbell_Flyes','Écarté couché haltères','Dumbbell Flyes','Force','Pectoraux',null,'Haltères','Débutant','Bras légèrement fléchis, ouvre les bras en arc jusqu''à l''étirement des pectoraux puis referme.',array['Lie down on a flat bench with a dumbbell on each hand resting on top of your thighs. The palms of your hand will be facing each other.','Then using your thighs to help raise the dumbbells, lift the dumbbells one at a time so you can hold them in front of you at shoulder width with the palms of your hands facing each other. Raise the dumbbells up like you''re pressing them, but stop and hold just before you lock out. This will be your starting position.','With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary; the movement should only occur at the shoulder joint.','Return your arms back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.','Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions.']::text[],array['Dumbbell_Flyes/0.jpg','Dumbbell_Flyes/1.jpg']::text[],true),
('Dumbbell_Incline_Row','Dumbbell Incline Row','Dumbbell Incline Row','Force','Haut du dos','Biceps, Avant-bras, Dorsaux, Épaules','Haltères','Débutant',null,array['Using a neutral grip, lean into an incline bench.','Take a dumbbell in each hand with a neutral grip, beginning with the arms straight. This will be your starting position.','Retract the shoulder blades and flex the elbows to row the dumbbells to your side.','Pause at the top of the motion, and then return to the starting position.']::text[],array['Dumbbell_Incline_Row/0.jpg','Dumbbell_Incline_Row/1.jpg']::text[],false),
('Dumbbell_Incline_Shoulder_Raise','Dumbbell Incline Shoulder Raise','Dumbbell Incline Shoulder Raise','Force','Épaules','Triceps','Haltères','Débutant',null,array['Sit on an Incline Bench while holding a dumbbell on each hand on top of your thighs.','Lift your legs up to kick the weights to your shoulders and lean back. Position the dumbbells above your shoulders with your arms extended. The arms should be perpendicular to the floor with your palms facing forward and knuckles pointing towards the ceiling. This will be your starting position.','While keeping the arms straight and locked, lift the dumbbells by raising the shoulders from the bench as you breathe out.','Bring back the dumbbells to the starting position as you breathe in.','Repeat for the recommended amount of repetitions.']::text[],array['Dumbbell_Incline_Shoulder_Raise/0.jpg','Dumbbell_Incline_Shoulder_Raise/1.jpg']::text[],false),
('Dumbbell_Lunges','Fentes haltères','Dumbbell Lunges','Force','Quadriceps','Mollets, Fessiers, Ischio-jambiers','Haltères','Débutant','Un haltère dans chaque main, avance d''un grand pas et descends le genou arrière près du sol, puis reviens.',array['Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.','Step forward with your right leg around 2 feet or so from the foot being left stationary behind and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground.','Using mainly the heel of your foot, push up and go back to the starting position as you exhale.','Repeat the movement for the recommended amount of repetitions and then perform with the left leg.']::text[],array['Dumbbell_Lunges/0.jpg','Dumbbell_Lunges/1.jpg']::text[],true),
('Dumbbell_Lying_One-Arm_Rear_Lateral_Raise','Dumbbell Lying One-Arm Rear Lateral Raise','Dumbbell Lying One-Arm Rear Lateral Raise','Force','Épaules','Haut du dos','Haltères','Intermédiaire',null,array['While holding a dumbbell in one hand, lay with your chest down on a slightly inclined (around 15 degrees when measured from the floor) adjustable bench. The other hand can be used to hold to the leg of the bench for stability.','Position the palm of the hand that is holding the dumbbell in a neutral manner (palms facing your torso) as you keep the arm extended with the elbow slightly bent. This will be your starting position.','Now raise the arm with the dumbbell to the side until your elbow is at shoulder height and your arm is roughly parallel to the floor as you exhale. Tip: Maintain your arm perpendicular to the torso while keeping your arm extended throughout the movement. Also, keep the contraction at the top for a second.','Slowly lower the dumbbell to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[],array['Dumbbell_Lying_One-Arm_Rear_Lateral_Raise/0.jpg','Dumbbell_Lying_One-Arm_Rear_Lateral_Raise/1.jpg']::text[],false),
('Dumbbell_Lying_Pronation','Dumbbell Lying Pronation','Dumbbell Lying Pronation','Force','Avant-bras',null,'Haltères','Intermédiaire',null,array['Lie on a flat bench face down with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.','Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm.','Now raise the upper arm so that the forearm is perpendicular to the floor and the upper arm is perpendicular to your torso. Tip: The upper arm should be parallel to the floor and also creating a 90-degree angle with your torso. This will be your starting position.','As you breathe out, externally rotate your forearm so that the dumbbell is lifted forward as you maintain the 90 degree angle bend between the upper arms and the forearm. You will continue this external rotation until the forearm is parallel to the floor. At this point you will hold the contraction for a second.','As you breathe in, slowly go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],array['Dumbbell_Lying_Pronation/0.jpg','Dumbbell_Lying_Pronation/1.jpg']::text[],false),
('Dumbbell_Lying_Rear_Lateral_Raise','Dumbbell Lying Rear Lateral Raise','Dumbbell Lying Rear Lateral Raise','Force','Épaules',null,'Haltères','Intermédiaire',null,array['While holding a dumbbell in each hand, lay with your chest down on a slightly inclined (around 15 degrees when measured from the floor) adjustable bench.','Position the palms of the hands in a neutral manner (palms facing your torso) as you keep the arms extended with the elbows slightly bent. This will be your starting position.','Now raise the arms to the side until your elbows are at shoulder height and your arms are roughly parallel to the floor as you exhale. Tip: Maintain your arms perpendicular to the torso while keeping them extended throughout the movement. Also, keep the contraction at the top for a second.','Slowly lower the dumbbells to the starting position as you inhale.','Repeat for the recommended amount of repetitions and then switch to the other arm.']::text[],array['Dumbbell_Lying_Rear_Lateral_Raise/0.jpg','Dumbbell_Lying_Rear_Lateral_Raise/1.jpg']::text[],false),
('Dumbbell_Lying_Supination','Dumbbell Lying Supination','Dumbbell Lying Supination','Force','Avant-bras',null,'Haltères','Intermédiaire',null,array['Lie sideways on a flat bench with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.','Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm.','Now raise the upper arm so that the forearm is parallel to the floor and perpendicular to your torso (Tip: So the forearm will be directly in front of you). The upper arm will be stationary by your torso and should be parallel to the floor (aligned with your torso at all times). This will be your starting position.','As you breathe out, externally rotate your forearm so that the dumbbell is lifted up in a semicircle motion as you maintain the 90 degree angle bend between the upper arms and the forearm. You will continue this external rotation until the forearm is perpendicular to the floor and the torso pointing towards the ceiling. At this point you will hold the contraction for a second.','As you breathe in, slowly go back to the starting position.','Repeat for the recommended amount of repetitions and then switch to the other arm.']::text[],array['Dumbbell_Lying_Supination/0.jpg','Dumbbell_Lying_Supination/1.jpg']::text[],false),
('Dumbbell_One-Arm_Shoulder_Press','Dumbbell One-Arm Shoulder Press','Dumbbell One-Arm Shoulder Press','Force','Épaules','Triceps','Haltères','Intermédiaire',null,array['Grab a dumbbell and either sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs or stand up straight.','Clean the dumbbell up to bring it to shoulder height. The other hand can be kept fully extended to the side, by the waist or grabbing a fixed surface.','Rotate the wrist so that the palm of your hand is facing forward. This is your starting position.','As you exhale, push the dumbbell up until your arm is fully extended.','After a second pause, slowly come down back to the starting position as you inhale.','Repeat for the recommended amount of repetitions and then switch arms.']::text[],array['Dumbbell_One-Arm_Shoulder_Press/0.jpg','Dumbbell_One-Arm_Shoulder_Press/1.jpg']::text[],false),
('Dumbbell_One-Arm_Triceps_Extension','Dumbbell One-Arm Triceps Extension','Dumbbell One-Arm Triceps Extension','Force','Triceps',null,'Haltères','Intermédiaire',null,array['Grab a dumbbell and either sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs or stand up straight.','Clean the dumbbell up to bring it to shoulder height and then extend the arm over your head so that the whole arm is perpendicular to the floor and next to your head. The dumbbell should be on top of you. The other hand can be kept fully extended to the side, by the waist, supporting the upper arm that has the dumbbell or grabbing a fixed surface.','Rotate the wrist so that the palm of your hand is facing forward and the pinkie is facing the ceiling. This will be your starting position.','Slowly lower the dumbbell behind your head as you hold the upper arm stationary. Inhale as you perform this movement and pause when your triceps are fully stretched.','Return to the starting position by flexing your triceps as you breathe out. Tip: It is imperative that only the forearm moves. The upper arm should remain at all times stationary next to your head.','Repeat for the recommended amount of repetitions and switch arms.']::text[],array['Dumbbell_One-Arm_Triceps_Extension/0.jpg','Dumbbell_One-Arm_Triceps_Extension/1.jpg']::text[],false),
('Dumbbell_One-Arm_Upright_Row','Dumbbell One-Arm Upright Row','Dumbbell One-Arm Upright Row','Force','Épaules','Biceps, Trapèzes','Haltères','Intermédiaire',null,array['Grab a dumbbell and stand up straight with your arm extended in front of you with a slight bend at the elbows and your back straight. This will be your starting position. Tip: The dumbbell should be resting on top of your thigh with the palm of your hands facing your thighs.','Keep the other hand can be kept fully extended to the side, by the waist or grabbing a fixed surface. This will be your starting position.','Use your side shoulders to lift the dumbbell as you exhale. The dumbbell should be close to the body as you move it up. Continue to lift it until the dumbbell is nearly in line with your chin. Tip: Your elbows should drive the motion. As you lift the dumbbell, your elbow should always be higher than your forearm. Also, keep your torso stationary and pause for a second at the top of the movement.','Lower the dumbbell back down slowly to the starting position. Inhale as you perform this portion of the movement.','Repeat for the recommended amount of repetitions and switch arms.']::text[],array['Dumbbell_One-Arm_Upright_Row/0.jpg','Dumbbell_One-Arm_Upright_Row/1.jpg']::text[],false),
('Dumbbell_Prone_Incline_Curl','Dumbbell Prone Incline Curl','Dumbbell Prone Incline Curl','Force','Biceps',null,'Haltères','Intermédiaire',null,array['Grab a dumbbell on each hand and lie face down on an incline bench with your shoulders near top of the incline. Your knees can rest on the seat or your legs can be straddled to the sides (my preferred way).','Let your arms extend and hang naturally in front of you so that they are perpendicular to the floor.','Now keep your elbows in by your side and face the palms forward. This will be your starting position.','Raise the dumbbells by contracting the biceps until your arms are fully flexed. Exhale as you perform this portion of the movement and ensure that only the forearms move. The upper arms should remain stationary at all times.','Lower the dumbbells until your arms are fully extended.','Repeat for the recommended amount of times.']::text[],array['Dumbbell_Prone_Incline_Curl/0.jpg','Dumbbell_Prone_Incline_Curl/1.jpg']::text[],false),
('Dumbbell_Raise','Dumbbell Raise','Dumbbell Raise','Force','Épaules','Biceps','Haltères','Débutant',null,array['Grab a dumbbell in each arm and stand up straight with your arms extended by your sides with a slight bend at the elbows and your back straight. This will be your starting position. Tip: The dumbbell should be next to your thighs with the palm of your hands facing back.','Use your side shoulders to lift the dumbbells as you exhale. The dumbbells should be to the side of the body as you move them up. Continue to lift it until the dumbbells are nearly in line with your chin. Tip: Your elbows should drive the motion. As you lift the dumbbell, your elbow should always be higher than your forearm. Also, keep your torso stationary and pause for a second at the top of the movement.','Lower the dumbbells back down slowly to the starting position. Inhale as you perform this portion of the movement.','Repeat for the recommended amount of repetitions.']::text[],array['Dumbbell_Raise/0.jpg','Dumbbell_Raise/1.jpg']::text[],false),
('Dumbbell_Rear_Lunge','Fente arrière haltères','Dumbbell Rear Lunge','Force','Quadriceps','Mollets, Fessiers, Ischio-jambiers','Haltères','Intermédiaire','Recule d''un grand pas, descends le genou arrière près du sol puis reviens en poussant sur la jambe avant.',array['Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.','Step backward with your right leg around two feet or so from the left foot and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Tip: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground. Keep the torso upright during the lunge; flexible hip flexors are important. A long lunge emphasizes the Gluteus Maximus; a short lunge emphasizes Quadriceps.','Push up and go back to the starting position as you exhale. Tip: Use the ball of your feet to push in order to accentuate the quadriceps. To focus on the glutes, press with your heels.','Now repeat with the opposite leg.']::text[],array['Dumbbell_Rear_Lunge/0.jpg','Dumbbell_Rear_Lunge/1.jpg']::text[],true),
('Dumbbell_Scaption','Dumbbell Scaption','Dumbbell Scaption','Force','Épaules','Trapèzes','Haltères','Débutant',null,array['This corrective exercise strengthens the muscles that stabilize your shoulder blade. Hold a light weight in each hand, hanging at your sides. Your thumbs should pointing up.','Begin the movement raising your arms out in front of you, about 30 degrees off center. Your arms should be fully extended as you perform the movement.','Continue until your arms are parallel to the ground, and then return to the starting position.']::text[],array['Dumbbell_Scaption/0.jpg','Dumbbell_Scaption/1.jpg']::text[],false),
('Dumbbell_Seated_Box_Jump','Dumbbell Seated Box Jump','Dumbbell Seated Box Jump','Explosivité','Quadriceps','Mollets, Fessiers, Ischio-jambiers','Haltères','Intermédiaire',null,array['Position a box a couple feet to the side of a bench. Hold a dumbbell to your chest with both hands and seat yourself on the bench facing the box. This will be your starting position.','Plant your feet firmly on the ground as you lean forward, extending through the hips and knees to jump up and forward.','Land on the box with both feet, absorbing the impact by allowing the hips and knees to bend.','Step down and return to the starting position.']::text[],array['Dumbbell_Seated_Box_Jump/0.jpg','Dumbbell_Seated_Box_Jump/1.jpg']::text[],false),
('Dumbbell_Seated_One-Leg_Calf_Raise','Dumbbell Seated One-Leg Calf Raise','Dumbbell Seated One-Leg Calf Raise','Force','Mollets',null,'Haltères','Débutant',null,array['Place a block on the floor about 12 inches from a flat bench.','Sit on a flat bench and place a dumbbell on your upper left thigh about 3 inches above your knee.','Now place the ball of your left foot on the block. This will be your starting position.','Raise your toes up as high as possible as you exhale and you contract your calf muscle. Hold the contraction for a second.','Slowly return to the starting position, stretching as far down as possible.','Repeat for your prescribed number of repetitions and then repeat with the right leg.']::text[],array['Dumbbell_Seated_One-Leg_Calf_Raise/0.jpg','Dumbbell_Seated_One-Leg_Calf_Raise/1.jpg']::text[],false),
('Dumbbell_Shoulder_Press','Développé épaules haltères','Dumbbell Shoulder Press','Force','Épaules','Triceps','Haltères','Intermédiaire','Haltères à hauteur d''oreilles, pousse au-dessus de la tête puis redescends en contrôle.',array['While holding a dumbbell in each hand, sit on a military press bench or utility bench that has back support. Place the dumbbells upright on top of your thighs.','Now raise the dumbbells to shoulder height one at a time using your thighs to help propel them up into position.','Make sure to rotate your wrists so that the palms of your hands are facing forward. This is your starting position.','Now, exhale and push the dumbbells upward until they touch at the top.','Then, after a brief pause at the top contracted position, slowly lower the weights back down to the starting position while inhaling.','Repeat for the recommended amount of repetitions.']::text[],array['Dumbbell_Shoulder_Press/0.jpg','Dumbbell_Shoulder_Press/1.jpg']::text[],true),
('Dumbbell_Shrug','Shrug haltères','Dumbbell Shrug','Force','Trapèzes',null,'Haltères','Débutant','Haltères le long du corps, hausse les épaules au maximum puis redescends.',array['Stand erect with a dumbbell on each hand (palms facing your torso), arms extended on the sides.','Lift the dumbbells by elevating the shoulders as high as possible while you exhale. Hold the contraction at the top for a second. Tip: The arms should remain extended at all times. Refrain from using the biceps to help lift the dumbbells. Only the shoulders should be moving up and down.','Lower the dumbbells back to the original position.','Repeat for the recommended amount of repetitions.']::text[],array['Dumbbell_Shrug/0.jpg','Dumbbell_Shrug/1.jpg']::text[],true),
('Dumbbell_Side_Bend','Dumbbell Side Bend','Dumbbell Side Bend','Force','Abdominaux',null,'Haltères','Débutant',null,array['Stand up straight while holding a dumbbell on the left hand (palms facing the torso) as you have the right hand holding your waist. Your feet should be placed at shoulder width. This will be your starting position.','While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting position as you exhale. Tip: Keep the rest of the body stationary.','Now repeat the movement but bending to the left instead. Hold for a second and come back to the starting position.','Repeat for the recommended amount of repetitions and then change hands.']::text[],array['Dumbbell_Side_Bend/0.jpg','Dumbbell_Side_Bend/1.jpg']::text[],false),
('Dumbbell_Squat','Squat haltères','Dumbbell Squat','Force','Quadriceps','Mollets, Fessiers, Ischio-jambiers, Lombaires','Haltères','Débutant','Un haltère dans chaque main le long du corps. Descends dos neutre et remonte en poussant dans les talons.',array['Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).','Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section.','Begin to slowly lower your torso by bending the knees as you maintain a straight posture with the head up. Continue down until your thighs are parallel to the floor. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.','Begin to raise your torso as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],array['Dumbbell_Squat/0.jpg','Dumbbell_Squat/1.jpg']::text[],true),
('Dumbbell_Squat_To_A_Bench','Dumbbell Squat To A Bench','Dumbbell Squat To A Bench','Force','Quadriceps','Mollets, Fessiers, Ischio-jambiers, Lombaires','Haltères','Intermédiaire',null,array['Stand up straight with a flat bench behind you while holding a dumbbell on each hand (palms facing the side of your legs).','Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section.','Begin to slowly lower your torso by bending the knees as you maintain a straight posture with the head up. Continue down until you slightly touch the bench behind you. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.','Begin to raise the bar as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],array['Dumbbell_Squat_To_A_Bench/0.jpg','Dumbbell_Squat_To_A_Bench/1.jpg']::text[],false),
('Dumbbell_Step_Ups','Step-up haltères','Dumbbell Step Ups','Force','Quadriceps','Mollets, Fessiers, Ischio-jambiers','Haltères','Intermédiaire','Haltères en mains, monte sur une box en poussant dans la jambe d''appui, redescends lentement.',array['Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).','Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute the force required to come up.','Step down with the left leg by flexing the hip and knee of the right leg as you inhale. Return to the original standing position by placing the right foot of to next to the left foot on the initial position.','Repeat with the right leg for the recommended amount of repetitions and then perform with the left leg.']::text[],array['Dumbbell_Step_Ups/0.jpg','Dumbbell_Step_Ups/1.jpg']::text[],true),
('Dumbbell_Tricep_Extension_-Pronated_Grip','Dumbbell Tricep Extension -Pronated Grip','Dumbbell Tricep Extension -Pronated Grip','Force','Triceps',null,'Haltères','Débutant',null,array['Lie down on a flat bench holding two dumbbells directly above your shoulders. Your arms should be fully extended and form a 90 degree angle from your torso and the floor.','The palms of your hands should be facing forward, and your elbows should be tucked in. This will be your starting position.','Now, inhale and slowly lower the dumbbells until they are near your ears. Be sure to keep your upper arms stationary and your elbows tucked in.','Then, exhale and use your triceps to return the weight to the starting position.']::text[],array['Dumbbell_Tricep_Extension_-Pronated_Grip/0.jpg','Dumbbell_Tricep_Extension_-Pronated_Grip/1.jpg']::text[],false),
('Dynamic_Back_Stretch','Dynamic Back Stretch','Dynamic Back Stretch','Mobilité','Dorsaux',null,null,'Débutant',null,array['Stand with your feet shoulder width apart. This will be your starting position.','Keeping your arms straight, swing them straight up in front of you 5-10 times, increasing the range of motion each time until your arms are above your head.']::text[],array['Dynamic_Back_Stretch/0.jpg','Dynamic_Back_Stretch/1.jpg']::text[],false),
('Dynamic_Chest_Stretch','Dynamic Chest Stretch','Dynamic Chest Stretch','Mobilité','Pectoraux','Haut du dos',null,'Débutant',null,array['Stand with your hands together, arms extended directly in front of you. This will be your starting position.','Keeping your arms straight, quickly move your arms back as far as possible and back in again, similar to an exaggerated clapping motion. Repeat 5-10 times, increasing speed as you do so.']::text[],array['Dynamic_Chest_Stretch/0.jpg','Dynamic_Chest_Stretch/1.jpg']::text[],false),
('EZ-Bar_Curl','Curl barre EZ','EZ-Bar Curl','Force','Biceps',null,'Barre EZ','Débutant','Prise sur les poignées inclinées, monte la barre en gardant les coudes fixes.',array['Stand up straight while holding an EZ curl bar at the wide outer handle. The palms of your hands should be facing forward and slightly tilted inward due to the shape of the bar. Keep your elbows close to your torso. This will be your starting position.','Now, while keeping your upper arms stationary, exhale and curl the weights forward while contracting the biceps. Focus on only moving your forearms.','Continue to raise the weight until your biceps are fully contracted and the bar is at shoulder level. Hold the top contracted position for a moment and squeeze the biceps.','Then inhale and slowly lower the bar back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],array['EZ-Bar_Curl/0.jpg','EZ-Bar_Curl/1.jpg']::text[],true),
('EZ-Bar_Skullcrusher','Barre au front (skull crusher)','EZ-Bar Skullcrusher','Force','Triceps','Avant-bras','Barre EZ','Débutant','Allongé, descends la barre EZ vers le front en fléchissant les coudes puis tends.',array['Using a close grip, lift the EZ bar and hold it with your elbows in as you lie on the bench. Your arms should be perpendicular to the floor. This will be your starting position.','Keeping the upper arms stationary, lower the bar by allowing the elbows to flex. Inhale as you perform this portion of the movement. Pause once the bar is directly above the forehead.','Lift the bar back to the starting position by extending the elbow and exhaling.','Repeat.']::text[],array['EZ-Bar_Skullcrusher/0.jpg','EZ-Bar_Skullcrusher/1.jpg']::text[],true),
('Elbow_Circles','Elbow Circles','Elbow Circles','Mobilité','Épaules','Trapèzes',null,'Débutant',null,array['Sit or stand with your feet slightly apart.','Place your hands on your shoulders with your elbows at shoulder level and pointing out.','Slowly make a circle with your elbows. Breathe out as you start the circle and breathe in as you complete the circle.']::text[],array['Elbow_Circles/0.jpg','Elbow_Circles/1.jpg']::text[],false),
('Elbow_to_Knee','Elbow to Knee','Elbow to Knee','Force','Abdominaux',null,'Poids du corps','Débutant',null,array['Lie on the floor, crossing your right leg across your bent left knee. Clasp your hands behind your head, beginning with your shoulder blades on the ground. This will be your starting position.','Perform the motion by flexing the spine and rotating your torso to bring the left elbow to the right knee.','Return to the starting position and repeat the movement for the desired number of repetitions before switching sides.']::text[],array['Elbow_to_Knee/0.jpg','Elbow_to_Knee/1.jpg']::text[],false),
('Elbows_Back','Elbows Back','Elbows Back','Mobilité','Pectoraux','Épaules',null,'Débutant',null,array['Stand up straight.','Place both hands on your lower back, fingers pointing downward and elbows out.','Then gently pull your elbows back aiming to touch them together.']::text[],array['Elbows_Back/0.jpg','Elbows_Back/1.jpg']::text[],false),
('Elevated_Back_Lunge','Elevated Back Lunge','Elevated Back Lunge','Force','Quadriceps','Fessiers, Ischio-jambiers','Barre','Intermédiaire',null,array['Position a bar onto a rack at shoulder height loaded to an appropriate weight. Place a short, raised platform behind you.','Rack the bar onto your upper back, keeping your back arched and tight. Step onto your raised platform with both feet. This will be your starting position.','Begin by stepping backwards with one leg. Descend by flexing your hips and knees until your knee touches the floor.','Pause, and extend through the hips and knees to rise up, returning all the way to the starting position before alternating.']::text[],array['Elevated_Back_Lunge/0.jpg','Elevated_Back_Lunge/1.jpg']::text[],false),
('Elevated_Cable_Rows','Elevated Cable Rows','Elevated Cable Rows','Force','Dorsaux','Haut du dos, Trapèzes','Poulie','Intermédiaire',null,array['Get a platform of some sort (it can be an aerobics or calf raise platform) that is around 4-6 inches in height.','Place it on the seat of the cable row machine.','Sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.','Lean over as you keep the natural alignment of your back and grab the V-bar handles.','With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. This is the starting position of the exercise.','Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it until you touch the abdominals. Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard. Hold that contraction for a second and slowly go back to the original position while breathing in.','Repeat for the recommended amount of repetitions.']::text[],array['Elevated_Cable_Rows/0.jpg','Elevated_Cable_Rows/1.jpg']::text[],false),
('Elliptical_Trainer','Vélo elliptique','Elliptical Trainer','Cardio','Quadriceps','Mollets, Fessiers, Ischio-jambiers','Machine','Intermédiaire','Mouvement fluide bras et jambes, dos droit.',array['To begin, step onto the elliptical and select the desired option from the menu. Most ellipticals have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.','The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.']::text[],array['Elliptical_Trainer/0.jpg','Elliptical_Trainer/1.jpg']::text[],true),
('Exercise_Ball_Crunch','Exercise Ball Crunch','Exercise Ball Crunch','Force','Abdominaux',null,'Swiss ball','Débutant',null,array['Lie on an exercise ball with your lower back curvature pressed against the spherical surface of the ball. Your feet should be bent at the knee and pressed firmly against the floor. The upper torso should be hanging off the top of the ball. The arms should either be kept alongside the body or crossed on top of your chest as these positions avoid neck strains (as opposed to the hands behind the back of the head position).','Lower your torso into a stretch position keeping the neck stationary at all times. This will be your starting position.','With the hips stationary, flex the waist by contracting the abdominals and curl the shoulders and trunk upward until you feel a nice contraction on your abdominals. The arms should simply slide up the side of your legs if you have them at the side or just stay on top of your chest if you have them crossed. The lower back should always stay in contact with the ball. Exhale as you perform this movement and hold the contraction for a second.','As you inhale, go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],array['Exercise_Ball_Crunch/0.jpg','Exercise_Ball_Crunch/1.jpg']::text[],false),
('Exercise_Ball_Pull-In','Exercise Ball Pull-In','Exercise Ball Pull-In','Force','Abdominaux',null,'Swiss ball','Débutant',null,array['Place an exercise ball nearby and lay on the floor in front of it with your hands on the floor shoulder width apart in a push-up position.','Now place your lower shins on top of an exercise ball. Tip: At this point your legs should be fully extended with the shins on top of the ball and the upper body should be in a push-up type of position being supported by your two extended arms in front of you. This will be your starting position.','While keeping your back completely straight and the upper body stationary, pull your knees in towards your chest as you exhale, allowing the ball to roll forward under your ankles. Squeeze your abs and hold that position for a second.','Now slowly straighten your legs, rolling the ball back to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[],array['Exercise_Ball_Pull-In/0.jpg','Exercise_Ball_Pull-In/1.jpg']::text[],false),
('Extended_Range_One-Arm_Kettlebell_Floor_Press','Extended Range One-Arm Kettlebell Floor Press','Extended Range One-Arm Kettlebell Floor Press','Force','Pectoraux','Épaules, Triceps','Kettlebell','Débutant',null,array['Lie on the floor and position a kettlebell for one arm to press. The kettlebell should be held by the handle. The leg on the same side that you are pressing should be bent, with the knee crossing over the midline of the body.','Press the kettlebell by extending the elbow and adducting the arm, pressing it above your body. Return to the starting position.']::text[],array['Extended_Range_One-Arm_Kettlebell_Floor_Press/0.jpg','Extended_Range_One-Arm_Kettlebell_Floor_Press/1.jpg']::text[],false),
('External_Rotation','External Rotation','External Rotation','Force','Épaules',null,'Haltères','Débutant',null,array['Lie sideways on a flat bench with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.','Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm. Tip: Keep the arm parallel to your torso.','Now bend the elbow while keeping the upper arm stationary. In this manner, the forearm will be parallel to the floor and perpendicular to your torso (Tip: So the forearm will be directly in front of you). The upper arm will be stationary by your torso and should be parallel to the floor (aligned with your torso at all times). This will be your starting position.','As you breathe out, externally rotate your forearm so that the dumbbell is lifted up in a semicircle motion as you maintain the 90 degree angle bend between the upper arms and the forearm. You will continue this external rotation until the forearm is perpendicular to the floor and the torso pointing towards the ceiling. At this point you will hold the contraction for a second.','As you breathe in, slowly go back to the starting position.','Repeat for the recommended amount of repetitions and then switch to the other arm.']::text[],array['External_Rotation/0.jpg','External_Rotation/1.jpg']::text[],false),
('External_Rotation_with_Band','Rotation externe élastique','External Rotation with Band','Force','Épaules',null,'Élastiques','Débutant','Coude collé au corps à 90°, tourne l''avant-bras vers l''extérieur contre l''élastique.',array['Choke the band around a post. The band should be at the same height as your elbow. Stand with your left side to the band a couple of feet away.','Grasp the end of the band with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position.','With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching across the front of your torso. This will be your starting position.','Execute the movement by rotating your arm in a backhand motion, keeping your elbow in place.','Continue as far as you are able, pause, and then return to the starting position.']::text[],array['External_Rotation_with_Band/0.jpg','External_Rotation_with_Band/1.jpg']::text[],true),
('External_Rotation_with_Cable','External Rotation with Cable','External Rotation with Cable','Force','Épaules',null,'Poulie','Débutant',null,array['Adjust the cable to the same height as your elbow. Stand with your left side to the band a couple of feet away.','Grasp the handle with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position.','With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching across the front of your torso. This will be your starting position.','Execute the movement by rotating your arm in a backhand motion, keeping your elbow in place.']::text[],array['External_Rotation_with_Cable/0.jpg','External_Rotation_with_Cable/1.jpg']::text[],false),
('Face_Pull','Face pull','Face Pull','Force','Épaules','Haut du dos','Poulie','Intermédiaire','Corde à la poulie haute, tire vers le visage en écartant les mains et en ouvrant les coudes.',array['Facing a high pulley with a rope or dual handles attached, pull the weight directly towards your face, separating your hands as you do so. Keep your upper arms parallel to the ground.']::text[],array['Face_Pull/0.jpg','Face_Pull/1.jpg']::text[],true),
('Farmers_Walk','Marche du fermier','Farmer''s Walk','Strongman','Avant-bras','Abdominaux, Fessiers, Ischio-jambiers, Lombaires, Quadriceps, Trapèzes','Autre','Intermédiaire','Une charge lourde dans chaque main, marche buste droit, épaules basses, gainage serré.',array['There are various implements that can be used for the farmers walk. These can also be performed with heavy dumbbells or short bars if these implements aren''t available. Begin by standing between the implements.','After gripping the handles, lift them up by driving through your heels, keeping your back straight and your head up.','Walk taking short, quick steps, and don''t forget to breathe. Move for a given distance, typically 50-100 feet, as fast as possible.']::text[],array['Farmers_Walk/0.jpg','Farmers_Walk/1.jpg']::text[],true),
('Fast_Skipping','Fast Skipping','Fast Skipping','Explosivité','Quadriceps','Abducteurs, Adducteurs, Mollets, Fessiers, Ischio-jambiers','Poids du corps','Débutant',null,array['Start in a relaxed position with one leg slightly forward. This will be your starting position.','Skip by executing a step-hop pattern of right-right-step to left-left-step, and so on, alternating back and forth.','Perform fast skips by maintaining close contact with the ground and reduce air time, moving as quickly as possible.']::text[],array['Fast_Skipping/0.jpg','Fast_Skipping/1.jpg']::text[],false),
('Finger_Curls','Finger Curls','Finger Curls','Force','Avant-bras',null,'Barre','Débutant',null,array['Hold a barbell with both hands and your palms facing up; hands spaced about shoulder width.','Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart. This will be your starting position.','Lower the bar as far as possible by extending the fingers. Allowing the bar to roll down the hands, catch the bar with the final joint in the fingers.','Now curl bar up as high as possible by closing your hands while exhaling. Hold the contraction at the top.']::text[],array['Finger_Curls/0.jpg','Finger_Curls/1.jpg']::text[],false),
('Flat_Bench_Cable_Flyes','Flat Bench Cable Flyes','Flat Bench Cable Flyes','Force','Pectoraux',null,'Poulie','Intermédiaire',null,array['Position a flat bench between two low pulleys so that when you are laying on it, your chest will be lined up with the cable pulleys.','Lay flat on the bench and keep your feet on the ground.','Have someone hand you the handles on each hand. You will grab each single handle attachment with a palms up grip.','Extend your arms by your side with a slight bend on your elbows. Tip: You will keep this bend constant through the whole movement. Your arms should be parallel to the floor. This is your starting position.','Now start lifting the arms in a semi-circle motion directly in front of you by pulling the cables together until both hands meet at the top of the movement. Squeeze your chest as you perform this motion and breathe out during this movement. Also, hold the contraction for a second at the top. Tip: When performed correctly, at the top position of this movement, your arms should be perpendicular to your torso and the floor touching above your chest.','Slowly come back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],array['Flat_Bench_Cable_Flyes/0.jpg','Flat_Bench_Cable_Flyes/1.jpg']::text[],false),
('Flat_Bench_Leg_Pull-In','Flat Bench Leg Pull-In','Flat Bench Leg Pull-In','Force','Abdominaux',null,'Poids du corps','Débutant',null,array['Lie on an exercise mat or a flat bench with your legs off the end.','Place your hands either under your glutes with your palms down or by the sides holding on to the bench (or with palms down by the side on an exercise mat). Also extend your legs straight out. This will be your starting position.','Bend your knees and pull your upper thighs into your midsection as you breathe out. Continue this movement until your knees are near your chest. Hold the contracted position for a second.','As you breathe in, slowly return to the starting position.','Repeat for the recommended amount of repetitions.']::text[],array['Flat_Bench_Leg_Pull-In/0.jpg','Flat_Bench_Leg_Pull-In/1.jpg']::text[],false),
('Flat_Bench_Lying_Leg_Raise','Relevé de jambes allongé','Flat Bench Lying Leg Raise','Force','Abdominaux',null,'Poids du corps','Débutant','Allongé sur un banc, monte les jambes tendues à la verticale puis redescends lentement.',array['Lie with your back flat on a bench and your legs extended in front of you off the end.','Place your hands either under your glutes with your palms down or by the sides holding on to the bench. This will be your starting position.','As you keep your legs extended, straight as possible with your knees slightly bent but locked raise your legs until they make a 90-degree angle with the floor. Exhale as you perform this portion of the movement and hold the contraction at the top for a second.','Now, as you inhale, slowly lower your legs back down to the starting position.']::text[],array['Flat_Bench_Lying_Leg_Raise/0.jpg','Flat_Bench_Lying_Leg_Raise/1.jpg']::text[],true),
('Flexor_Incline_Dumbbell_Curls','Flexor Incline Dumbbell Curls','Flexor Incline Dumbbell Curls','Force','Biceps',null,'Haltères','Débutant',null,array['Hold the dumbbell towards the side farther from you so that you have more weight on the side closest to you. (This can be done for a good effect on all bicep dumbbell exercises). Now do a normal incline dumbbell curl, but keep your wrists as far back as possible so as to neutralize any stress that is placed on them.','Sit on an incline bench that is angled at 45-degrees while holding a dumbbell on each hand.','Let your arms hang down on your sides, with the elbows in, and turn the palms of your hands forward with the thumbs pointing away from the body. Tip: You will keep this hand position throughout the movement as there should not be any twisting of the hands as they come up. This will be your starting position.','Curl up the two dumbbells at the same time until your biceps are fully contracted and exhale. Tip: Do not swing the arms or use momentum. Keep a controlled motion at all times. Hold the contracted position for a second at the top.','As you inhale, slowly go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],array['Flexor_Incline_Dumbbell_Curls/0.jpg','Flexor_Incline_Dumbbell_Curls/1.jpg']::text[],false),
('Floor_Glute-Ham_Raise','Floor Glute-Ham Raise','Floor Glute-Ham Raise','Force','Ischio-jambiers','Mollets, Fessiers',null,'Intermédiaire',null,array['You can use a partner for this exercise or brace your feet under something stable.','Begin on your knees with your upper legs and torso upright. If using a partner, they will firmly hold your feet to keep you in position. This will be your starting position.','Lower yourself by extending at the knee, taking care to NOT flex the hips as you go forward.','Place your hands in front of you as you reach the floor. This movement is very difficult and you may be unable to do it unaided. Use your arms to lightly push off the floor to aid your return to the starting position.']::text[],array['Floor_Glute-Ham_Raise/0.jpg','Floor_Glute-Ham_Raise/1.jpg']::text[],false),
('Floor_Press','Floor Press','Floor Press','Force','Triceps','Pectoraux, Épaules','Barre','Intermédiaire',null,array['Adjust the j-hooks so they are at the appropriate height to rack the bar. Begin lying on the floor with your head near the end of a power rack. Keeping your shoulder blades pulled together; pull the bar off of the hooks.','Lower the bar towards the bottom of your chest or upper stomach, squeezing the bar and attempting to pull it apart as you do so. Ensure that you tuck your elbows throughout the movement. Lower the bar until your upper arm contacts the ground and pause, preventing any slamming or bouncing of the weight.','Press the bar back up as fast as you can, keeping the bar, your wrists, and elbows in line as you do so.']::text[],array['Floor_Press/0.jpg','Floor_Press/1.jpg']::text[],false),
('Floor_Press_with_Chains','Floor Press with Chains','Floor Press with Chains','Force','Triceps','Pectoraux, Épaules','Barre','Intermédiaire',null,array['Adjust the j-hooks so they are at the appropriate height to rack the bar. For this exercise, drape the chains directly over the end of the bar, trying to keep the ends away from the plates.','Begin lying on the floor with your head near the end of a power rack. Keeping your shoulder blades pulled together, pull the bar off of the hooks.','Lower the bar towards the bottom of your chest or upper stomach, squeezing the bar and attempting to pull it apart as you do so. Ensure that you tuck your elbows throughout the movement. Lower the bar until your upper arm contacts the ground and pause, preventing any slamming or bouncing of the weight.','Press the bar back up as fast as you can, keeping the bar, your wrists, and elbows in line as you do so.']::text[],array['Floor_Press_with_Chains/0.jpg','Floor_Press_with_Chains/1.jpg']::text[],false),
('Flutter_Kicks','Battements de jambes','Flutter Kicks','Force','Fessiers','Ischio-jambiers','Poids du corps','Débutant','Allongé, jambes tendues décollées, fais de petits battements alternés.',array['On a flat bench lie facedown with the hips on the edge of the bench, the legs straight with toes high off the floor and with the arms on top of the bench holding on to the front edge.','Squeeze your glutes and hamstrings and straighten the legs until they are level with the hips. This will be your starting position.','Start the movement by lifting the left leg higher than the right leg.','Then lower the left leg as you lift the right leg.','Continue alternating in this manner (as though you are doing a flutter kick in water) until you have done the recommended amount of repetitions for each leg. Make sure that you keep a controlled movement at all times. Tip: You will breathe normally as you perform this movement.']::text[],array['Flutter_Kicks/0.jpg','Flutter_Kicks/1.jpg']::text[],true),
('Foot-SMR','Foot-SMR','Foot-SMR','Mobilité','Mollets',null,'Autre','Intermédiaire',null,array['This exercise stretches the fascia of the muscles in the feet. Start off seated with your shoes removed. Using a foot roller or a similar object, such as a small section of pvc pipe, place your foot against the roller across the arch of your foot. This will be your starting position.','Press down firmly, rolling across the arch of your foot. Hold for 10-30 seconds, and then switch feet.']::text[],array['Foot-SMR/0.jpg','Foot-SMR/1.jpg']::text[],false),
('Forward_Drag_with_Press','Forward Drag with Press','Forward Drag with Press','Strongman','Pectoraux','Mollets, Fessiers, Ischio-jambiers, Quadriceps, Épaules, Triceps','Autre','Intermédiaire',null,array['Attach a dual handled chain or rope attachment to the sled. You should be facing away from the sled, holding a handle in each hand.','Begin the movement by moving forward for one step. Leaning forward, extend through the legs and hips to move, pausing with each step to extend through the elbows, pressing your hands forward. Step forward until you return to the start position prepared to press.']::text[],array['Forward_Drag_with_Press/0.jpg','Forward_Drag_with_Press/1.jpg']::text[],false),
('Frankenstein_Squat','Frankenstein Squat','Frankenstein Squat','Haltérophilie','Quadriceps','Abdominaux, Mollets, Fessiers, Ischio-jambiers','Barre','Intermédiaire',null,array['This drill teaches you the proper positioning of both the bar and your body during the clean and front squat.','Place the barbell on the front of the shoulders, releasing your grip and extending your arms out in front of you. The shoulders should be pushed forward to create a shelf, and the bar should be in contact with the throat. Ensure that you only move your shoulder blades forward; don''t round the thoracic spine.','Squat by flexing the knees and hips, sitting in between your legs. Keep the torso upright, the arms up, and the shoulders forward, and the bar should stay in place. Go to the bottom of the squat, until your hamstrings contact your calves.','Return to the upright position by driving through the front of the heel and extending the knees and hips.']::text[],array['Frankenstein_Squat/0.jpg','Frankenstein_Squat/1.jpg']::text[],false),
('Freehand_Jump_Squat','Squat sauté','Freehand Jump Squat','Force','Quadriceps','Mollets, Fessiers, Ischio-jambiers','Poids du corps','Intermédiaire','Descends en squat puis saute le plus haut possible, réception amortie.',array['Cross your arms over your chest.','With your head up and your back straight, position your feet at shoulder width.','Keeping your back straight and chest up, squat down as you inhale until your upper thighs are parallel, or lower, to the floor.','Now pressing mainly with the ball of your feet, jump straight up in the air as high as possible, using the thighs like springs. Exhale during this portion of the movement.','When you touch the floor again, immediately squat down and jump again.','Repeat for the recommended amount of repetitions.']::text[],array['Freehand_Jump_Squat/0.jpg','Freehand_Jump_Squat/1.jpg']::text[],true),
('Frog_Hops','Frog Hops','Frog Hops','Mobilité','Quadriceps','Mollets, Fessiers, Ischio-jambiers',null,'Intermédiaire',null,array['Stand with your hands behind your head, and squat down keeping your torso upright and your head up. This will be your starting position.','Jump forward several feet, avoiding jumping unnecessarily high. As your feet contact the ground, absorb the impact through your legs, and jump again. Repeat this action 5-10 times.']::text[],array['Frog_Hops/0.jpg','Frog_Hops/1.jpg']::text[],false),
('Frog_Sit-Ups','Frog Sit-Ups','Frog Sit-Ups','Force','Abdominaux',null,'Poids du corps','Intermédiaire',null,array['Lie with your back flat on the floor (or exercise mat) and your legs extended in front of you.','Now bend at the knees and place your outer thighs by the floor (or mat) as you make the soles of your feet touch each other.','Now try pushing both soles and bringing them up as near you as possible while you keep the outer thighs on the floor (or at least almost touching it). Tip: In this position your legs should create a diamond shape.','Now, cross your arms in front of you by touching the opposite shoulders. This will be your starting position.','As you exhale flatten your lower back to the floor while curling the torso upwards. Tip: This will be like performing the first 1/4 movement of a sit up. Hold at the top position for a second.','As you inhale, slowly lower back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],array['Frog_Sit-Ups/0.jpg','Frog_Sit-Ups/1.jpg']::text[],false),
('Front_Barbell_Squat','Front squat barre','Front Barbell Squat','Force','Quadriceps','Mollets, Fessiers, Ischio-jambiers','Barre','Avancé','Barre posée sur l''avant des épaules, coudes hauts. Descends buste droit puis remonte en gardant les coudes levés.',array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, bring your arms up under the bar while keeping the elbows high and the upper arm slightly above parallel to the floor. Rest the bar on top of the deltoids and cross your arms while grasping the bar for total control.','Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso.','Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).','Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.','Begin to raise the bar as you exhale by pushing the floor mainly with the middle of your foot as you straighten the legs again and go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],array['Front_Barbell_Squat/0.jpg','Front_Barbell_Squat/1.jpg']::text[],true),
('Front_Barbell_Squat_To_A_Bench','Front Barbell Squat To A Bench','Front Barbell Squat To A Bench','Force','Quadriceps','Mollets, Fessiers, Ischio-jambiers','Barre','Avancé',null,array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set a flat bench behind you and set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, bring your arms up under the bar while keeping the elbows high and the upper arm slightly above parallel to the floor. Rest the bar on top of the deltoids and cross your arms while grasping the bar for total control.','Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso.','Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).','Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until you touch the bench with your glutes. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.','Begin to raise the bar as you exhale by pushing the floor mainly with the heel of your foot as you straighten the legs again and go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],array['Front_Barbell_Squat_To_A_Bench/0.jpg','Front_Barbell_Squat_To_A_Bench/1.jpg']::text[],false),
('Front_Box_Jump','Saut sur box','Front Box Jump','Explosivité','Ischio-jambiers','Abducteurs, Adducteurs, Mollets, Fessiers, Quadriceps','Autre','Débutant','Élan des bras, saute sur la box et réceptionne en position de squat.',array['Begin with a box of an appropriate height 1-2 feet in front of you. Stand with your feet should width apart. This will be your starting position.','Perform a short squat in preparation for jumping, swinging your arms behind you.','Rebound out of this position, extending through the hips, knees, and ankles to jump as high as possible. Swing your arms forward and up.','Land on the box with the knees bent, absorbing the impact through the legs. You can jump from the box back to the ground, or preferably step down one leg at a time.']::text[],array['Front_Box_Jump/0.jpg','Front_Box_Jump/1.jpg']::text[],true),
('Front_Cable_Raise','Front Cable Raise','Front Cable Raise','Force','Épaules',null,'Poulie','Débutant',null,array['Select the weight on a low pulley machine and grasp the single hand cable attachment that is attached to the low pulley with your left hand.','Face away from the pulley and put your arm straight down with the hand cable attachment in front of your thighs at arms'' length with the palms of the hand facing your thighs. This will be your starting position.','While maintaining the torso stationary (no swinging), lift the left arm to the front with a slight bend on the elbow and the palms of the hand always faces down. Continue to go up until you arm is slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top.','Now as you inhale lower the arm back down slowly to the starting position.','Once all of the recommended amount of repetitions have been performed for this arm, switch arms and perform the exercise with the right one.']::text[],array['Front_Cable_Raise/0.jpg','Front_Cable_Raise/1.jpg']::text[],false),
('Front_Cone_Hops_or_hurdle_hops','Front Cone Hops (or hurdle hops)','Front Cone Hops (or hurdle hops)','Explosivité','Quadriceps','Abducteurs, Adducteurs, Mollets, Fessiers, Ischio-jambiers','Autre','Débutant',null,array['Set up a row of cones or other small barriers, placing them a few feet apart.','Stand in front of the first cone with your feet shoulder width apart. This will be your starting position.','Begin by jumping with both feet over the first cone, swinging both arms as you jump.','Absorb the impact of landing by bending the knees, rebounding out of the first leap by jumping over the next cone.','Continue until you have jumped over all of the cones.']::text[],array['Front_Cone_Hops_or_hurdle_hops/0.jpg','Front_Cone_Hops_or_hurdle_hops/1.jpg']::text[],false),
('Front_Dumbbell_Raise','Élévations frontales haltères','Front Dumbbell Raise','Force','Épaules',null,'Haltères','Débutant','Monte les haltères devant toi jusqu''à hauteur d''yeux puis redescends lentement.',array['Pick a couple of dumbbells and stand with a straight torso and the dumbbells on front of your thighs at arms length with the palms of the hand facing your thighs. This will be your starting position.','While maintaining the torso stationary (no swinging), lift the left dumbbell to the front with a slight bend on the elbow and the palms of the hands always facing down. Continue to go up until you arm is slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top. Inhale after the second pause.','Now lower the dumbbell back down slowly to the starting position as you simultaneously lift the right dumbbell.','Continue alternating in this fashion until all of the recommended amount of repetitions have been performed for each arm.']::text[],array['Front_Dumbbell_Raise/0.jpg','Front_Dumbbell_Raise/1.jpg']::text[],true),
('Front_Incline_Dumbbell_Raise','Front Incline Dumbbell Raise','Front Incline Dumbbell Raise','Force','Épaules',null,'Haltères','Débutant',null,array['Sit down on an incline bench with the incline set anywhere between 30 to 60 degrees while holding a dumbbell on each hand. Tip: You can change the angle to hit the muscle a little differently each time.','Extend your arms straight in front of you and have your palms facing down with the dumbbells raised about 1 inch above your thighs. This will be your starting position.','Slowly raise the dumbbells straight up until they are slightly above your shoulders, while keeping your elbows locked. Squeeze at the top for a second and make sure you breathe out during this portion of the movement. Tip: Keep your head resting down against the bench and your legs on the floor at all times.','Lower the arms back to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[],array['Front_Incline_Dumbbell_Raise/0.jpg','Front_Incline_Dumbbell_Raise/1.jpg']::text[],false),
('Front_Leg_Raises','Front Leg Raises','Front Leg Raises','Mobilité','Ischio-jambiers',null,'Poids du corps','Débutant',null,array['Stand next to a chair or other support, holding on with one hand.','Swing your leg forward, keeping the leg straight. Continue with a downward swing, bringing the leg as far back as your flexibility allows. Repeat 5-10 times, and then switch legs.']::text[],array['Front_Leg_Raises/0.jpg','Front_Leg_Raises/1.jpg']::text[],false)
