-- Base d'exercices pré-remplie, partie 1/3 (292 exercices) – source : free-exercise-db, domaine public.
-- Images servies depuis le CDN jsDelivr (voir src/lib/exercises.js).
on conflict (slug) do update set name = excluded.name, name_en = excluded.name_en, category = excluded.category, muscles = excluded.muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, level = excluded.level, description = excluded.description, instructions = excluded.instructions, images = excluded.images, featured = excluded.featured;
